#include "xml.h"
#include <cstdio>
#include <cstring>
#include <cctype>

namespace xml {

const char* errorName(int e)
{
    static const char* names[] = {
        "XML_SUCCESS",
        "XML_NO_ATTRIBUTE",
        "XML_WRONG_ATTRIBUTE_TYPE",
        "XML_ERROR_FILE_NOT_FOUND",
        "XML_ERROR_FILE_COULD_NOT_BE_OPENED",
        "XML_ERROR_FILE_READ_ERROR",
        "XML_ERROR_PARSING_ELEMENT",
        "XML_ERROR_PARSING_ATTRIBUTE",
        "XML_ERROR_PARSING_TEXT",
        "XML_ERROR_PARSING_CDATA",
        "XML_ERROR_PARSING_COMMENT",
        "XML_ERROR_PARSING_DECLARATION",
        "XML_ERROR_PARSING_UNKNOWN",
        "XML_ERROR_EMPTY_DOCUMENT",
        "XML_ERROR_MISMATCHED_ELEMENT",
        "XML_ERROR_PARSING",
        "XML_CAN_NOT_CONVERT_TEXT",
        "XML_NO_TEXT_NODE",
        "XML_ELEMENT_DEPTH_EXCEEDED"
    };
    if (e < 0 || e > 18)
        return "";
    return names[e];
}

const char* Node::attr(const char* name) const
{
    for (const Attribute& a : attributes)
        if (a.name == name)
            return a.value.c_str();
    return nullptr;
}

const Node* Node::firstChildElement(const char* name) const
{
    for (const auto& c : children) {
        if (c->type == ELEMENT && (!name || c->value == name))
            return c.get();
    }
    return nullptr;
}

std::vector<const Node*> Node::childElements() const
{
    std::vector<const Node*> ret;
    for (const auto& c : children)
        if (c->type == ELEMENT)
            ret.push_back(c.get());
    return ret;
}

const char* Node::getText() const
{
    if (!children.empty() && (children[0]->type == TEXT || children[0]->type == CDATA))
        return children[0]->value.c_str();
    return nullptr;
}

static bool isNameStartChar(unsigned char ch)
{
    if (ch >= 128)
        return true;
    if (std::isalpha(ch))
        return true;
    return ch == ':' || ch == '_';
}

static bool isNameChar(unsigned char ch)
{
    return isNameStartChar(ch) || std::isdigit(ch) || ch == '.' || ch == '-';
}

static bool isWhiteSpace(unsigned char ch)
{
    return ch < 128 && std::isspace(ch);
}

struct Parser {
    Document& doc;
    const char* buf;
    int curLine = 1;
    explicit Parser(Document& d, const char* b) : doc(d), buf(b) {}

    const char* skipWhiteSpace(const char* p) {
        while (isWhiteSpace((unsigned char)*p)) {
            if (*p == '\n')
                ++curLine;
            ++p;
        }
        return p;
    }

    const char* parseName(const char* p, std::string& out) {
        out.clear();
        if (!p || !*p)
            return nullptr;
        if (!isNameStartChar((unsigned char)*p))
            return nullptr;
        const char* start = p;
        ++p;
        while (*p && isNameChar((unsigned char)*p))
            ++p;
        out.assign(start, p - start);
        return p;
    }

    static std::string decodeEntities(const std::string& s) {
        std::string out;
        out.reserve(s.size());
        for (std::size_t i = 0; i < s.size(); ++i) {
            if (s[i] == '&') {
                static const struct { const char* pat; char ch; } ents[] = {
                    {"&quot;", '"'}, {"&amp;", '&'}, {"&apos;", '\''}, {"&lt;", '<'}, {"&gt;", '>'}
                };
                bool done = false;
                for (const auto& e : ents) {
                    const std::size_t l = std::strlen(e.pat);
                    if (s.compare(i, l, e.pat) == 0) {
                        out += e.ch;
                        i += l - 1;
                        done = true;
                        break;
                    }
                }
                if (!done && i + 1 < s.size() && s[i+1] == '#') {
                    std::size_t j = i + 2;
                    unsigned long code = 0;
                    bool hex = false;
                    if (j < s.size() && (s[j] == 'x' || s[j] == 'X')) {
                        hex = true;
                        ++j;
                    }
                    std::size_t startDigits = j;
                    while (j < s.size() && (hex ? std::isxdigit((unsigned char)s[j]) : std::isdigit((unsigned char)s[j]))) {
                        code = code * (hex ? 16 : 10) + (std::isdigit((unsigned char)s[j]) ? s[j]-'0' : (std::tolower(s[j])-'a'+10));
                        ++j;
                    }
                    if (j < s.size() && s[j] == ';' && j > startDigits) {
                        // utf-8 encode
                        if (code < 0x80) out += (char)code;
                        else if (code < 0x800) { out += (char)(0xC0 | (code >> 6)); out += (char)(0x80 | (code & 0x3F)); }
                        else if (code < 0x10000) { out += (char)(0xE0 | (code >> 12)); out += (char)(0x80 | ((code >> 6) & 0x3F)); out += (char)(0x80 | (code & 0x3F)); }
                        else { out += (char)(0xF0 | (code >> 18)); out += (char)(0x80 | ((code >> 12) & 0x3F)); out += (char)(0x80 | ((code >> 6) & 0x3F)); out += (char)(0x80 | (code & 0x3F)); }
                        i = j;
                        done = true;
                    }
                }
                if (!done)
                    out += '&';
            } else {
                out += s[i];
            }
        }
        return out;
    }

    static std::string normalizeNewlines(const std::string& s) {
        std::string out;
        out.reserve(s.size());
        for (std::size_t i = 0; i < s.size(); ++i) {
            if (s[i] == '\r') {
                out += '\n';
                if (i + 1 < s.size() && s[i+1] == '\n')
                    ++i;
            } else
                out += s[i];
        }
        return out;
    }

    // search for endTag, return pointer after it, or nullptr
    const char* parseText(const char* p, const char* endTag, std::string& out, bool entities) {
        const std::size_t len = std::strlen(endTag);
        const char* start = p;
        while (*p) {
            if (*p == endTag[0] && std::strncmp(p, endTag, len) == 0) {
                out.assign(start, p - start);
                out = normalizeNewlines(out);
                if (entities)
                    out = decodeEntities(out);
                return p + len;
            }
            if (*p == '\n')
                ++curLine;
            ++p;
        }
        return nullptr;
    }

    // Identify node type. Returns new p. node may be null.
    const char* identify(const char* p, std::unique_ptr<Node>& node) {
        const char* start = p;
        const int startLine = curLine;
        p = skipWhiteSpace(p);
        if (!*p) {
            node.reset();
            return p;
        }
        node.reset(new Node);
        if (std::strncmp(p, "<?", 2) == 0) {
            node->type = Node::DECLARATION;
            node->line = curLine;
            p += 2;
        } else if (std::strncmp(p, "<!--", 4) == 0) {
            node->type = Node::COMMENT;
            node->line = curLine;
            p += 4;
        } else if (std::strncmp(p, "<![CDATA[", 9) == 0) {
            node->type = Node::CDATA;
            node->line = curLine;
            p += 9;
        } else if (std::strncmp(p, "<!", 2) == 0) {
            node->type = Node::UNKNOWN;
            node->line = curLine;
            p += 2;
        } else if (*p == '<') {
            node->type = Node::ELEMENT;
            node->line = curLine;
            p += 1;
        } else {
            node->type = Node::TEXT;
            node->line = curLine;
            p = start;
            curLine = startLine;
        }
        return p;
    }

    enum Closing { OPEN, CLOSED, CLOSING };

    // returns p or nullptr
    const char* parseNode(Node* node, const char* p, std::string* parentEndTag, Closing& closing) {
        closing = OPEN;
        switch (node->type) {
        case Node::DECLARATION: {
            p = parseText(p, "?>", node->value, false);
            if (!p)
                doc.setError(XML_ERROR_PARSING_DECLARATION, node->line, "");
            return p;
        }
        case Node::COMMENT: {
            p = parseText(p, "-->", node->value, false);
            if (!p)
                doc.setError(XML_ERROR_PARSING_COMMENT, node->line, "");
            return p;
        }
        case Node::UNKNOWN: {
            p = parseText(p, ">", node->value, false);
            if (!p)
                doc.setError(XML_ERROR_PARSING_UNKNOWN, node->line, "");
            return p;
        }
        case Node::CDATA: {
            p = parseText(p, "]]>", node->value, false);
            if (!p)
                doc.setError(XML_ERROR_PARSING_CDATA, node->line, "");
            return p;
        }
        case Node::TEXT: {
            p = parseText(p, "<", node->value, true);
            if (p && *p)
                return p - 1;
            if (p && !*p)  // '<' was the last char
                return p - 1;
            doc.setError(XML_ERROR_PARSING_TEXT, node->line, "");
            return nullptr;
        }
        case Node::ELEMENT:
            break;
        }
        // element
        p = skipWhiteSpace(p);
        if (*p == '/') {
            closing = CLOSING;
            ++p;
        }
        p = parseName(p, node->value);
        if (!p || node->value.empty())
            return nullptr;
        // attributes
        while (p) {
            p = skipWhiteSpace(p);
            if (!*p) {
                doc.setError(XML_ERROR_PARSING_ELEMENT, node->line, "XMLElement name=" + node->value);
                return nullptr;
            }
            if (isNameStartChar((unsigned char)*p)) {
                Attribute a;
                const int attrLine = curLine;
                p = parseName(p, a.name);
                bool ok = p && *p;
                if (ok) {
                    p = skipWhiteSpace(p);
                    ok = (*p == '=');
                }
                if (ok) {
                    ++p;
                    p = skipWhiteSpace(p);
                    ok = (*p == '"' || *p == '\'');
                }
                if (ok) {
                    const char endTag[2] = { *p, 0 };
                    ++p;
                    p = parseText(p, endTag, a.value, true);
                    ok = p != nullptr;
                }
                if (ok && node->attr(a.name.c_str()))
                    ok = false;
                if (!ok) {
                    doc.setError(XML_ERROR_PARSING_ATTRIBUTE, attrLine, "XMLElement name=" + node->value);
                    return nullptr;
                }
                node->attributes.push_back(std::move(a));
            } else if (*p == '>') {
                ++p;
                break;
            } else if (*p == '/' && *(p+1) == '>') {
                closing = CLOSED;
                return p + 2;
            } else {
                doc.setError(XML_ERROR_PARSING_ELEMENT, node->line, "");
                return nullptr;
            }
        }
        if (!p || !*p || closing != OPEN)
            return p;
        return parseDeep(node, p, parentEndTag);
    }

    const char* parseDeep(Node* parent, const char* p, std::string* parentEndTag) {
        const bool isDocument = (parent == &doc.mRoot);
        while (p && *p) {
            std::unique_ptr<Node> node;
            p = identify(p, node);
            if (!node)
                break;
            const int initialLine = node->line;
            std::string endTag;
            Closing closing;
            p = parseNode(node.get(), p, &endTag, closing);
            if (!p) {
                if (!doc.mError)
                    doc.setError(XML_ERROR_PARSING, initialLine, "");
                break;
            }
            if (node->type == Node::DECLARATION) {
                bool wellLocated = false;
                if (isDocument) {
                    if (!parent->children.empty()) {
                        wellLocated = parent->children.front()->type == Node::DECLARATION &&
                                      parent->children.back()->type == Node::DECLARATION;
                    } else {
                        wellLocated = true;
                    }
                }
                if (!wellLocated) {
                    doc.setError(XML_ERROR_PARSING_DECLARATION, initialLine, "XMLDeclaration value=" + node->value);
                    break;
                }
            }
            if (node->type == Node::ELEMENT) {
                if (closing == CLOSING) {
                    if (parentEndTag)
                        *parentEndTag = node->value;
                    return p;
                }
                bool mismatch = false;
                if (endTag.empty()) {
                    if (closing == OPEN)
                        mismatch = true;
                } else {
                    if (closing != OPEN)
                        mismatch = true;
                    else if (endTag != node->value)
                        mismatch = true;
                }
                if (mismatch) {
                    doc.setError(XML_ERROR_MISMATCHED_ELEMENT, initialLine, "XMLElement name=" + node->value);
                    break;
                }
            }
            parent->children.push_back(std::move(node));
        }
        return nullptr;
    }
};

void Document::setError(int e, int line, const std::string& msg)
{
    mError = e;
    mErrorLine = line;
    mErrorMsg = msg;
}

std::string Document::errorStr() const
{
    if (!mError)
        return "";
    char buf[256];
    std::snprintf(buf, sizeof(buf), "Error=%s ErrorID=%d (0x%x) Line number=%d", xml::errorName(mError), mError, mError, mErrorLine);
    std::string ret = buf;
    if (!mErrorMsg.empty())
        ret += ": " + mErrorMsg;
    return ret;
}

int Document::parse(const std::string& data)
{
    mRoot = Node();
    mRoot.type = Node::ELEMENT;
    mError = 0;
    mErrorLine = 0;
    mErrorMsg.clear();
    std::string buf = data;
    const char* p = buf.c_str();
    Parser parser(*this, p);
    p = parser.skipWhiteSpace(p);
    // BOM
    if ((unsigned char)p[0] == 0xEF && (unsigned char)p[1] == 0xBB && (unsigned char)p[2] == 0xBF)
        p += 3;
    if (!*p) {
        setError(XML_ERROR_EMPTY_DOCUMENT, 0, "");
        return mError;
    }
    parser.parseDeep(&mRoot, p, nullptr);
    if (mError)
        mRoot.children.clear();
    return mError;
}

int Document::loadFile(const std::string& filename)
{
    mRoot = Node();
    mError = 0;
    mErrorLine = 0;
    mErrorMsg.clear();
    FILE* fp = std::fopen(filename.c_str(), "rb");
    if (!fp) {
        setError(XML_ERROR_FILE_NOT_FOUND, 0, "filename=" + filename);
        return mError;
    }
    std::fseek(fp, 0, SEEK_SET);
    if (std::fgetc(fp) == EOF && std::ferror(fp) != 0) {
        std::fclose(fp);
        setError(XML_ERROR_FILE_READ_ERROR, 0, "");
        return mError;
    }
    std::fseek(fp, 0, SEEK_END);
    const long size = std::ftell(fp);
    std::fseek(fp, 0, SEEK_SET);
    if (size <= 0) {
        std::fclose(fp);
        setError(XML_ERROR_EMPTY_DOCUMENT, 0, "");
        return mError;
    }
    std::string data;
    data.resize(size);
    const std::size_t read = std::fread(&data[0], 1, size, fp);
    std::fclose(fp);
    if (read != (std::size_t)size) {
        setError(XML_ERROR_FILE_READ_ERROR, 0, "");
        return mError;
    }
    // stop at embedded NUL like C string handling
    const std::size_t nul = data.find('\0');
    if (nul != std::string::npos)
        data.resize(nul);
    return parse(data);
}

const Node* Document::rootElement() const
{
    return mRoot.firstChildElement();
}

}
