#include "util.h"
#include <sys/stat.h>
#include <unistd.h>
#include <climits>
#include <cstring>
#include <algorithm>

namespace util {

std::string simplifyPath(std::string path)
{
    if (path.empty())
        return path;

    std::string::size_type pos;

    std::replace(path.begin(), path.end(), '\\', '/');

    const bool unc(path.compare(0, 2, "//") == 0);

    pos = 0;
    while ((pos = path.find("//", pos)) != std::string::npos)
        path.erase(pos, 1);

    pos = 0;
    while ((pos = path.find("./", pos)) != std::string::npos) {
        if (pos == 0 || path[pos - 1U] == '/')
            path.erase(pos, 2);
        else
            pos += 2;
    }

    if (endsWith(path, "/."))
        path.erase(path.size() - 1);

    pos = 1;
    while ((pos = path.find("/..", pos)) != std::string::npos) {
        if (pos + 3 < path.size() && path[pos + 3] != '/') {
            ++pos;
            continue;
        }
        std::string::size_type pos1 = path.rfind('/', pos - 1U);
        if (pos1 == std::string::npos)
            pos1 = 0;
        else
            pos1 += 1U;
        const std::string previousSubPath = path.substr(pos1, pos - pos1);
        if (previousSubPath == "..") {
            ++pos;
        } else {
            path.erase(pos1, pos - pos1 + 4);
            if (path.empty())
                path = ".";
            pos = (pos1 == 0) ? 1 : (pos1 - 1);
        }
    }

    if (unc)
        path = '/' + path;

    return path;
}

bool isDirectory(const std::string& path)
{
    struct stat st;
    return stat(path.c_str(), &st) == 0 && S_ISDIR(st.st_mode);
}

bool isFile(const std::string& path)
{
    struct stat st;
    return stat(path.c_str(), &st) == 0 && S_ISREG(st.st_mode);
}

bool exists(const std::string& path)
{
    struct stat st;
    return stat(path.c_str(), &st) == 0;
}

std::string getCurrentPath()
{
    char buf[PATH_MAX];
    if (getcwd(buf, sizeof(buf)))
        return buf;
    return "";
}

bool isAbsolute(const std::string& path)
{
    return !path.empty() && path[0] == '/';
}

std::string toLower(std::string s)
{
    for (char& c : s)
        c = (char)std::tolower((unsigned char)c);
    return s;
}

std::string getFilenameExtension(const std::string& path, bool lowercase)
{
    const std::string::size_type dotLocation = path.find_last_of('.');
    if (dotLocation == std::string::npos)
        return "";
    std::string extension = path.substr(dotLocation);
    if (lowercase)
        extension = toLower(extension);
    return extension;
}

std::string getPathFromFilename(const std::string& filename)
{
    const std::size_t pos = filename.find_last_of("\\/");
    if (pos != std::string::npos)
        return filename.substr(0, 1 + pos);
    return "";
}

std::string trim(const std::string& s, const char* ws)
{
    const std::string::size_type beg = s.find_first_not_of(ws);
    if (beg == std::string::npos)
        return "";
    const std::string::size_type end = s.find_last_not_of(ws);
    return s.substr(beg, end - beg + 1);
}

std::vector<std::string> split(const std::string& s, char sep)
{
    std::vector<std::string> ret;
    std::string::size_type start = 0;
    for (;;) {
        const std::string::size_type pos = s.find(sep, start);
        if (pos == std::string::npos) {
            ret.push_back(s.substr(start));
            break;
        }
        ret.push_back(s.substr(start, pos - start));
        start = pos + 1;
    }
    return ret;
}

std::string getAbsoluteFilePath(const std::string& path)
{
    if (path.empty())
        return "";
    char buf[PATH_MAX];
    if (realpath(path.c_str(), buf))
        return buf;
    if (isAbsolute(path))
        return simplifyPath(path);
    return simplifyPath(getCurrentPath() + "/" + path);
}

}
