// glob matching with * and ?
bool matchglob(const std::string& pattern, const std::string& name, bool caseInsensitive)
{
    const char* p = pattern.c_str();
    const char* n = name.c_str();
    std::vector<std::pair<const char*, const char*>> backtrack;

    for (;;) {
        bool matching = true;
        while (*p != '\0' && matching) {
            switch (*p) {
            case '*':
                // Step forward until we match the next character after *
                while (*n != '\0' && *n != p[1]) {
                    n++;
                }
                if (*n != '\0') {
                    // If this isn't the last possibility, save it for later
                    backtrack.emplace_back(p, n);
                }
                break;
            case '?':
                // Any character matches unless we're at the end of the name
                if (*n != '\0') {
                    n++;
                } else {
                    matching = false;
                }
                break;
            default:
                // Non-wildcard characters match literally
                if (*n == *p || (caseInsensitive && std::tolower((unsigned char)*n) == std::tolower((unsigned char)*p))) {
                    n++;
                } else if (*n == '\\' && *p == '/') {
                    n++;
                } else if (*n == '/' && *p == '\\') {
                    n++;
                } else {
                    matching = false;
                }
                break;
            }
            p++;
        }

        // If we haven't failed matching and we've reached the end of the name, then success
        if (matching && *n == '\0') {
            return true;
        }

        // If there are no other paths to try, then fail
        if (backtrack.empty()) {
            return false;
        }

        // Restore pointers from backtrack stack
        p = backtrack.back().first;
        n = backtrack.back().second;
        backtrack.pop_back();

        // Advance name pointer by one because the current position didn't work
        n++;
    }
}

bool Suppression::isMatch(const std::string& file, int line, const std::string& id, const std::string& symbolNames, std::size_t h, bool* matchedOut) const
{
    (void)matchedOut;
    if (hash > 0 && hash != h)
        return false;
    if (!errorId.empty() && !matchglob(errorId, id))
        return false;
    if (type == Type::macro) {
        return false;
    }
    if (!fileName.empty() && !matchglob(fileName, file))
        return false;
    if (type == Type::unique || type == Type::file) {
        if (lineNumber != NO_LINE && lineNumber != line) {
            if (!thisAndNextLine || lineNumber + 1 != line)
                return false;
        }
    } else if (type == Type::block) {
        if (line < lineBegin || line > lineEnd)
            return false;
    }
    if (!symbolName.empty()) {
        bool found = false;
        for (std::string::size_type pos = 0; pos < symbolNames.size();) {
            const std::string::size_type pos2 = symbolNames.find('\n', pos);
            std::string sn;
            if (pos2 == std::string::npos) {
                sn = symbolNames.substr(pos);
                pos = pos2;
            } else {
                sn = symbolNames.substr(pos, pos2 - pos);
                pos = pos2 + 1;
            }
            if (matchglob(symbolName, sn)) {
                found = true;
                break;
            }
        }
        if (!found)
            return false;
    }
    return true;
}
