        const int c = (unsigned char)s[pos++];
        if (c == '\n') ++line;
        return c;
    }
    void ungetc() {
        if (pos > 0) {
            --pos;
            if (pos < s.size() && s[pos] == '\n') --line;
        }
    }
    void skipWs() {
        for (;;) {
            const int c = getc();
            if (!(c == ' ' || c == '\t' || c == '\r' || c == '\n')) {
                ungetc();
                break;
            }
        }
    }
    bool expect(int expected) {
        skipWs();
        if (getc() != expected) {
            ungetc();
            return false;
        }
        return true;
    }
    bool match(const char* pattern) {
        for (const char* pi = pattern; *pi; ++pi) {
            if (getc() != (unsigned char)*pi) {
                ungetc();
                return false;
            }
        }
        return true;
    }
