int hexval(int c) {
    if ('0' <= c && c <= '9') return c - '0';
    if ('A' <= c && c <= 'F') return c - 'A' + 10;
    if ('a' <= c && c <= 'f') return c - 'a' + 10;
    return -1;
}

int parseQuadhex(Input& in) {
    int uni = 0;
    for (int i = 0; i < 4; i++) {
        const int h = hexval(in.getc());
        if (h == -1)
            return -1;
        uni = uni * 16 + h;
    }
    return uni;
}

bool parseCodepoint(std::string& out, Input& in) {
    int uni_ch;
    if ((uni_ch = parseQuadhex(in)) == -1)
        return false;
    if (0xd800 <= uni_ch && uni_ch <= 0xdfff) {
        if (0xdc00 <= uni_ch)
            return false;
        if (in.getc() != '\\' || in.getc() != 'u') {
            in.ungetc();
            return false;
        }
        const int second = parseQuadhex(in);
        if (!(0xdc00 <= second && second <= 0xdfff))
            return false;
        uni_ch = ((uni_ch - 0xd800) << 10) | ((second - 0xdc00) & 0x3ff);
        uni_ch += 0x10000;
    }
    if (uni_ch < 0x80) {
        out.push_back((char)uni_ch);
    } else {
        if (uni_ch < 0x800) {
            out.push_back((char)(0xc0 | (uni_ch >> 6)));
        } else {
            if (uni_ch < 0x10000) {
                out.push_back((char)(0xe0 | (uni_ch >> 12)));
            } else {
                out.push_back((char)(0xf0 | (uni_ch >> 18)));
                out.push_back((char)(0x80 | ((uni_ch >> 12) & 0x3f)));
            }
            out.push_back((char)(0x80 | ((uni_ch >> 6) & 0x3f)));
        }
        out.push_back((char)(0x80 | (uni_ch & 0x3f)));
    }
    return true;
}

bool parseString(std::string& out, Input& in) {
    for (;;) {
        const int ch = in.getc();
        if (ch < ' ') {
            in.ungetc();
            return false;
        } else if (ch == '"') {
            return true;
        } else if (ch == '\\') {
            const int c2 = in.getc();
            switch (c2) {
            case '"': out.push_back('"'); break;
            case '\\': out.push_back('\\'); break;
            case '/': out.push_back('/'); break;
            case 'b': out.push_back('\b'); break;
            case 'f': out.push_back('\f'); break;
            case 'n': out.push_back('\n'); break;
            case 'r': out.push_back('\r'); break;
            case 't': out.push_back('\t'); break;
            case 'u':
                if (!parseCodepoint(out, in))
                    return false;
                break;
            default:
                return false;
            }
        } else {
            out.push_back((char)ch);
        }
    }
}

bool parseValue(Value& out, Input& in, int depth);

bool parseArray(Value& out, Input& in, int depth) {
    out.setArray();
    if (in.expect(']'))
        return true;
    do {
        out.getArray().emplace_back();
        if (!parseValue(out.getArray().back(), in, depth + 1))
            return false;
    } while (in.expect(','));
    return in.expect(']');
}

bool parseObject(Value& out, Input& in, int depth) {
    out.setObject();
    if (in.expect('}'))
        return true;
    do {
        std::string key;
        if (!in.expect('"') || !parseString(key, in) || !in.expect(':'))
            return false;
        Value& v = out.getObject()[key];
        v = Value();
        if (!parseValue(v, in, depth + 1))
            return false;
    } while (in.expect(','));
    return in.expect('}');
}

std::string readNumber(Input& in) {
    std::string num_str;
    while (true) {
        const int ch = in.getc();
        if (('0' <= ch && ch <= '9') || ch == '+' || ch == '-' || ch == 'e' || ch == 'E') {
            num_str.push_back((char)ch);
        } else if (ch == '.') {
            num_str.push_back('.');
        } else {
            in.ungetc();
            break;
        }
    }
    return num_str;
}

bool parseValue(Value& out, Input& in, int depth) {
    if (depth > 100)
        return false;
    in.skipWs();
    const int ch = in.getc();
    switch (ch) {
    case 'n':
        if (in.match("ull")) { out.setNull(); return true; }
        return false;
    case 'f':
        if (in.match("alse")) { out.setBool(false); return true; }
        return false;
    case 't':
        if (in.match("rue")) { out.setBool(true); return true; }
        return false;
    case '"':
        out.setString();
        return parseString(out.getString(), in);
    case '[':
        return parseArray(out, in, depth);
    case '{':
        return parseObject(out, in, depth);
    default:
        if (('0' <= ch && ch <= '9') || ch == '-') {
