            if (endp == num_str.c_str() + num_str.size()) {
                out.setNumber(f);
                return true;
            }
            return false;
        }
        break;
    }
    in.ungetc();
    return false;
}
}

std::string parse(Value& out, const std::string& s)
{
    Input in(s);
    if (!parseValue(out, in, 0)) {
        return "syntax error at line " + std::to_string(in.line);
