            if (!parseEnableDisable(s, true, mSettings, errmsg)) {
                printError("--enable" + errmsg);
                return Result::Fail;
            }
        }

        else if (std::strncmp(argv[i], "--error-exitcode=", 17) == 0) {
            std::string err;
            if (!util::strToInt(std::string(argv[i] + 17), mSettings.exitCode, &err)) {
                printError("argument to '--error-exitcode=' is not valid - " + err + ".");
                return Result::Fail;
            }
        }

        else if (std::strcmp(argv[i], "--errorlist") == 0) {
            // handled in prescan
        }

        else if (std::strcmp(argv[i], "--exception-handling") == 0) {
            mSettings.exceptionHandling = true;
        }

        else if (std::strncmp(argv[i], "--exception-handling=", 21) == 0) {
            const std::string exceptionOutfilename = argv[i] + 21;
            if (exceptionOutfilename != "stderr" && exceptionOutfilename != "stdout") {
                printError("invalid '--exception-handling' argument");
                return Result::Fail;
            }
            mSettings.exceptionHandling = true;
            mSettings.exceptionOutput = exceptionOutfilename;
        }

        else if (std::strncmp(argv[i], "--executor=", 11) == 0) {
            const std::string type = argv[i] + 11;
            if (type == "auto") {
                executorAuto = true;
                mSettings.executor = Settings::Executor::Default;
            } else if (type == "thread") {
                executorAuto = false;
                mSettings.executor = Settings::Executor::Thread;
            } else if (type == "process") {
                executorAuto = false;
                mSettings.executor = Settings::Executor::Process;
            } else {
                printError("unknown executor: '" + type + "'.");
                return Result::Fail;
            }
        }

        else if (std::strncmp(argv[i], "--exitcode-suppressions=", 24) == 0) {
            const std::string filename = argv[i] + 24;
            std::ifstream f(filename);
            if (!f.is_open()) {
                printError("couldn't open the file: \"" + filename + "\".");
                return Result::Fail;
            }
            const std::string errmsg(mSuppressions.nofail.parseFile(f));
            if (!errmsg.empty()) {
                printError(errmsg);
                return Result::Fail;
            }
        }

        else if (std::strncmp(argv[i], "--file-filter=", 14) == 0) {
            const std::string filter = argv[i] + 14;
            if (filter == "-") {
                if (!addFilesToList(filter, mSettings.fileFilters)) {
                    printError("Failed: --file-filter=-");
                    return Result::Fail;
                }
            } else if (filter == "+") {
                inputAsFilter = true;
            } else {
                mSettings.fileFilters.emplace_back(filter);
            }
        }

        else if (std::strncmp(argv[i], "--file-list=", 12) == 0) {
            const std::string fileList = argv[i] + 12;
            if (!addFilesToList(fileList, mPathNames)) {
                printError("couldn't open the file: \"" + fileList + "\".");
                return Result::Fail;
            }
        }

        else if (std::strcmp(argv[i], "-f") == 0 || std::strcmp(argv[i], "--force") == 0)
            mSettings.force = true;

        else if (std::strcmp(argv[i], "--fsigned-char") == 0)
            mSettings.signedChar = 's';

        else if (std::strcmp(argv[i], "--funsigned-char") == 0)
            mSettings.signedChar = 'u';

        else if (std::strncmp(argv[i], "--include=", 10) == 0) {
            mSettings.userIncludes.emplace_back(util::fromNativeSeparators(argv[i] + 10));
        }

        else if (std::strncmp(argv[i], "--includes-file=", 16) == 0) {
            const std::string includesFile = argv[i] + 16;
            if (!addIncludePathsToList(includesFile, mSettings.includePaths)) {
                printError("unable to open includes file at '" + includesFile + "'");
                return Result::Fail;
            }
        }

        else if (std::strcmp(argv[i], "--inconclusive") == 0)
            mSettings.inconclusive = true;

        else if (std::strcmp(argv[i], "--inline-suppr") == 0)
            mSettings.inlineSuppressions = true;

        else if (std::strncmp(argv[i], "-i", 2) == 0) {
            std::string path;
            if (std::strcmp(argv[i], "-i") == 0) {
                ++i;
                if (i >= argc || argv[i][0] == '-') {
                    printError("argument to '-i' is missing.");
                    return Result::Fail;
                }
                path = argv[i];
            } else {
                path = 2 + argv[i];
            }
            if (!path.empty()) {
                path = removeQuotationMarks(std::move(path));
                path = util::simplifyPath(std::move(path));
                if (util::isDirectory(path) && !endsWith(path, '/'))
                    path += '/';
                mIgnoredPaths.emplace_back(std::move(path));
            }
        }

        else if (std::strncmp(argv[i], "-j", 2) == 0) {
            std::string numberString;
            if (std::strcmp(argv[i], "-j") == 0) {
                ++i;
                if (i >= argc || argv[i][0] == '-') {
                    printError("argument to '-j' is missing.");
                    return Result::Fail;
                }
                numberString = argv[i];
            } else {
                numberString = argv[i] + 2;
            }
            unsigned int tmp;
            std::string err;
            if (!util::strToInt(numberString, tmp, &err)) {
                printError("argument to '-j' is not valid - " + err + ".");
                return Result::Fail;
            }
            if (tmp == 0) {
                printError("argument for '-j' must be greater than 0.");
                return Result::Fail;
            }
            if (tmp > 1024) {
                printError("argument for '-j' is allowed to be 1024 at max.");
                return Result::Fail;
            }
            mSettings.jobs = tmp;
        }

        else if (std::strncmp(argv[i], "-l", 2) == 0) {
            std::string numberString;
            if (std::strcmp(argv[i], "-l") == 0) {
                ++i;
                if (i >= argc || argv[i][0] == '-') {
                    printError("argument to '-l' is missing.");
                    return Result::Fail;
                }
                numberString = argv[i];
            } else {
                numberString = argv[i] + 2;
            }
            int tmp;
            std::string err;
            if (!util::strToInt(numberString, tmp, &err)) {
                printError("argument to '-l' is not valid - " + err + ".");
                return Result::Fail;
            }
            mSettings.loadAverage = tmp;
        }

        else if (std::strcmp(argv[i], "-x") == 0 || std::strncmp(argv[i], "--language=", 11) == 0) {
            std::string str;
            if (argv[i][2]) {
                str = argv[i] + 11;
            } else {
                i++;
                if (i >= argc || argv[i][0] == '-') {
                    printError("no language given to '-x' option.");
                    return Result::Fail;
                }
                str = argv[i];
            }
            if (str == "c")
                mSettings.enforcedLang = "c";
            else if (str == "c++")
                mSettings.enforcedLang = "c++";
            else {
                printError("unknown language '" + str + "' enforced.");
                return Result::Fail;
            }
        }

        else if (std::strncmp(argv[i], "--library=", 10) == 0) {
            std::vector<std::string> libs = util::split(argv[i] + 10, ',');
            for (auto& l : libs) {
                if (l.empty()) {
                    printError("empty library specified.");
                    return Result::Fail;
                }
                mSettings.libraries.emplace_back(std::move(l));
            }
        }

        else if (std::strncmp(argv[i], "--max-configs=", 14) == 0) {
            int tmp;
            std::string err;
            if (!util::strToInt(std::string(argv[i] + 14), tmp, &err)) {
                printError("argument to '--max-configs=' is not valid - " + err + ".");
                return Result::Fail;
            }
            if (tmp < 1) {
                printError("argument to '--max-configs=' must be greater than 0.");
                return Result::Fail;
            }
            mSettings.maxConfigs = tmp;
            mSettings.force = false;
            maxconfigs = true;
        }

        else if (std::strncmp(argv[i], "--max-ctu-depth=", 16) == 0) {
            int temp = 0;
            std::string err;
            if (!util::strToInt(std::string(argv[i] + 16), temp, &err)) {
                printError("argument to '--max-ctu-depth=' is not valid - " + err + ".");
                return Result::Fail;
            }
            if (temp > 10) {
                printMessage("--max-ctu-depth is being capped at 10. This limitation will be removed in a future Cppcheck version.");
                temp = 10;
            }
            mSettings.maxCtuDepth = temp;
        }

        else if (std::strncmp(argv[i], "--max-template-recursion=", 25) == 0) {
            int temp = 0;
            std::string err;
            if (!util::strToInt(std::string(argv[i] + 25), temp, &err)) {
                printError("argument to '--max-template-recursion=' is not valid - " + err + ".");
                return Result::Fail;
            }
            mSettings.maxTemplateRecursion = temp;
        }

        else if (std::strcmp(argv[i], "--no-check-headers") == 0)
            mSettings.checkHeaders = false;

        else if (std::strcmp(argv[i], "--no-check-unused-templates") == 0)
            mSettings.checkUnusedTemplates = false;

        else if (std::strcmp(argv[i], "--no-cpp-header-probe") == 0)
            mSettings.cppHeaderProbe = false;

        else if (std::strcmp(argv[i], "--no-safety") == 0)
            mSettings.safety = false;

        else if (std::strncmp(argv[i], "--output-file=", 14) == 0) {
            mSettings.outputFile = util::simplifyPath(argv[i] + 14);
        }

        else if (std::strncmp(argv[i], "--output-format=", 16) == 0) {
            if (xmlOptionProvided) {
                printError("'--output-format' and '--xml...' may not be used in conjunction.");
                return Result::Fail;
            }
            const std::string format = argv[i] + 16;
            if (format == "sarif")
                mSettings.outputFormat = Settings::OutputFormat::sarif;
            else if (format == "xml")
                mSettings.outputFormat = Settings::OutputFormat::xml;
            else if (format == "xmlv2") {
                mSettings.outputFormat = Settings::OutputFormat::xml;
                mSettings.xml_version = 2;
            } else if (format == "xmlv3") {
                mSettings.outputFormat = Settings::OutputFormat::xml;
                mSettings.xml_version = 3;
            } else if (format == "text")
                mSettings.outputFormat = Settings::OutputFormat::text;
            else {
                printError("argument to '--output-format=' must be 'text', 'sarif', 'xml' (deprecated), 'xmlv2' or 'xmlv3'.");
                return Result::Fail;
            }
            outputFormatOptionProvided = true;
        }

        else if (std::strncmp(argv[i], "--performance-valueflow-max-if-count=", 37) == 0) {
            int temp = 0;
            std::string err;
            if (!util::strToInt(std::string(argv[i] + 37), temp, &err)) {
                printError("argument to '--performance-valueflow-max-if-count=' is not valid - " + err + ".");
                return Result::Fail;
            }
            if (temp < 0) {
                printError("argument to '--performance-valueflow-max-if-count=' needs to be a positive integer.");
                return Result::Fail;
            }
            mSettings.performanceValueFlowMaxIfCount = temp;
        }

        else if (std::strncmp(argv[i], "--performance-valueflow-max-time=", 33) == 0) {
            int temp = 0;
            std::string err;
            if (!util::strToInt(std::string(argv[i] + 33), temp, &err)) {
                printError("argument to '--performance-valueflow-max-time=' is not valid - " + err + ".");
                return Result::Fail;
            }
            if (temp < 0) {
                printError("argument to '--performance-valueflow-max-time=' needs to be a positive integer.");
                return Result::Fail;
            }
            mSettings.performanceValueFlowMaxTime = temp;
        }

        else if (std::strncmp(argv[i], "--platform=", 11) == 0) {
            const std::string p = argv[i] + 11;
            if (p.empty()) {
                printError("empty platform specified.");
                return Result::Fail;
            }
            platform = p;
        }

        else if (std::strncmp(argv[i], "--plist-output=", 15) == 0) {
            std::string path = util::simplifyPath(argv[i] + 15);
            if (path.empty())
                path = ".";
            const std::string plistOutput = util::fromNativeSeparators(path);
            if (!util::isDirectory(plistOutput)) {
                printError("plist folder does not exist: '" + plistOutput + "'.");
                return Result::Fail;
            }
            mSettings.plistOutput = plistOutput;
            if (!endsWith(mSettings.plistOutput, '/'))
                mSettings.plistOutput += '/';
            mSettings.outputFormat = Settings::OutputFormat::plist;
        }

        else if (std::strncmp(argv[i], "--project=", 10) == 0) {
            if (mProjectType != ProjectType::NONE) {
                printError("multiple --project options are not supported.");
                return Result::Fail;
