            const std::string projectFile = argv[i] + 10;
            if (!importProject(projectFile))
                return Result::Fail;
        }

        else if (std::strncmp(argv[i], "--project-configuration=", 24) == 0) {
            mVsConfiguration = argv[i] + 24;
            if (mVsConfiguration.empty()) {
                printError("--project-configuration parameter is empty.");
                return Result::Fail;
            }
            if (mProjectType != ProjectType::VS_SLN && mProjectType != ProjectType::VS_VCXPROJ) {
                printError("--project-configuration has no effect - no Visual Studio project provided.");
                return Result::Fail;
            }
        }

        else if (std::strcmp(argv[i], "-q") == 0 || std::strcmp(argv[i], "--quiet") == 0)
            mSettings.quiet = true;

        else if (std::strcmp(argv[i], "--report-progress") == 0)
            mSettings.reportProgress = 10;

        else if (std::strncmp(argv[i], "--report-progress=", 18) == 0) {
            int tmp;
            std::string err;
            if (!util::strToInt(std::string(argv[i] + 18), tmp, &err)) {
                printError("argument to '--report-progress=' is not valid - " + err + ".");
                return Result::Fail;
            }
            if (tmp < 0) {
                printError("argument to '--report-progress=' needs to be a positive integer.");
                return Result::Fail;
            }
            mSettings.reportProgress = tmp;
        }

        else if (std::strncmp(argv[i], "--report-type=", 14) == 0) {
            const std::string typeStr = argv[i] + 14;
            static const char* types[] = { "normal", "autosar", "cert-c-2016", "cert-cpp-2016", "misra-c-2012", "misra-c-2023", "misra-c-2025", "misra-cpp-2008", "misra-cpp-2023" };
            bool ok = false;
            for (const char* t : types)
                if (typeStr == t)
                    ok = true;
            if (!ok) {
                printError("Unknown report type '" + typeStr + "'");
                return Result::Fail;
            }
            mSettings.reportType = typeStr;
        }

        else if (std::strcmp(argv[i], "-rp") == 0 || std::strcmp(argv[i], "--relative-paths") == 0)
            mSettings.relativePaths = true;

        else if (std::strncmp(argv[i], "-rp=", 4) == 0 || std::strncmp(argv[i], "--relative-paths=", 17) == 0) {
            mSettings.relativePaths = true;
            const char* val = argv[i] + (argv[i][3] == '=' ? 4 : 17);
            if (*val) {
                std::string paths = val;
                for (;;) {
                    const std::string::size_type pos = paths.find(';');
                    if (pos == std::string::npos) {
                        mSettings.basePaths.emplace_back(util::fromNativeSeparators(paths));
                        break;
                    }
                    mSettings.basePaths.emplace_back(util::fromNativeSeparators(paths.substr(0, pos)));
                    paths.erase(0, pos + 1);
                }
            } else {
                printError("no paths specified for the '" + arg + "' option.");
                return Result::Fail;
            }
        }

        else if (std::strncmp(argv[i], "--rule=", 7) == 0) {
            printError("Option --rule cannot be used as Cppcheck has not been built with rules support.");
            return Result::Fail;
        }

        else if (std::strncmp(argv[i], "--rule-file=", 12) == 0) {
            printError("Option --rule-file cannot be used as Cppcheck has not been built with rules support.");
            return Result::Fail;
        }

        else if (std::strcmp(argv[i], "--safety") == 0)
            mSettings.safety = true;

        else if (std::strncmp(argv[i], "--showtime=", 11) == 0) {
            const std::string showtimeMode = argv[i] + 11;
            if (showtimeMode == "file" || showtimeMode == "file-total" || showtimeMode == "summary" ||
                showtimeMode == "top5_file" || showtimeMode == "top5_summary" || showtimeMode == "none")
                mSettings.showtime = showtimeMode;
            else if (showtimeMode.empty()) {
                printError("no mode provided for --showtime");
                return Result::Fail;
            } else {
                printError("unrecognized --showtime mode: '" + showtimeMode + "'. Supported modes: file, file-total, summary, top5_file, top5_summary.");
                return Result::Fail;
            }
        }

        else if (std::strncmp(argv[i], "--std=", 6) == 0) {
            const std::string std = argv[i] + 6;
            if (!setStandard(mSettings.standards, std)) {
                printError("unknown --std value '" + std + "'");
                return Result::Fail;
            }
        }

        else if (std::strncmp(argv[i], "--suppress=", 11) == 0) {
            const std::string suppression = argv[i] + 11;
            const std::string errmsg(mSuppressions.nomsg.addSuppressionLine(suppression));
            if (!errmsg.empty()) {
                printError(errmsg);
                return Result::Fail;
            }
        }

        else if (std::strncmp(argv[i], "--suppress-xml=", 15) == 0) {
            const char* filename = argv[i] + 15;
            const std::string errmsg(mSuppressions.nomsg.parseXmlFile(filename));
            if (!errmsg.empty()) {
                printError(errmsg);
                return Result::Fail;
            }
        }

        else if (std::strncmp(argv[i], "--suppressions-list=", 20) == 0) {
            const std::string filename = argv[i] + 20;
            std::ifstream f(filename);
            if (!f.is_open()) {
                printError("couldn't open the file: \"" + filename + "\".");
                return Result::Fail;
            }
            const std::string errmsg(mSuppressions.nomsg.parseFile(f));
            if (!errmsg.empty()) {
                printError(errmsg);
                return Result::Fail;
            }
        }

        else if (std::strncmp(argv[i], "--template=", 11) == 0) {
            mSettings.templateFormat = argv[i] + 11;
        }

        else if (std::strncmp(argv[i], "--template-location=", 20) == 0) {
            mSettings.templateLocation = argv[i] + 20;
        }

        else if (std::strncmp(argv[i], "--template-max-time=", 20) == 0) {
            std::size_t tmp;
            std::string err;
            if (!util::strToInt(std::string(argv[i] + 20), tmp, &err)) {
                printError("argument to '--template-max-time=' is not valid - " + err + ".");
                return Result::Fail;
            }
            mSettings.templateMaxTime = tmp;
        }

        else if (std::strncmp(argv[i], "--typedef-max-time=", 19) == 0) {
            std::size_t tmp;
            std::string err;
            if (!util::strToInt(std::string(argv[i] + 19), tmp, &err)) {
                printError("argument to '--typedef-max-time=' is not valid - " + err + ".");
                return Result::Fail;
            }
            mSettings.typedefMaxTime = tmp;
        }

        else if (std::strncmp(argv[i], "--valueflow-max-iterations=", 27) == 0) {
            std::size_t tmp;
            std::string err;
            if (!util::strToInt(std::string(argv[i] + 27), tmp, &err)) {
                printError("argument to '--valueflow-max-iterations=' is not valid - " + err + ".");
                return Result::Fail;
            }
            mSettings.valueFlowMaxIterations = tmp;
        }

        else if (std::strcmp(argv[i], "-v") == 0 || std::strcmp(argv[i], "--verbose") == 0)
            mSettings.verbose = true;

        else if (std::strcmp(argv[i], "--xml") == 0) {
            if (outputFormatOptionProvided) {
                printError("'--output-format' and '--xml...' may not be used in conjunction.");
                return Result::Fail;
            }
            mSettings.outputFormat = Settings::OutputFormat::xml;
            xmlOptionProvided = true;
        }

        else if (std::strncmp(argv[i], "--xml-version=", 14) == 0) {
            if (outputFormatOptionProvided) {
                printError("'--output-format' and '--xml...' may not be used in conjunction.");
                return Result::Fail;
            }
            int tmp;
            std::string err;
            if (!util::strToInt(std::string(argv[i] + 14), tmp, &err)) {
                printError("argument to '--xml-version=' is not valid - " + err + ".");
                return Result::Fail;
            }
            if (tmp != 2 && tmp != 3) {
                printError("'--xml-version' can only be 2 or 3.");
                return Result::Fail;
            }
            mSettings.xml_version = tmp;
            mSettings.outputFormat = Settings::OutputFormat::xml;
            xmlOptionProvided = true;
        }

        else {
            printError("unrecognized command line option: \"" + arg + "\".");
            return Result::Fail;
        }
    }

    // post-loop
    if (!executorAuto && mSettings.jobs == 1)
        printMessage("'--executor' has no effect as only a single job will be used.");
    mSettings.executorExplicit = !executorAuto;

    if (mSettings.unusedFunction && mSettings.jobs > 1 && mSettings.buildDir.empty())
        printMessage("unusedFunction check requires --cppcheck-build-dir to be active with -j.");

    if (mProjectType != ProjectType::NONE && !mPathNames.empty()) {
        printError("--project cannot be used in conjunction with source files.");
        return Result::Fail;
    }

    if (!platform.empty()) {
        if (!setPlatform(platform)) {
            printError("unrecognized platform: '" + platform + "'.");
            return Result::Fail;
        }
    }

    if (mSettings.force)
        mSettings.maxConfigs = 0x7fffffff;
    else if ((def || mSettings.preprocessOnly) && !maxconfigs)
        mSettings.maxConfigs = 1;

    if (inputAsFilter) {
        mSettings.fileFilters.insert(mSettings.fileFilters.end(), mPathNames.cbegin(), mPathNames.cend());
        mPathNames.clear();
    }

    if (mProjectType == ProjectType::CPPCHECK_GUI && !mGuiPathNames.empty())
        mPathNames = mGuiPathNames;

    if (!mFileSettings.empty()) {
        // remove ignored
        extern bool isPathIgnored(const std::vector<std::string>& ignored, const std::string& path);
        for (auto it = mFileSettings.begin(); it != mFileSettings.end();) {
            if (isPathIgnored(mIgnoredPaths, it->filename))
                it = mFileSettings.erase(it);
            else
                ++it;
        }
        if (mFileSettings.empty()) {
            printError("no C or C++ source files found.");
            printMessage("all paths were ignored");
            return Result::Fail;
        }
    }

    if (mSettings.debugnormal && mSettings.outputFormat == Settings::OutputFormat::xml && (mPathNames.size() > 1 || mFileSettings.size() > 1)) {
        printError("printing debug output in XML format does not support multiple input files.");
        return Result::Fail;
    }

    if (mSettings.basePaths.empty() && mSettings.relativePaths)
        mSettings.basePaths = mPathNames;

    if (mPathNames.empty() && mFileSettings.empty()) {
        printError("no C or C++ source files found.");
        return Result::Fail;
    }

    return Result::Success;
}
