using util::startsWith;
using util::endsWith;

void CmdLineParser::printError(const std::string& msg)
{
    std::cout << "cppcheck: error: " << msg << std::endl;
}

void CmdLineParser::printMessage(const std::string& msg)
{
    std::cout << "cppcheck: " << msg << std::endl;
}

void CmdLineParser::printRaw(const std::string& msg)
{
    std::cout << msg << std::endl;
}

static void printResource(const char* const* res)
{
    for (const char* const* p = res; *p; ++p)
        std::cout << *p;
    std::cout << std::flush;
}

static std::string removeQuotationMarks(std::string path)
{
    path.erase(std::remove(path.begin(), path.end(), '\"'), path.end());
    return path;
}

static bool addFilesToList(const std::string& fileList, std::vector<std::string>& pathNames)
{
    std::istream* files;
    std::ifstream infile;
    if (fileList == "-") {
        files = &std::cin;
    } else {
        infile.open(fileList);
        if (!infile.is_open())
            return false;
        files = &infile;
    }
    std::string fileName;
    while (std::getline(*files, fileName)) {
        if (!fileName.empty())
            pathNames.emplace_back(util::fromNativeSeparators(fileName));
    }
    return true;
}

static bool addIncludePathsToList(const std::string& fileList, std::list<std::string>& pathNames)
{
    std::ifstream files(fileList);
    if (!files)
        return false;
    std::string pathName;
    while (std::getline(files, pathName)) {
        if (!pathName.empty()) {
            pathName = util::fromNativeSeparators(pathName);
            if (!endsWith(pathName, '/'))
                pathName += '/';
            pathNames.emplace_back(std::move(pathName));
        }
    }
    return true;
}

static bool addPathsToSet(const std::string& fileName, std::set<std::string>& set)
{
    std::list<std::string> templist;
    if (!addIncludePathsToList(fileName, templist))
        return false;
    set.insert(templist.cbegin(), templist.cend());
    return true;
}

static bool parseEnableDisable(const std::string& str, bool enable, Settings& settings, std::string& errmsg)
{
    std::string::size_type pos = 0;
    // split
    std::vector<std::string> parts = util::split(str, ',');
    (void)pos;
    for (const std::string& s : parts) {
        if (s.empty()) {
            errmsg = "--enable parameter is empty";
            return false;
        }
        std::set<Severity> sev;
        bool uf = false, mi = false;
        if (s == "all") {
            sev = { Severity::warning, Severity::style, Severity::performance, Severity::portability, Severity::information };
            uf = mi = true;
        } else if (s == "warning") {
            sev = { Severity::warning };
        } else if (s == "style") {
            sev = { Severity::warning, Severity::style, Severity::performance, Severity::portability };
        } else if (s == "performance") {
            sev = { Severity::performance };
        } else if (s == "portability") {
            sev = { Severity::portability };
        } else if (s == "information") {
            sev = { Severity::information };
        } else if (s == "unusedFunction") {
            uf = true;
        } else if (s == "missingInclude") {
            mi = true;
        } else {
            errmsg = " parameter with the unknown name '" + s + "'";
            return false;
        }
        for (Severity v : sev) {
            if (enable)
                settings.severities.insert(v);
            else
                settings.severities.erase(v);
        }
        if (uf)
            settings.unusedFunction = enable;
        if (mi)
            settings.missingInclude = enable;
    }
    return true;
}

static bool setStandard(Standards& standards, const std::string& str)
{
    static const std::pair<const char*, Standards::cstd_t> cstds[] = {
        {"c89", Standards::C89}, {"c90", Standards::C89}, {"iso9899:1990", Standards::C89}, {"iso9899:199409", Standards::C89},
        {"gnu89", Standards::C89}, {"gnu90", Standards::C89},
        {"c99", Standards::C99}, {"c9x", Standards::C99}, {"iso9899:1999", Standards::C99}, {"iso9899:199x", Standards::C99},
        {"gnu99", Standards::C99}, {"gnu9x", Standards::C99},
        {"c11", Standards::C11}, {"c1x", Standards::C11}, {"iso9899:2011", Standards::C11}, {"gnu11", Standards::C11}, {"gnu1x", Standards::C11},
        {"c17", Standards::C17}, {"c18", Standards::C17}, {"iso9899:2017", Standards::C17}, {"iso9899:2018", Standards::C17},
        {"gnu17", Standards::C17}, {"gnu18", Standards::C17},
        {"c23", Standards::C23}, {"c2x", Standards::C23}, {"gnu23", Standards::C23}, {"gnu2x", Standards::C23},
        {"c2y", Standards::C2Y}, {"gnu2y", Standards::C2Y},
    };
    static const std::pair<const char*, Standards::cppstd_t> cppstds[] = {
        {"c++98", Standards::CPP03}, {"c++03", Standards::CPP03}, {"gnu++98", Standards::CPP03}, {"gnu++03", Standards::CPP03},
        {"c++11", Standards::CPP11}, {"c++0x", Standards::CPP11}, {"gnu++11", Standards::CPP11}, {"gnu++0x", Standards::CPP11},
        {"c++14", Standards::CPP14}, {"c++1y", Standards::CPP14}, {"gnu++14", Standards::CPP14}, {"gnu++1y", Standards::CPP14},
        {"c++17", Standards::CPP17}, {"c++1z", Standards::CPP17}, {"gnu++17", Standards::CPP17}, {"gnu++1z", Standards::CPP17},
        {"c++20", Standards::CPP20}, {"c++2a", Standards::CPP20}, {"gnu++20", Standards::CPP20}, {"gnu++2a", Standards::CPP20},
        {"c++23", Standards::CPP23}, {"c++2b", Standards::CPP23}, {"gnu++23", Standards::CPP23}, {"gnu++2b", Standards::CPP23},
        {"c++26", Standards::CPP26}, {"c++2c", Standards::CPP26}, {"gnu++26", Standards::CPP26}, {"gnu++2c", Standards::CPP26},
    };
    for (const auto& c : cstds) {
        if (str == c.first) {
            standards.c = c.second;
            standards.stdValueC = str;
            return true;
        }
    }
    for (const auto& c : cppstds) {
        if (str == c.first) {
            standards.cpp = c.second;
            standards.stdValueCPP = str;
            return true;
        }
    }
    return false;
}

bool CmdLineParser::loadCppcheckCfg()
{
    const bool debug = mSettings.debuglookup || mSettings.debuglookupConfig;
    std::vector<std::string> paths;
    paths.push_back(std::string(FILESDIR) + "/cppcheck.cfg");
    paths.push_back(mSettings.exeDir + "cppcheck.cfg");
    for (const std::string& p : paths) {
        if (debug)
            std::cout << "looking for '" << p << "'" << std::endl;
        std::ifstream fin(p);
        if (fin.is_open()) {
            // configuration found
            std::stringstream ss;
            ss << fin.rdbuf();
            json::Value v;
            const std::string err = json::parse(v, ss.str());
            if (!err.empty()) {
                printError("could not load cppcheck.cfg - not a valid JSON - " + err);
                return false;
            }
            return true;
        }
    }
    if (debug)
        std::cout << "no configuration found" << std::endl;
    return true;
}

bool CmdLineParser::fillSettingsFromArgs(int argc, const char* const argv[], bool& exitNow)
{
    exitNow = false;
    const Result result = parseFromArgs(argc, argv);
    switch (result) {
    case Result::Success:
        break;
    case Result::Exit:
        exitNow = true;
        return true;
    case Result::Fail:
        return false;
    }

    if (!loadLibraries())
        return false;

    if (!loadAddons())
        return false;

    // Check that all include paths exist
    for (auto iter = mSettings.includePaths.begin(); iter != mSettings.includePaths.end();) {
        const std::string path(*iter);
        if (util::isDirectory(path))
            ++iter;
        else {
            if (mSettings.debugwarnings)
                std::cout << "(debug) Ignoring non-existing include path: " << path << std::endl;
            iter = mSettings.includePaths.erase(iter);
        }
    }
    return true;
}

CmdLineParser::Result CmdLineParser::parseFromArgs(int argc, const char* const argv[])
{
    // prescan debug lookups
    for (int i = 1; i < argc; i++) {
        if (std::strcmp(argv[i], "--debug-lookup") == 0)
            mSettings.debuglookup = true;
        else if (std::strncmp(argv[i], "--debug-lookup=", 15) == 0) {
            const std::string lookup = argv[i] + 15;
            if (lookup == "all")
                mSettings.debuglookup = true;
            else if (lookup == "addon")
                mSettings.debuglookupAddon = true;
            else if (lookup == "config")
                mSettings.debuglookupConfig = true;
            else if (lookup == "library")
                mSettings.debuglookupLibrary = true;
            else if (lookup == "platform")
                mSettings.debuglookupPlatform = true;
            else {
                printError("unknown lookup '" + lookup + "'");
                return Result::Fail;
            }
        }
    }

    if (!loadCppcheckCfg())
        return Result::Fail;

    // exclusive options
    for (int i = 1; i < argc; i++) {
        if (std::strcmp(argv[i], "--doc") == 0) {
            printResource(RES_DOC);
            return Result::Exit;
        }
        if (std::strcmp(argv[i], "--errorlist") == 0) {
            printResource(RES_ERRORLIST);
            return Result::Exit;
        }
        if (std::strcmp(argv[i], "-h") == 0 || std::strcmp(argv[i], "--help") == 0) {
            printResource(RES_HELP);
            return Result::Exit;
        }
        if (std::strcmp(argv[i], "--filesdir") == 0) {
            std::cout << FILESDIR << std::endl;
            return Result::Exit;
        }
        if (std::strcmp(argv[i], "--version") == 0) {
            std::cout << "Cppcheck " << CPPCHECK_VERSION_STRING << std::endl;
            return Result::Exit;
        }
    }

    bool def = false;
    bool maxconfigs = false;
    bool xmlOptionProvided = false;
    bool outputFormatOptionProvided = false;
    bool inputAsFilter = false;
    std::string platform;
    bool executorAuto = true;

    for (int i = 1; i < argc; i++) {
        if (argv[i][0] != '-') {
            mPathNames.emplace_back(util::fromNativeSeparators(removeQuotationMarks(argv[i])));
            continue;
        }
        const std::string arg = argv[i];

        // User define
        if (std::strncmp(argv[i], "-D", 2) == 0) {
            std::string define;
            if (std::strcmp(argv[i], "-D") == 0) {
                ++i;
                if (i >= argc || argv[i][0] == '-') {
                    printError("argument to '-D' is missing.");
                    return Result::Fail;
                }
                define = argv[i];
            } else {
                define = 2 + argv[i];
            }
            if (define.find('=') == std::string::npos)
                define += "=1";
            if (!mSettings.userDefines.empty())
                mSettings.userDefines += ";";
            mSettings.userDefines += define;
            def = true;
        }

        // -E
        else if (std::strcmp(argv[i], "-E") == 0) {
            mSettings.preprocessOnly = true;
            mSettings.quiet = true;
        }

        // Include paths
        else if (std::strncmp(argv[i], "-I", 2) == 0) {
            std::string path;
            if (std::strcmp(argv[i], "-I") == 0) {
                ++i;
                if (i >= argc || argv[i][0] == '-') {
                    printError("argument to '-I' is missing.");
                    return Result::Fail;
                }
                path = argv[i];
            } else {
                path = 2 + argv[i];
            }
            path = removeQuotationMarks(std::move(path));
            path = util::fromNativeSeparators(std::move(path));
            if (!endsWith(path, '/'))
                path += '/';
            mSettings.includePaths.emplace_back(std::move(path));
        }

        // User undef
        else if (std::strncmp(argv[i], "-U", 2) == 0) {
            std::string undef;
            if (std::strcmp(argv[i], "-U") == 0) {
                ++i;
                if (i >= argc || argv[i][0] == '-') {
                    printError("argument to '-U' is missing.");
                    return Result::Fail;
                }
                undef = argv[i];
            } else {
                undef = 2 + argv[i];
            }
            mSettings.userUndefs.insert(std::move(undef));
        }

        else if (std::strncmp(argv[i], "--addon=", 8) == 0)
            mSettings.addons.emplace(argv[i] + 8);

        else if (std::strncmp(argv[i], "--addon-python=", 15) == 0)
            mSettings.addonPython.assign(argv[i] + 15);

        else if (std::strcmp(argv[i], "--check-config") == 0)
            mSettings.checkConfiguration = true;

        else if (std::strcmp(argv[i], "--check-headers") == 0)
            mSettings.checkHeaders = true;

        else if (std::strncmp(argv[i], "--check-level=", 14) == 0) {
            const std::string level = argv[i] + 14;
            if (level == "reduced")
                mSettings.checkLevel = Settings::CheckLevel::reduced;
            else if (level == "normal")
                mSettings.checkLevel = Settings::CheckLevel::normal;
            else if (level == "exhaustive")
                mSettings.checkLevel = Settings::CheckLevel::exhaustive;
            else {
                printError("unknown '--check-level' value '" + level + "'.");
                return Result::Fail;
            }
        }

        else if (std::strcmp(argv[i], "--check-library") == 0)
            mSettings.checkLibrary = true;

        else if (std::strcmp(argv[i], "--check-unused-templates") == 0)
            mSettings.checkUnusedTemplates = true;

        else if (std::strncmp(argv[i], "--checkers-report=", 18) == 0)
            mSettings.checkersReportFilename = argv[i] + 18;

        else if (std::strcmp(argv[i], "--clang") == 0 || std::strncmp(argv[i], "--clang=", 8) == 0) {
            mSettings.clang = true;
            if (std::strncmp(argv[i], "--clang=", 8) == 0)
                mSettings.clangExecutable = argv[i] + 8;
        }

        else if (std::strncmp(argv[i], "--config-exclude=", 17) == 0) {
            mSettings.configExcludePaths.insert(util::fromNativeSeparators(argv[i] + 17));
        }

        else if (std::strncmp(argv[i], "--config-excludes-file=", 23) == 0) {
            const std::string filename = argv[i] + 23;
            if (!addPathsToSet(filename, mSettings.configExcludePaths)) {
                printError("unable to open config excludes file at '" + filename + "'");
                return Result::Fail;
            }
        }

        else if (std::strncmp(argv[i], "--cppcheck-build-dir=", 21) == 0) {
            std::string path = util::fromNativeSeparators(argv[i] + 21);
            if (path.empty()) {
                printError("no path has been specified for --cppcheck-build-dir");
                return Result::Fail;
            }
            if (endsWith(path, '/'))
                path.pop_back();
            mSettings.buildDir = path;
            if (!util::isDirectory(mSettings.buildDir)) {
                printError("Directory '" + mSettings.buildDir + "' specified by --cppcheck-build-dir argument has to be existent.");
                return Result::Fail;
            }
        }

        else if (std::strcmp(argv[i], "--cpp-header-probe") == 0)
            mSettings.cppHeaderProbe = true;

        else if (std::strcmp(argv[i], "--debug") == 0 || std::strcmp(argv[i], "--debug-normal") == 0)
            mSettings.debugnormal = true;

        else if (std::strcmp(argv[i], "--debug-ast") == 0)
            mSettings.debugast = true;

        else if (std::strcmp(argv[i], "--debug-clang-output") == 0)
            mSettings.debugClangOutput = true;

        else if (std::strcmp(argv[i], "--debug-ignore") == 0)
            mSettings.debugignore = true;

        else if (std::strcmp(argv[i], "--debug-lookup") == 0 || std::strncmp(argv[i], "--debug-lookup=", 15) == 0) {
            // handled in prescan
        }

        else if (std::strcmp(argv[i], "--debug-simplified") == 0)
            mSettings.debugsimplified = true;

        else if (std::strcmp(argv[i], "--debug-symdb") == 0)
            mSettings.debugsymdb = true;

        else if (std::strcmp(argv[i], "--debug-template") == 0)
            mSettings.debugtemplate = true;

        else if (std::strcmp(argv[i], "--debug-valueflow") == 0)
            mSettings.debugvalueflow = true;

        else if (std::strcmp(argv[i], "--debug-warnings") == 0)
            mSettings.debugwarnings = true;

        else if (std::strncmp(argv[i], "--disable=", 10) == 0) {
            const std::string s = argv[i] + 10;
            if (s.empty()) {
                printError("--disable parameter is empty");
                return Result::Fail;
            }
            std::string errmsg;
            if (!parseEnableDisable(s, false, mSettings, errmsg)) {
                printError("--disable" + errmsg);
                return Result::Fail;
            }
        }

        else if (std::strcmp(argv[i], "--dump") == 0)
            mSettings.dump = true;

        else if (std::strncmp(argv[i], "--enable=", 9) == 0) {
            const std::string s = argv[i] + 9;
            if (s.empty()) {
                printError("--enable parameter is empty");
                return Result::Fail;
            }
            std::string errmsg;
            if (!parseEnableDisable(s, true, mSettings, errmsg)) {
                printError("--enable" + errmsg);
                return Result::Fail;
            }
        }

        else if (std::strncmp(argv[i], "--error-exitcode=", 17) == 0) {
            std::string err;
            if (!util::strToInt(std::string(argv[i] + 17), mSettings.exitCode, &err)) {
                printError("argument to '--error-exitcode=' is not valid - " + err + ".");
                return Result::Fail;
            }
        }

        else if (std::strcmp(argv[i], "--errorlist") == 0) {
            // handled in prescan
        }

        else if (std::strcmp(argv[i], "--exception-handling") == 0) {
            mSettings.exceptionHandling = true;
        }

        else if (std::strncmp(argv[i], "--exception-handling=", 21) == 0) {
            const std::string exceptionOutfilename = argv[i] + 21;
            if (exceptionOutfilename != "stderr" && exceptionOutfilename != "stdout") {
                printError("invalid '--exception-handling' argument");
