            mSettings.exceptionHandling = true;
            mSettings.exceptionOutput = exceptionOutfilename;
        }

        else if (std::strncmp(argv[i], "--executor=", 11) == 0) {
            const std::string type = argv[i] + 11;
            if (type == "auto") {
                executorAuto = true;
                mSettings.executor = Settings::Executor::Default;
            } else if (type == "thread") {
                executorAuto = false;
                mSettings.executor = Settings::Executor::Thread;
            } else if (type == "process") {
                executorAuto = false;
                mSettings.executor = Settings::Executor::Process;
            } else {
                printError("unknown executor: '" + type + "'.");
                return Result::Fail;
            }
        }

        else if (std::strncmp(argv[i], "--exitcode-suppressions=", 24) == 0) {
            const std::string filename = argv[i] + 24;
            std::ifstream f(filename);
            if (!f.is_open()) {
