static std::string readFileContents(const std::string& filename)
{
    std::ifstream fin(filename);
    std::string str((std::istreambuf_iterator<char>(fin)), std::istreambuf_iterator<char>());
    return str;
}

bool CmdLineParser::importProject(const std::string& projectFile)
{
    mProjectFile = projectFile;
    std::ifstream fin(projectFile);
    if (!fin.is_open()) {
        mProjectType = ProjectType::MISSING;
        printError("failed to open project '" + projectFile + "'. The file does not exist.");
        return false;
    }
    fin.close();

    bool ok = false;
    if (endsWith(projectFile, ".json")) {
        mProjectType = ProjectType::COMPILE_DB;
        ok = importCompileCommands(projectFile, readFileContents(projectFile));
    } else if (endsWith(projectFile, ".sln")) {
        mProjectType = ProjectType::VS_SLN;
        ok = importVsSln(projectFile);
    } else if (endsWith(projectFile, ".vcxproj")) {
        mProjectType = ProjectType::VS_VCXPROJ;
        ok = importVcxproj(projectFile);
    } else if (endsWith(projectFile, ".bpr")) {
        mProjectType = ProjectType::BORLAND;
        ok = importBcb6(projectFile);
    } else if (endsWith(projectFile, ".cppcheck")) {
        mProjectType = ProjectType::CPPCHECK_GUI;
        ok = importGuiProject(projectFile);
    } else {
        mProjectType = ProjectType::UNKNOWN;
        printError("failed to load project '" + projectFile + "'. The format is unknown.");
        return false;
    }
    if (!ok) {
        printError("failed to load project '" + projectFile + "'. An error occurred.");
        return false;
    }
    return true;
}

// split a command line into arguments (simple shell-like)
static std::vector<std::string> splitCommand(const std::string& cmd)
{
    std::vector<std::string> ret;
    std::string cur;
    bool inArg = false;
    char quote = 0;
    for (std::size_t i = 0; i < cmd.size(); ++i) {
        const char c = cmd[i];
        if (quote) {
            if (c == quote)
                quote = 0;
            else if (c == '\\' && quote == '"' && i + 1 < cmd.size() && (cmd[i+1] == '"' || cmd[i+1] == '\\'))
                cur += cmd[++i];
            else
                cur += c;
        } else if (c == '"' || c == '\'') {
            quote = c;
            inArg = true;
        } else if (c == '\\' && i + 1 < cmd.size()) {
            cur += cmd[++i];
            inArg = true;
        } else if (c == ' ' || c == '\t' || c == '\n') {
            if (inArg) {
                ret.push_back(cur);
                cur.clear();
                inArg = false;
            }
        } else {
            cur += c;
            inArg = true;
        }
    }
    if (inArg)
        ret.push_back(cur);
    return ret;
}

static void parseCommandArgs(FileSettings& fs, const std::vector<std::string>& args, const std::string& directory)
{
    std::string defs;
    for (std::size_t i = 1; i < args.size(); ++i) {
        const std::string& a = args[i];
        auto value = [&](const char* opt) -> std::string {
            const std::size_t l = std::strlen(opt);
            if (a.size() > l)
                return a.substr(l);
            if (i + 1 < args.size())
                return args[++i];
            return "";
        };
        if (startsWith(a, "-D")) {
            std::string d = value("-D");
            if (d.find('=') == std::string::npos)
                d += "=1";
            if (!defs.empty())
                defs += ";";
            defs += d;
        } else if (startsWith(a, "-U")) {
            fs.undefs.insert(value("-U"));
        } else if (startsWith(a, "-I")) {
            std::string p = value("-I");
            if (!util::isAbsolute(p))
                p = directory + p;
            p = util::simplifyPath(p);
            if (!endsWith(p, '/'))
                p += '/';
            fs.includePaths.push_back(p);
        } else if (startsWith(a, "-std=")) {
            fs.standard = a.substr(5);
        } else if (a == "-isystem") {
            std::string p = value("-isystem");
            if (!util::isAbsolute(p))
                p = directory + p;
            p = util::simplifyPath(p);
            if (!endsWith(p, '/'))
                p += '/';
            fs.systemIncludePaths.push_back(p);
        }
    }
    fs.defines = defs;
}

bool CmdLineParser::importCompileCommands(const std::string& /*filename*/, const std::string& data)
{
    json::Value compileCommands;
    json::parse(compileCommands, data);
    if (!compileCommands.isArray()) {
        printError("compilation database is not a JSON array");
        return false;
    }

    for (const json::Value& fileInfo : compileCommands.getArray()) {
        const auto& obj = fileInfo.getObject();

        if (obj.count("directory") == 0) {
            printError("'directory' field in compilation database entry missing");
            return false;
        }
        if (!obj.at("directory").isString()) {
            printError("'directory' field in compilation database entry is not a string");
            return false;
        }
        std::string dirpath = util::fromNativeSeparators(obj.at("directory").getString());
        if (!endsWith(dirpath, '/'))
            dirpath += '/';
        const std::string directory = dirpath;

        std::vector<std::string> args;
        if (obj.count("arguments")) {
            if (!obj.at("arguments").isArray()) {
                printError("'arguments' field in compilation database entry is not a JSON array");
                return false;
            }
            for (const json::Value& arg : obj.at("arguments").getArray()) {
                if (arg.isString())
                    args.push_back(arg.getString());
            }
        } else if (obj.count("command")) {
            if (!obj.at("command").isString()) {
                printError("'command' field in compilation database entry is not a string");
                return false;
            }
            args = splitCommand(obj.at("command").getString());
        } else {
            printError("no 'arguments' or 'command' field found in compilation database entry");
            return false;
        }

        if (!obj.count("file") || !obj.at("file").isString()) {
            printError("skip compilation database entry because it does not have a proper 'file' field");
            continue;
        }

        const std::string file = util::fromNativeSeparators(obj.at("file").getString());
        std::string path;
        if (util::isAbsolute(file))
            path = util::simplifyPath(file);
        else
            path = util::simplifyPath(directory + file);

        FileSettings fs;
        fs.filename = path;
        parseCommandArgs(fs, args, directory);
