bool CmdLineParser::importProject(const std::string& projectFile)
{
    mProjectFile = projectFile;
    std::ifstream fin(projectFile);
    if (!fin.is_open()) {
        mProjectType = ProjectType::MISSING;
        printError("failed to open project '" + projectFile + "'. The file does not exist.");
        return false;
    }
    fin.close();

    bool ok = false;
    if (endsWith(projectFile, ".json")) {
        mProjectType = ProjectType::COMPILE_DB;
        ok = importCompileCommands(projectFile, readFileContents(projectFile));
    } else if (endsWith(projectFile, ".sln")) {
        mProjectType = ProjectType::VS_SLN;
        ok = importVsSln(projectFile);
    } else if (endsWith(projectFile, ".vcxproj")) {
        mProjectType = ProjectType::VS_VCXPROJ;
