static bool loadPlatformXml(PlatformInfo& p, const xml::Document& doc)
{
    const xml::Node* const rootnode = doc.rootElement();
    if (!rootnode || rootnode->value != "platform")
        return false;
    bool error = false;
    auto toInt = [&error](const xml::Node* n, int def) -> int {
        const char* t = n->getText();
        if (!t) {
            error = true;
            return def;
        }
        int v = 0;
        if (!util::strToInt(std::string(t), v)) {
            error = true;
            return def;
        }
        return v;
    };
    for (const xml::Node* node : rootnode->childElements()) {
        if (node->value == "default-sign") {
            const char* str = node->getText();
            if (str)
                p.defaultSign = *str;
            else
                error = true;
        } else if (node->value == "char_bit")
            p.char_bit = toInt(node, 8);
        else if (node->value == "sizeof") {
            for (const xml::Node* sz : node->childElements()) {
                if (sz->value == "short")
                    p.sizeof_short = toInt(sz, 2);
                else if (sz->value == "bool")
                    p.sizeof_bool = toInt(sz, 1);
                else if (sz->value == "int")
                    p.sizeof_int = toInt(sz, 4);
                else if (sz->value == "long")
                    p.sizeof_long = toInt(sz, 4);
                else if (sz->value == "long-long")
                    p.sizeof_long_long = toInt(sz, 8);
                else if (sz->value == "float")
                    p.sizeof_float = toInt(sz, 4);
                else if (sz->value == "double")
                    p.sizeof_double = toInt(sz, 8);
                else if (sz->value == "long-double")
