#include "library.h"
#include "util.h"
#include "version.h"
#include <iostream>
#include <cstring>
#include <sstream>

Library::Error Library::load(const std::string& exeDir, const std::string& path, bool debug)
{
    xml::Document doc;
    int error;
    std::string absolute_path;
    if (util::isAbsolute(path)) {
        if (debug)
            std::cout << "looking for library '" + path + "'" << std::endl;
        error = doc.loadFile(path);
        if (error != xml::XML_ERROR_FILE_NOT_FOUND)
            absolute_path = util::getAbsoluteFilePath(path);
    } else {
        std::string fullfilename(path);
        if (util::getFilenameExtension(fullfilename).empty())
            fullfilename += ".cfg";
        if (debug)
            std::cout << "looking for library '" + fullfilename + "'" << std::endl;
        error = doc.loadFile(fullfilename);
        if (error != xml::XML_ERROR_FILE_NOT_FOUND)
            absolute_path = util::getAbsoluteFilePath(fullfilename);
        std::vector<std::string> cfgfolders;
        cfgfolders.push_back(std::string(FILESDIR) + "/cfg");
        cfgfolders.push_back(exeDir + "cfg");
        cfgfolders.push_back(exeDir);
        while (error == xml::XML_ERROR_FILE_NOT_FOUND && !cfgfolders.empty()) {
            const std::string cfgfolder(cfgfolders.back());
            cfgfolders.pop_back();
            const char* sep = (!cfgfolder.empty() && util::endsWith(cfgfolder, '/') ? "" : "/");
            const std::string filename(cfgfolder + sep + fullfilename);
            if (debug)
                std::cout << "looking for library '" + filename + "'" << std::endl;
            error = doc.loadFile(filename);
            if (error != xml::XML_ERROR_FILE_NOT_FOUND)
                absolute_path = util::getAbsoluteFilePath(filename);
        }
    }

    if (error == xml::XML_SUCCESS) {
        if (files.find(absolute_path) == files.end()) {
            Error err = load(doc);
            if (err.errorcode == ErrorCode::OK)
                files.insert(absolute_path);
            return err;
        }
        return Error(ErrorCode::OK);
    }

    if (debug)
        std::cout << "library not found: '" + path + "'" << std::endl;

    if (error == xml::XML_ERROR_FILE_NOT_FOUND)
        return Error(ErrorCode::FILE_NOT_FOUND);

    std::cout << doc.errorStr() << std::endl;
    return Error(ErrorCode::BAD_XML);
}

static bool isKnownTopElement(const std::string& n)
{
    static const char* known[] = {
        "memory", "resource", "container", "define", "function", "reflection", "markup", "podtype",
        "platformtype", "type-checks", "smart-pointer", "entrypoint", "unknown_return_values", "attribute"
    };
    for (const char* k : known)
        if (n == k)
            return true;
    return false;
}

Library::Error Library::load(const xml::Document& doc)
{
    const xml::Node* const rootnode = doc.rootElement();
    if (rootnode == nullptr)
        return Error(ErrorCode::BAD_XML);
    if (rootnode->value != "def")
        return Error(ErrorCode::UNSUPPORTED_FORMAT, rootnode->value);

    int format = 1;
    if (const char* f = rootnode->attr("format")) {
        int tmp;
        if (util::strToInt(std::string(f), tmp))
            format = tmp;
    }
    if (format > 2 || format <= 0)
        return Error(ErrorCode::UNSUPPORTED_FORMAT);

    std::set<std::string> unknown_elements;
    for (const xml::Node* node : rootnode->childElements()) {
        const std::string& nodename = node->value;
        if (nodename == "define") {
            const char* name = node->attr("name");
            if (name == nullptr)
                return Error(ErrorCode::MISSING_ATTRIBUTE, "name");
            const char* value = node->attr("value");
            if (value == nullptr)
                return Error(ErrorCode::MISSING_ATTRIBUTE, "value");
            const std::string def = std::string(name) + " " + value;
            if (defines.count(def))
                return Error(ErrorCode::DUPLICATE_DEFINE, name);
            defines.insert(def);
            defineValues[name] = value;
        } else if (nodename == "function") {
            const char* name = node->attr("name");
            if (name == nullptr)
                return Error(ErrorCode::MISSING_ATTRIBUTE, "name");
            for (const std::string& fname : util::split(name, ',')) {
