// glob match where '*' does not cross '/', '**' does, '?' matches one non-'/' char
static bool globMatch(const char* p, const char* s)
{
    while (*p) {
        if (*p == '*') {
            if (p[1] == '*') {
                const char* rest = p + 2;
                if (*rest == '/') {
                    // "**/" can match zero directories
                    if (globMatch(rest + 1, s))
                        return true;
                }
                for (const char* t = s;; ++t) {
                    if (globMatch(rest, t))
                        return true;
                    if (!*t)
                        break;
                }
                return false;
            }
            const char* rest = p + 1;
            for (const char* t = s;; ++t) {
                if (globMatch(rest, t))
                    return true;
                if (!*t || *t == '/')
                    break;
            }
            return false;
        }
        if (*p == '?') {
            if (!*s || *s == '/')
                return false;
            ++p;
            ++s;
            continue;
        }
        if (*p != *s)
            return false;
        ++p;
        ++s;
    }
    return *s == '\0';
}

static bool matchPrefixes(const std::string& pattern, const std::string& path, bool dirOnly)
{
    // try every component-aligned prefix of path
    for (std::size_t i = 1; i <= path.size(); ++i) {
        const bool atBoundary = (i == path.size()) ? !dirOnly : (path[i] == '/');
        if (!atBoundary)
            continue;
        if (globMatch(pattern.c_str(), path.substr(0, i).c_str()))
            return true;
    }
    return false;
}

static bool matchOne(std::string pattern, const std::string& path)
{
    if (pattern.empty())
        return false;
    pattern = util::fromNativeSeparators(pattern);
    bool dirOnly = false;
    while (pattern.size() > 1 && util::endsWith(pattern, '/')) {
        pattern.pop_back();
        dirOnly = true;
    }
    if (pattern == "/")
        return false;
    const std::string absPath = util::isAbsolute(path) ? util::simplifyPath(path) : util::simplifyPath(util::getCurrentPath() + "/" + path);

    if (util::isAbsolute(pattern)) {
        return matchPrefixes(util::simplifyPath(pattern), absPath, dirOnly);
    }
    // relative to current dir
    std::string absPattern = util::simplifyPath(util::getCurrentPath() + "/" + pattern);
    while (absPattern.size() > 1 && util::endsWith(absPattern, '/'))
        absPattern.pop_back();
    if (matchPrefixes(absPattern, absPath, dirOnly))
        return true;
    // match any component sequence
    const std::string p = util::simplifyPath(pattern);
    for (std::size_t start = 0; start < absPath.size(); ++start) {
        if (start != 0 && absPath[start - 1] != '/')
            continue;
        if (absPath[start] == '/')
            continue;
        if (matchPrefixes(p, absPath.substr(start), dirOnly))
            return true;
    }
    return false;
}

bool isPathIgnored(const std::vector<std::string>& ignored, const std::string& path)
{
    for (const std::string& i : ignored) {
        if (matchOne(i, path))
            return true;
    }
    return false;
}
