    case Severity::internal: return "internal";
    }
    return "";
}

ErrorMessage::ErrorMessage(std::list<FileLocation> cs, std::string file0_, Severity sev, const std::string& msg, std::string id_, int cwe_, bool inconclusive_)
    : callStack(std::move(cs)), id(std::move(id_)), severity(sev), cwe(cwe_), inconclusive(inconclusive_), file0(std::move(file0_))
{
    setmsg(msg);
}

static void replaceAll(std::string& s, const std::string& from, const std::string& to)
{
    if (from.empty())
        return;
    std::string::size_type pos = 0;
    while ((pos = s.find(from, pos)) != std::string::npos) {
        s.replace(pos, from.size(), to);
        pos += to.size();
    }
}

void ErrorMessage::setmsg(const std::string& msg)
{
    std::string m = msg;
    // extract $symbol:
    std::string symbols;
    while (util::startsWith(m, "$symbol:")) {
        const std::string::size_type pos = m.find('\n');
        const std::string name = m.substr(8, pos == std::string::npos ? std::string::npos : pos - 8);
        if (!symbols.empty())
            symbols += '\n';
        symbols += name;
        m = (pos == std::string::npos) ? "" : m.substr(pos + 1);
    }
    if (!symbols.empty()) {
        symbolNames = symbols;
        const std::string first = symbols.substr(0, symbols.find('\n'));
        replaceAll(m, "$symbol", first);
    }
    const std::string::size_type pos = m.find('\n');
    if (pos == std::string::npos) {
        shortMessage = m;
        verboseMessage = m;
    } else {
        shortMessage = m.substr(0, pos);
        verboseMessage = m.substr(pos + 1);
    }
}

std::string xmlEscape(const std::string& s)
{
    std::string r;
    r.reserve(s.size());
    for (char c : s) {
        switch (c) {
        case '&': r += "&amp;"; break;
        case '<': r += "&lt;"; break;
        case '>': r += "&gt;"; break;
        case '"': r += "&quot;"; break;
        case '\'': r += "&apos;"; break;
        default:
            if ((unsigned char)c < 32 && c != '\n' && c != '\t' && c != '\r') {
                char buf[16];
                std::snprintf(buf, sizeof(buf), "&#x%X;", (unsigned char)c);
                r += buf;
            } else
                r += c;
        }
    }
    return r;
}

std::string callStackToString(const std::list<FileLocation>& cs)
{
    std::string str;
    for (auto it = cs.cbegin(); it != cs.cend(); ++it) {
        str += (it == cs.cbegin() ? "" : " -> ");
        str += "[" + it->file + ":" + std::to_string(it->line) + "]";
    }
    return str;
}

static std::string readCode(const std::string& file, int linenr, int column, const char* endl)
{
    std::ifstream fin(file);
    std::string line;
    while (linenr > 0 && std::getline(fin, line))
        linenr--;
    const std::string::size_type endPos = line.find_last_not_of("\r\n\t ");
    if (endPos + 1 < line.size())
        line.erase(endPos + 1);
    std::string::size_type pos = 0;
    while ((pos = line.find('\t', pos)) != std::string::npos)
        line[pos] = ' ';
    return line + endl + std::string((column > 0 ? column - 1 : 0), ' ') + '^';
}

static const char* endlOf(const std::string& result)
{
    const std::string::size_type pos = result.find('\r');
    if (pos == std::string::npos)
        return "\n";
    if (pos + 1 < result.size() && result[pos + 1] == '\n')
        return "\r\n";
    return "\r";
}

std::string ErrorMessage::toString(bool verbose, const std::string& templateFormat, const std::string& templateLocation) const
{
    std::string result = templateFormat;
    replaceAll(result, "{id}", id);

    std::string::size_type pos1 = result.find("{inconclusive:");
    while (pos1 != std::string::npos) {
        const std::string::size_type pos2 = result.find('}', pos1 + 1);
        const std::string replaceFrom = result.substr(pos1, pos2 - pos1 + 1);
        const std::string replaceWith = inconclusive ? result.substr(pos1 + 14, pos2 - pos1 - 14) : std::string();
        replaceAll(result, replaceFrom, replaceWith);
        pos1 = result.find("{inconclusive:", pos1);
    }
    replaceAll(result, "{severity}", severityToString(severity));
    replaceAll(result, "{cwe}", std::to_string(cwe));
    replaceAll(result, "{message}", verbose ? verboseMessage : shortMessage);
    replaceAll(result, "{remark}", "");
    if (!callStack.empty()) {
        if (result.find("{callstack}") != std::string::npos)
            replaceAll(result, "{callstack}", callStackToString(callStack));
        replaceAll(result, "{file}", callStack.back().file);
        replaceAll(result, "{line}", std::to_string(callStack.back().line));
        replaceAll(result, "{column}", std::to_string(callStack.back().column));
        if (result.find("{code}") != std::string::npos) {
            const char* endl = endlOf(result);
            replaceAll(result, "{code}", readCode(callStack.back().origFile, callStack.back().line, callStack.back().column, endl));
        }
    } else {
        replaceAll(result, "{callstack}", "");
        replaceAll(result, "{file}", "nofile");
        replaceAll(result, "{line}", "0");
        replaceAll(result, "{column}", "0");
        replaceAll(result, "{code}", "");
    }

    if (!templateLocation.empty() && callStack.size() >= 2U) {
        for (const FileLocation& fileLocation : callStack) {
            std::string text = templateLocation;
            replaceAll(text, "{file}", fileLocation.file);
            replaceAll(text, "{line}", std::to_string(fileLocation.line));
            replaceAll(text, "{column}", std::to_string(fileLocation.column));
            replaceAll(text, "{info}", fileLocation.info.empty() ? shortMessage : fileLocation.info);
            if (text.find("{code}") != std::string::npos) {
                const char* endl = endlOf(text);
                replaceAll(text, "{code}", readCode(fileLocation.origFile, fileLocation.line, fileLocation.column, endl));
            }
            result += '\n' + text;
        }
    }
    return result;
}

std::string ErrorMessage::toXML() const
{
    std::ostringstream os;
    os << "        <error id=\"" << xmlEscape(id) << "\" severity=\"" << severityToString(severity) << "\"";
    os << " msg=\"" << xmlEscape(shortMessage) << "\" verbose=\"" << xmlEscape(verboseMessage) << "\"";
    if (cwe)
        os << " cwe=\"" << cwe << "\"";
    if (hash)
        os << " hash=\"" << hash << "\"";
    if (inconclusive)
        os << " inconclusive=\"true\"";
    if (!file0.empty())
        os << " file0=\"" << xmlEscape(file0) << "\"";
    std::vector<std::string> symbols;
    if (!symbolNames.empty())
        symbols = util::split(symbolNames, '\n');
    if (callStack.empty() && symbols.empty()) {
        os << "/>";
        return os.str();
    }
    os << ">\n";
    for (auto it = callStack.crbegin(); it != callStack.crend(); ++it) {
        os << "            <location file=\"" << xmlEscape(it->file) << "\" line=\"" << std::max(it->line, 0) << "\" column=\"" << it->column << "\"";
        if (!it->info.empty())
            os << " info=\"" << xmlEscape(it->info) << "\"";
        os << "/>\n";
    }
    for (const std::string& s : symbols)
        os << "            <symbol>" << xmlEscape(s) << "</symbol>\n";
    os << "        </error>";
    return os.str();
}

ErrorOutput::ErrorOutput(Settings& s, Suppressions& sup) : settings(s), suppressions(sup)
{
    if (!settings.outputFile.empty()) {
        mOutFile.open(settings.outputFile);
        mUseFile = true;
    }
}

ErrorOutput::~ErrorOutput() = default;

void ErrorOutput::writeRaw(const std::string& s)
{
    if (mUseFile)
        mOutFile << s << std::endl;
    else
        std::cerr << s << std::endl;
}

bool ErrorOutput::report(ErrorMessage msg)
{
    const bool xml = settings.outputFormat == Settings::OutputFormat::xml;
    if (!xml && settings.templateLocation.empty() && !settings.verbose && msg.callStack.size() > 1) {
        FileLocation last = msg.callStack.back();
        msg.callStack.clear();
        msg.callStack.push_back(last);
    }
    std::string text;
    if (xml)
        text = msg.toXML();
    else
        text = msg.toString(settings.verbose, templateFormat, templateLocation);
    const std::string key = msg.toString(settings.verbose, templateFormat, templateLocation) + (xml ? text : "");
    if (mShown.count(key))
        return false;
    mShown.insert(key);
    if (msg.id != "checkersReport")
        mAnyError = true;
    writeRaw(text);
    return true;
}

void ErrorOutput::xmlHeader()
{
    std::string s = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<results version=\"" + std::to_string(settings.xml_version) + "\">\n";
    s += "    <cppcheck version=\"" CPPCHECK_VERSION_STRING "\"/>\n    <errors>";
    writeRaw(s);
}

void ErrorOutput::xmlFooter(const std::vector<std::string>& activeCheckers, const std::set<std::string>& critical)
{
    std::string s = "    </errors>\n";
    if (settings.xml_version == 3) {
        s += "\n";
        if (critical.empty())
            s += "    <critical-errors/>\n";
        else {
            s += "    <critical-errors>\n";
            for (const std::string& c : critical)
                s += "        <error id=\"" + c + "\"/>\n";
            s += "    </critical-errors>\n";
        }
        if (activeCheckers.empty())
            s += "    <checkers-report/>\n";
        else {
            s += "    <checkers-report>\n";
            for (const std::string& c : activeCheckers)
                s += "        <checker id=\"" + c + "\"/>\n";
            s += "    </checkers-report>\n";
        }
    }
    s += "</results>";
    writeRaw(s);
}
