bool PPToken::isString() const
{
    if (str.empty())
        return false;
    std::size_t i = 0;
    while (i < str.size() && (str[i] == 'L' || str[i] == 'u' || str[i] == 'U' || str[i] == '8' || str[i] == 'R'))
        ++i;
    return i < str.size() && str[i] == '"' && (i == 0 || std::isalpha((unsigned char)str[0]));
}

bool PPToken::isChar() const
{
    if (str.empty())
        return false;
    std::size_t i = 0;
    while (i < str.size() && (str[i] == 'L' || str[i] == 'u' || str[i] == 'U' || str[i] == '8'))
        ++i;
    return i < str.size() && str[i] == '\'';
}

static bool isNameChar(char c)
{
    return std::isalnum((unsigned char)c) || c == '_' || c == '$' || (unsigned char)c >= 0x80;
}

std::vector<PPToken> tokenizeRaw(const std::string& data, int fileIndex, std::vector<PPComment>* comments)
{
    std::vector<PPToken> toks;
    int line = 1;
    int col = 0;          // column of last read char
    int multiline = 0;    // pending line splices
    bool ws = false;
    std::size_t i = 0;
    const std::size_t n = data.size();

    // helper to get char with splice handling: returns char at i, consumes splices before
    auto skipSplices = [&]() {
        while (i + 1 < n && data[i] == '\\' && (data[i+1] == '\n' || (data[i+1] == '\r' && i + 2 < n && data[i+2] == '\n'))) {
            col++;
            i += (data[i+1] == '\r') ? 3 : 2;
            multiline++;
        }
    };

    while (i < n) {
        skipSplices();
        if (i >= n)
            break;
        char ch = data[i];
        if (ch == '\r' && i + 1 < n && data[i+1] == '\n') {
            ++i;
            continue;
        }
        if (ch == '\n') {
            line += 1 + multiline;
            multiline = 0;
            col = 0;
            ++i;
            ws = true;
            continue;
        }
        if (ch == ' ' || ch == '\t' || ch == '\f' || ch == '\v' || ch == '\r') {
            col++;
            ++i;
            ws = true;
            continue;
        }
        // comments
        if (ch == '/' && i + 1 < n && data[i+1] == '/') {
            const int startCol = col + 1;
            std::string text;
            while (i < n && data[i] != '\n') {
                if (data[i] == '\\' && i + 1 < n && data[i+1] == '\n') {
                    i += 2;
                    multiline++;
                    col++;
                    continue;
                }
                if (data[i] != '\r')
                    text += data[i];
                ++i;
                col++;
            }
            if (comments)
                comments->push_back({text, fileIndex, line, startCol});
            ws = true;
            continue;
        }
        if (ch == '/' && i + 1 < n && data[i+1] == '*') {
            const int startCol = col + 1;
            const int startLine = line;
            std::string text = "/*";
            i += 2;
            col += 2;
            while (i < n && !(data[i] == '*' && i + 1 < n && data[i+1] == '/')) {
                if (data[i] == '\n') {
                    line += 1 + multiline;
                    multiline = 0;
                    col = 0;
                } else
                    col++;
                text += data[i];
                ++i;
            }
            if (i < n) {
                i += 2;
                col += 2;
                text += "*/";
            }
            if (comments)
                comments->push_back({text, fileIndex, startLine, startCol});
            ws = true;
            continue;
        }

        PPToken tok;
        tok.fileIndex = fileIndex;
        tok.line = line;
        tok.col = col + 1;
        tok.ws = ws;
        ws = false;

        auto readQuoted = [&](char q) {
            // assumes data[i] == q
            tok.str += data[i];
            ++i;
            col++;
            while (i < n) {
                skipSplices();
                if (i >= n)
                    break;
                const char c = data[i];
                if (c == '\n')
                    break;
                if (c == '\\' && i + 1 < n) {
                    tok.str += c;
                    tok.str += data[i+1];
                    i += 2;
                    col += 2;
                    continue;
                }
                tok.str += c;
                ++i;
                col++;
                if (c == q)
                    break;
            }
        };

        if (std::isalpha((unsigned char)ch) || ch == '_' || ch == '$' || (unsigned char)ch >= 0x80) {
            // identifier, or string/char prefix
            std::size_t j = i;
            std::string name;
            while (j < n && isNameChar(data[j])) {
                name += data[j];
                ++j;
            }
            const bool prefix = (name == "L" || name == "u" || name == "U" || name == "u8");
            const bool rawPrefix = (name == "R" || name == "LR" || name == "uR" || name == "UR" || name == "u8R");
            if (j < n && data[j] == '"' && rawPrefix) {
                // raw string
                tok.str = name;
                col += (int)name.size();
                i = j;
                std::size_t k = i + 1;
                std::string delim;
                while (k < n && data[k] != '(' && data[k] != '\n')
                    delim += data[k++];
                const std::string endseq = ")" + delim + "\"";
                const std::size_t endpos = data.find(endseq, k);
                const std::size_t stop = (endpos == std::string::npos) ? n : endpos + endseq.size();
                for (; i < stop; ++i) {
                    if (data[i] == '\n') {
                        line++;
                        col = 0;
                    } else
                        col++;
                    tok.str += data[i];
                }
                // convert raw string to normal string literal representation
                std::string content = tok.str.substr(name.size() + 1 + delim.size() + 1);
                if (content.size() >= endseq.size())
                    content.erase(content.size() - endseq.size());
                std::string esc;
                for (char c : content) {
                    if (c == '\\' || c == '"')
                        esc += '\\';
                    if (c == '\n') {
                        esc += "\\n";
                        continue;
                    }
                    esc += c;
                }
                tok.str = name.substr(0, name.size() - 1) + "\"" + esc + "\"";
                toks.push_back(tok);
                continue;
            }
            if (j < n && (data[j] == '"' || data[j] == '\'') && prefix) {
                tok.str = name;
                col += (int)name.size();
                i = j;
                readQuoted(data[i]);
                toks.push_back(tok);
                continue;
            }
            tok.str = name;
            col += (int)name.size();
            i = j;
            toks.push_back(tok);
            continue;
        }
        if (std::isdigit((unsigned char)ch) || (ch == '.' && i + 1 < n && std::isdigit((unsigned char)data[i+1]))) {
            while (i < n) {
                skipSplices();
                if (i >= n)
                    break;
                const char c = data[i];
                if (isNameChar(c) || c == '.') {
                    tok.str += c;
                    ++i;
                    col++;
                    if ((c == 'e' || c == 'E' || c == 'p' || c == 'P') && i < n && (data[i] == '+' || data[i] == '-')) {
                        // exponent sign; but not for hex digits 'e' in hex literals
                        const bool hex = tok.str.size() > 1 && (tok.str[1] == 'x' || tok.str[1] == 'X');
                        if (!hex || c == 'p' || c == 'P') {
                            tok.str += data[i];
                            ++i;
                            col++;
                        }
                    }
                } else if (c == '\'' && i + 1 < n && isNameChar(data[i+1]) && !tok.str.empty()) {
                    // digit separator
                    ++i;
                    col++;
                } else
                    break;
            }
            toks.push_back(tok);
            continue;
        }
        if (ch == '"' || ch == '\'') {
            readQuoted(ch);
            toks.push_back(tok);
            continue;
        }
        // operators
        static const char* ops3[] = { "<<=", ">>=", "...", "->*", "<=>" };
        static const char* ops2[] = { "##", "&&", "||", "==", "!=", "<=", ">=", "<<", ">>", "++", "--", "->", "::",
                                      "+=", "-=", "*=", "/=", "%=", "&=", "|=", "^=", ".*" };
        bool done = false;
        for (const char* op : ops3) {
            if (data.compare(i, 3, op) == 0) {
                if (std::strcmp(op, "<=>") == 0 || std::strcmp(op, "->*") == 0)
                    continue;
                tok.str = op;
                i += 3;
                col += 3;
                done = true;
                break;
            }
        }
        if (!done) {
            for (const char* op : ops2) {
                if (data.compare(i, 2, op) == 0) {
                    if (std::strcmp(op, ".*") == 0)
                        continue;
                    tok.str = op;
                    i += 2;
                    col += 2;
                    done = true;
                    break;
                }
            }
        }
        if (!done) {
            tok.str = std::string(1, ch);
            ++i;
            col++;
        }
        toks.push_back(tok);
    }
    return toks;
}

Preprocessor::Preprocessor(const Settings& settings, bool cpp) : mSettings(settings), mCpp(cpp) {}

int Preprocessor::loadFile(const std::string& path)
{
    const auto it = mFileIndex.find(path);
    if (it != mFileIndex.end())
        return it->second;
    std::ifstream fin(path, std::ios::binary);
    if (!fin.is_open())
        return -1;
    std::string data((std::istreambuf_iterator<char>(fin)), std::istreambuf_iterator<char>());
    // strip UTF-8 BOM
    if (data.size() >= 3 && (unsigned char)data[0] == 0xEF && (unsigned char)data[1] == 0xBB && (unsigned char)data[2] == 0xBF)
        data.erase(0, 3);
    const int idx = (int)mRaw.size();
    std::unique_ptr<RawFile> rf(new RawFile);
    rf->path = path;
    rf->tokens = tokenizeRaw(data, idx, &rf->comments);
    rf->ok = true;
    mRaw.push_back(std::move(rf));
    mFileNames.push_back(path);
    mFileIndex[path] = idx;
    return idx;
}

bool Preprocessor::loadMain(const std::string& path)
{
    return loadFile(path) == 0;
}

std::string Preprocessor::findInclude(const std::string& header, bool system, const std::string& sourcefile)
{
    if (util::isAbsolute(header))
        return util::isFile(header) ? util::simplifyPath(header) : "";
    if (!system) {
        const std::string dir = util::getPathFromFilename(sourcefile);
        const std::string p = util::simplifyPath(dir + header);
        if (util::isFile(p))
            return p;
    }
    for (const std::string& inc : mSettings.includePaths) {
        const std::string p = util::simplifyPath(inc + header);
        if (util::isFile(p))
            return p;
    }
    if (system) {
        // fall back to source dir for <> includes is not done
    }
    return "";
}

// ---------------- configuration extraction ----------------

static std::string cfgJoin(const std::vector<std::string>& configs, const std::string& userDefines)
{
    std::set<std::string> configs2(configs.cbegin(), configs.cend());
    std::string ret;
    for (const std::string& c : configs2) {
        if (c.empty())
            continue;
        if (c == "0")
            return "";
        if (!ret.empty())
            ret += ';';
        ret += c;
    }
    if (!userDefines.empty()) {
        if (!ret.empty())
            ret = ';' + ret;
        ret = userDefines + ret;
    }
    return ret;
}

static bool isUndefinedCfg(const std::string& cfg, const std::set<std::string>& undefined)
{
    for (std::string::size_type pos1 = 0U; pos1 < cfg.size();) {
        const std::string::size_type pos2 = cfg.find(';', pos1);
        const std::string def = (pos2 == std::string::npos) ? cfg.substr(pos1) : cfg.substr(pos1, pos2 - pos1);
        const std::string::size_type eq = def.find('=');
        if (eq == std::string::npos && undefined.find(def) != undefined.end())
            return true;
        if (eq != std::string::npos && undefined.find(def.substr(0, eq)) != undefined.end() && def.substr(eq) != "=0")
            return true;
        pos1 = (pos2 == std::string::npos) ? pos2 : pos2 + 1U;
    }
    return false;
}

struct LineToks {
    std::vector<const PPToken*> toks;
};

// group tokens by line
static std::vector<LineToks> splitLines(const std::vector<PPToken>& tokens)
{
    std::vector<LineToks> lines;
    int curLine = -1;
    for (const PPToken& t : tokens) {
        if (t.line != curLine || lines.empty()) {
            lines.emplace_back();
            curLine = t.line;
        }
        lines.back().toks.push_back(&t);
    }
    return lines;
}

static std::string readCondition(const LineToks& lt, const std::set<std::string>& defined, const std::set<std::string>& undefined)
{
    // lt.toks[0] == '#', [1] == if/elif
    const std::vector<const PPToken*>& t = lt.toks;
    if (t.size() < 3)
        return "";
    const std::size_t len = t.size() - 2;
    const PPToken* cond = t[2];
    if (len == 1 && cond->str == "0")
        return "0";
    if (len == 1 && cond->isName()) {
        if (defined.find(cond->str) == defined.end())
            return cond->str;
    }
    if (len == 2 && cond->str == "!" && t[3]->isName()) {
        if (defined.find(t[3]->str) == defined.end())
            return t[3]->str + "=0";
    }
    if (len == 3 && cond->str == "(" && t[3]->isName() && t[4]->str == ")") {
        if (defined.find(t[3]->str) == defined.end() && undefined.find(t[3]->str) == undefined.end())
            return t[3]->str;
    }
    if (len == 3 && cond->isName() && t[3]->str == "==" && t[4]->isNumber()) {
        if (defined.find(cond->str) == defined.end())
            return cond->str + '=' + t[4]->str;
    }
    std::set<std::string> configset;
    for (std::size_t i = 2; i < t.size(); ++i) {
        if (t[i]->str == "!") {
            if (i + 1 >= t.size() || !t[i+1]->isName())
                break;
            if (t[i+1]->str == "defined")
                continue;
            configset.insert(t[i+1]->str + "=0");
            continue;
        }
        if (t[i]->str != "defined")
            continue;
        std::size_t j = i + 1;
        if (j >= t.size())
            break;
        if (t[j]->str == "(")
            ++j;
        if (j < t.size() && t[j]->isName() && defined.find(t[j]->str) == defined.end() && undefined.find(t[j]->str) == undefined.end())
            configset.insert(t[j]->str);
    }
    std::string cfgStr;
    for (const std::string& s : configset) {
        if (!cfgStr.empty())
            cfgStr += ';';
        cfgStr += s;
    }
    return cfgStr;
}

static bool elseIsFalse(const std::vector<std::string>& configs_if, const std::string& userDefines)
{
    return std::any_of(configs_if.cbegin(), configs_if.cend(), [=](const std::string& cfg) {
        return cfg.find('=') == std::string::npos ? false : false;
    }) && userDefines.empty() ? false : false;
}

void Preprocessor::getConfigsFromFile(int fileIndex, std::set<std::string>& defined, std::set<std::string>& ret)
{
    RawFile* rf = mRaw[fileIndex].get();
    const std::vector<LineToks> lines = splitLines(rf->tokens);
    std::vector<std::string> configs_if;
    std::vector<std::string> configs_ifndef;
    std::string elseError;
    const std::string& userDefines = mSettings.userDefines;
    const std::set<std::string>& undefined = mSettings.userUndefs;
    bool firstDirectiveSeen = false;

    for (std::size_t li = 0; li < lines.size(); ++li) {
        const LineToks& lt = lines[li];
        if (lt.toks.empty() || lt.toks[0]->str != "#" || lt.toks.size() < 2) {
            if (!lt.toks.empty())
                firstDirectiveSeen = true;
            continue;
        }
        const std::string& cmd = lt.toks[1]->str;
        const bool isFirst = !firstDirectiveSeen;
        firstDirectiveSeen = true;
        if (cmd == "ifdef" || cmd == "ifndef" || cmd == "if") {
            std::string config;
            if (cmd == "ifdef" || cmd == "ifndef") {
                if (lt.toks.size() == 3 && lt.toks[2]->isName())
                    config = lt.toks[2]->str;
                if (defined.find(config) != defined.end())
                    config.clear();
            } else {
                config = readCondition(lt, defined, undefined);
            }
            if (isUndefinedCfg(config, undefined))
                config.clear();

            bool ifndef = false;
            if (cmd == "ifndef")
                ifndef = true;
            else {
                const std::vector<std::string> match{"if", "!", "defined", "(", config, ")"};
                ifndef = lt.toks.size() >= 7;
                for (std::size_t k = 0; ifndef && k < match.size(); ++k) {
                    if (lt.toks[k + 1]->str != match[k])
                        ifndef = false;
                }
            }
            // include guard
            if (ifndef && fileIndex > 0 && isFirst) {
                configs_if.emplace_back();
                configs_ifndef.emplace_back();
                continue;
            }
            configs_if.push_back((cmd == "ifndef") ? std::string() : config);
            configs_ifndef.push_back((cmd == "ifndef") ? config : std::string());
            ret.insert(cfgJoin(configs_if, userDefines));
        } else if (cmd == "elif" || cmd == "else") {
            if (cmd == "else" && li + 1 < lines.size() && lines[li+1].toks.size() >= 2 &&
                lines[li+1].toks[0]->str == "#" && lines[li+1].toks[1]->str == "error") {
                const std::string ifcfg = cfgJoin(configs_if, userDefines);
                if (!ifcfg.empty()) {
                    if (!elseError.empty())
                        elseError += ';';
                    elseError += ifcfg;
                }
            }
            if (!configs_if.empty())
                configs_if.pop_back();
            if (cmd == "elif") {
                std::string config = readCondition(lt, defined, undefined);
                if (isUndefinedCfg(config, undefined))
                    config.clear();
                configs_if.push_back(std::move(config));
                ret.insert(cfgJoin(configs_if, userDefines));
            } else if (!configs_ifndef.empty()) {
                configs_if.push_back(configs_ifndef.back());
                ret.insert(cfgJoin(configs_if, userDefines));
            }
        } else if (cmd == "endif" && lt.toks.size() == 2) {
            if (!configs_if.empty())
                configs_if.pop_back();
            if (!configs_ifndef.empty())
                configs_ifndef.pop_back();
        } else if (cmd == "error") {
            if (!configs_ifndef.empty() && !configs_ifndef.back().empty()) {
                if (configs_ifndef.size() == 1U)
                    ret.erase("");
                std::vector<std::string> configs(configs_if);
                configs.push_back(configs_ifndef.back());
                ret.erase(cfgJoin(configs, userDefines));
                std::set<std::string> temp;
                temp.swap(ret);
                for (const std::string& c : temp) {
                    if (c.find(configs_ifndef.back()) != std::string::npos)
                        ret.insert(c);
                    else if (c.empty())
                        ret.insert("");
                    else
                        ret.insert(c + ";" + configs_ifndef.back());
                }
                if (!elseError.empty())
                    elseError += ';';
                elseError += cfgJoin(configs_ifndef, userDefines);
            }
            if (!configs_if.empty() && !configs_if.back().empty()) {
                const std::string last = configs_if.back();
                if (last.size() > 2U && last.compare(last.size() - 2U, 2, "=0") == 0) {
                    std::vector<std::string> configs(configs_if);
                    ret.erase(cfgJoin(configs, userDefines));
                    configs[configs.size() - 1U] = last.substr(0, last.size() - 2U);
                    if (configs.size() == 1U)
                        ret.erase("");
                    if (!elseError.empty())
                        elseError += ';';
                    elseError += cfgJoin(configs, userDefines);
                }
            }
        } else if (cmd == "define" && lt.toks.size() >= 3 && lt.toks[2]->isName()) {
            defined.insert(lt.toks[2]->str);
        }
    }
    if (!elseError.empty())
        ret.insert(elseError);
    (void)elseIsFalse;
}

std::set<std::string> Preprocessor::getConfigs()
{
    std::set<std::string> ret = { "" };
    if (mRaw.empty() || mRaw[0]->tokens.empty())
        return ret;
    std::set<std::string> defined = { "__cplusplus" };
    // follow includes: load all reachable include files (found ones)
    std::vector<int> order;
    std::set<int> seen;
    std::function<void(int)> visit = [&](int idx) {
        if (seen.count(idx))
            return;
        seen.insert(idx);
        order.push_back(idx);
        const std::vector<LineToks> lines = splitLines(mRaw[idx]->tokens);
        for (const LineToks& lt : lines) {
            if (lt.toks.size() >= 3 && lt.toks[0]->str == "#" && lt.toks[1]->str == "include") {
                const std::string& h = lt.toks[2]->str;
                std::string header;
                bool sys = false;
                if (h.size() >= 2 && h[0] == '"') {
                    header = h.substr(1, h.size() - 2);
                } else if (h == "<") {
                    sys = true;
                    for (std::size_t k = 3; k < lt.toks.size() && lt.toks[k]->str != ">"; ++k)
                        header += lt.toks[k]->str;
                } else
                    continue;
                const std::string path = findInclude(header, sys, mRaw[idx]->path);
                if (path.empty())
                    continue;
                const int fi = loadFile(path);
                if (fi >= 0)
                    visit(fi);
            }
        }
    };
    visit(0);
    getConfigsFromFile(0, defined, ret);
    for (std::size_t k = 1; k < order.size(); ++k) {
        bool excluded = false;
        for (const std::string& ex : mSettings.configExcludePaths)
            if (util::startsWith(mRaw[order[k]]->path, ex))
                excluded = true;
        if (!excluded)
            getConfigsFromFile(order[k], defined, ret);
    }
    return ret;
}

// ---------------- macro expansion and directive processing ----------------

namespace {

struct Macro {
    std::string name;
    bool functionLike = false;
    bool variadic = false;
    std::vector<std::string> params;
    std::vector<PPToken> body;
};

struct ETok {
    PPToken t;
    std::shared_ptr<std::set<std::string>> hide;
};

class Expander {
public:
    std::map<std::string, Macro>& macros;
    const std::vector<std::string>& fileNames;
    int counter = 0;
    std::string dateStr, timeStr;
    explicit Expander(std::map<std::string, Macro>& m, const std::vector<std::string>& f) : macros(m), fileNames(f) {
        std::time_t now = std::time(nullptr);
        std::tm* lt = std::localtime(&now);
        static const char* months[] = {"Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"};
        char buf[64];
        std::snprintf(buf, sizeof(buf), "\"%s %2d %d\"", months[lt->tm_mon], lt->tm_mday, lt->tm_year + 1900);
        dateStr = buf;
        std::snprintf(buf, sizeof(buf), "\"%02d:%02d:%02d\"", lt->tm_hour, lt->tm_min, lt->tm_sec);
        timeStr = buf;
    }

    static std::string stringify(const std::vector<ETok>& arg) {
        std::string s = "\"";
        for (std::size_t i = 0; i < arg.size(); ++i) {
            if (i > 0 && arg[i].t.ws)
                s += ' ';
            const std::string& str = arg[i].t.str;
            if (arg[i].t.isString() || arg[i].t.isChar()) {
                for (char c : str) {
                    if (c == '"' || c == '\\')
                        s += '\\';
                    s += c;
                }
            } else
                s += str;
        }
        s += "\"";
        return s;
    }

    // expand a sequence of tokens fully
    std::vector<ETok> expand(std::vector<ETok> input, bool inIf = false) {
        std::vector<ETok> out;
        std::size_t pos = 0;
        while (pos < input.size()) {
            ETok cur = input[pos];
            if (!cur.t.isName()) {
                out.push_back(cur);
                ++pos;
                continue;
            }
            if (inIf && cur.t.str == "defined") {
                // copy defined X / defined(X) as is
                out.push_back(cur);
                ++pos;
                if (pos < input.size() && input[pos].t.str == "(") {
                    for (int k = 0; k < 3 && pos < input.size(); ++k)
                        out.push_back(input[pos++]);
                } else if (pos < input.size())
                    out.push_back(input[pos++]);
                continue;
            }
            if (cur.t.str == "__FILE__") {
                cur.t.str = "\"" + fileNames[cur.t.fileIndex] + "\"";
                out.push_back(cur);
                ++pos;
                continue;
            }
            if (cur.t.str == "__LINE__") {
                cur.t.str = std::to_string(cur.t.line);
                out.push_back(cur);
                ++pos;
                continue;
            }
            if (cur.t.str == "__COUNTER__") {
                cur.t.str = std::to_string(counter++);
                out.push_back(cur);
                ++pos;
                continue;
            }
            auto it = macros.find(cur.t.str);
            if (it == macros.end() || (cur.hide && cur.hide->count(cur.t.str))) {
                out.push_back(cur);
                ++pos;
                continue;
            }
            const Macro& m = it->second;
            if (!m.functionLike) {
                std::vector<ETok> repl = substitute(m, {}, cur);
                input.erase(input.begin() + pos);
                input.insert(input.begin() + pos, repl.begin(), repl.end());
                continue;
            }
            // function-like: need '('
            std::size_t p = pos + 1;
            if (p >= input.size() || input[p].t.str != "(") {
                out.push_back(cur);
                ++pos;
                continue;
            }
            // collect args
            std::vector<std::vector<ETok>> args(1);
            int depth = 0;
            std::size_t q = p + 1;
            bool closed = false;
            for (; q < input.size(); ++q) {
                const std::string& s = input[q].t.str;
                if (s == "(") {
                    depth++;
                } else if (s == ")") {
                    if (depth == 0) {
                        closed = true;
                        break;
                    }
                    depth--;
                } else if (s == "," && depth == 0) {
                    if (!(m.variadic && args.size() >= m.params.size())) {
                        args.emplace_back();
                        continue;
                    }
                }
                args.back().push_back(input[q]);
            }
            if (!closed) {
                out.push_back(cur);
                ++pos;
                continue;
            }
            if (m.params.empty() && args.size() == 1 && args[0].empty())
                args.clear();
            std::vector<ETok> repl = substitute(m, args, cur);
            input.erase(input.begin() + pos, input.begin() + q + 1);
            input.insert(input.begin() + pos, repl.begin(), repl.end());
        }
        return out;
    }

    std::vector<ETok> substitute(const Macro& m, const std::vector<std::vector<ETok>>& args, const ETok& nameTok) {
        auto hide = std::make_shared<std::set<std::string>>();
        if (nameTok.hide)
            *hide = *nameTok.hide;
        hide->insert(m.name);
        auto paramIndex = [&](const std::string& s) -> int {
            for (std::size_t i = 0; i < m.params.size(); ++i)
                if (m.params[i] == s)
                    return (int)i;
            if (m.variadic && s == "__VA_ARGS__")
                return (int)m.params.size() - 1;
            return -1;
        };
        auto getArg = [&](int idx) -> std::vector<ETok> {
            if (idx < (int)args.size())
                return args[idx];
            return {};
        };
        std::vector<ETok> res;
        const std::vector<PPToken>& body = m.body;
        for (std::size_t i = 0; i < body.size(); ++i) {
            const PPToken& bt = body[i];
            if (m.functionLike && bt.str == "#" && i + 1 < body.size() && paramIndex(body[i+1].str) >= 0) {
                ETok e;
                e.t = nameTok.t;
                e.t.str = stringify(getArg(paramIndex(body[i+1].str)));
                e.t.macroExpanded = true;
                e.hide = hide;
                res.push_back(e);
                ++i;
                continue;
            }
            if (bt.str == "##" && !res.empty() && i + 1 < body.size()) {
                // paste
                const PPToken& nt = body[i+1];
                std::string rhs;
                std::vector<ETok> rest;
                const int pi = m.functionLike ? paramIndex(nt.str) : -1;
                if (pi >= 0) {
                    std::vector<ETok> a = getArg(pi);
                    if (!a.empty()) {
                        rhs = a[0].t.str;
                        rest.assign(a.begin() + 1, a.end());
                    }
                } else
                    rhs = nt.str;
                res.back().t.str += rhs;
                for (ETok& r : rest) {
                    r.t.line = nameTok.t.line;
                    r.t.col = nameTok.t.col;
                    r.t.fileIndex = nameTok.t.fileIndex;
                    r.t.macroExpanded = true;
                    r.hide = hide;
                    res.push_back(r);
                }
                ++i;
                continue;
            }
            const int pi = m.functionLike ? paramIndex(bt.str) : -1;
            if (pi >= 0) {
                const bool nextIsPaste = (i + 1 < body.size() && body[i+1].str == "##");
                std::vector<ETok> a = getArg(pi);
                if (!nextIsPaste)
                    a = expand(a);
                for (std::size_t k = 0; k < a.size(); ++k) {
                    ETok e = a[k];
                    e.t.line = nameTok.t.line;
                    e.t.col = nameTok.t.col;
                    e.t.fileIndex = nameTok.t.fileIndex;
                    e.t.macroExpanded = true;
                    if (k == 0)
                        e.t.ws = bt.ws;
                    auto h = std::make_shared<std::set<std::string>>(*hide);
                    if (e.hide)
                        h->insert(e.hide->begin(), e.hide->end());
                    e.hide = h;
                    res.push_back(e);
                }
                continue;
            }
            ETok e;
            e.t = bt;
            e.t.line = nameTok.t.line;
            e.t.col = nameTok.t.col;
            e.t.fileIndex = nameTok.t.fileIndex;
            e.t.macroExpanded = true;
            e.hide = hide;
            res.push_back(e);
        }
        if (!res.empty())
            res[0].t.ws = nameTok.t.ws;
        return res;
    }
};

struct ExprEval {
    std::vector<std::string> toks;
    std::size_t pos = 0;
    bool error = false;
    const std::string& peek() { static const std::string empty; return pos < toks.size() ? toks[pos] : empty; }
    std::string next() { return pos < toks.size() ? toks[pos++] : std::string(); }

    static long long parseNumber(const std::string& s, bool& ok) {
        ok = true;
        std::string n = s;
        while (!n.empty() && (n.back() == 'u' || n.back() == 'U' || n.back() == 'l' || n.back() == 'L'))
            n.pop_back();
        if (n.empty()) { ok = false; return 0; }
        char* end = nullptr;
        long long v;
        if (n.size() > 2 && n[0] == '0' && (n[1] == 'x' || n[1] == 'X'))
            v = (long long)std::strtoull(n.c_str() + 2, &end, 16);
        else if (n.size() > 2 && n[0] == '0' && (n[1] == 'b' || n[1] == 'B'))
            v = (long long)std::strtoull(n.c_str() + 2, &end, 2);
        else if (n.size() > 1 && n[0] == '0')
            v = (long long)std::strtoull(n.c_str(), &end, 8);
        else
            v = (long long)std::strtoull(n.c_str(), &end, 10);
        if (end && *end)
            ok = false;
        return v;
    }

    long long primary() {
        const std::string t = next();
        if (t.empty()) { error = true; return 0; }
        if (t == "(") {
            const long long v = conditional();
            if (next() != ")")
                error = true;
            return v;
        }
        if (t == "!") return !primary();
        if (t == "~") return ~primary();
        if (t == "-") return -primary();
        if (t == "+") return primary();
        if (std::isdigit((unsigned char)t[0])) {
            bool ok;
            const long long v = parseNumber(t, ok);
            if (!ok) error = true;
            return v;
        }
        if (t[0] == '\'' || (t.size() > 1 && t[1] == '\'')) {
            const std::string::size_type q = t.find('\'');
            if (q + 1 < t.size()) {
                if (t[q+1] == '\\' && q + 2 < t.size()) {
                    switch (t[q+2]) {
                    case 'n': return '\n';
                    case 't': return '\t';
                    case '0': return 0;
                    case 'r': return '\r';
                    case '\\': return '\\';
                    case '\'': return '\'';
                    default: return t[q+2];
                    }
                }
                return (unsigned char)t[q+1];
            }
            return 0;
        }
        if (std::isalpha((unsigned char)t[0]) || t[0] == '_') {
            if (t == "true") return 1;
            return 0;
        }
        error = true;
        return 0;
    }
    long long mul() {
        long long v = primary();
        for (;;) {
            const std::string& op = peek();
            if (op == "*") { next(); v *= primary(); }
            else if (op == "/") { next(); const long long r = primary(); if (r == 0) { error = true; return 0; } v /= r; }
            else if (op == "%") { next(); const long long r = primary(); if (r == 0) { error = true; return 0; } v %= r; }
            else break;
        }
        return v;
    }
    long long add() {
        long long v = mul();
        for (;;) {
            const std::string& op = peek();
            if (op == "+") { next(); v += mul(); }
            else if (op == "-") { next(); v -= mul(); }
            else break;
        }
        return v;
    }
    long long shift() {
        long long v = add();
        for (;;) {
            const std::string& op = peek();
            if (op == "<<") { next(); v <<= add(); }
            else if (op == ">>") { next(); v >>= add(); }
            else break;
        }
        return v;
    }
    long long rel() {
        long long v = shift();
        for (;;) {
            const std::string& op = peek();
            if (op == "<") { next(); v = v < shift(); }
            else if (op == ">") { next(); v = v > shift(); }
            else if (op == "<=") { next(); v = v <= shift(); }
            else if (op == ">=") { next(); v = v >= shift(); }
            else break;
        }
        return v;
    }
    long long eq() {
        long long v = rel();
        for (;;) {
            const std::string& op = peek();
            if (op == "==") { next(); v = v == rel(); }
            else if (op == "!=") { next(); v = v != rel(); }
            else break;
        }
        return v;
    }
    long long band() { long long v = eq(); while (peek() == "&") { next(); v &= eq(); } return v; }
    long long bxor() { long long v = band(); while (peek() == "^") { next(); v ^= band(); } return v; }
    long long bor() { long long v = bxor(); while (peek() == "|") { next(); v |= bxor(); } return v; }
    long long land() { long long v = bor(); while (peek() == "&&") { next(); const long long r = bor(); v = v && r; } return v; }
    long long lor() { long long v = land(); while (peek() == "||") { next(); const long long r = land(); v = v || r; } return v; }
    long long conditional() {
        const long long c = lor();
        if (peek() == "?") {
            next();
            const long long a = conditional();
            if (next() != ":")
                error = true;
            const long long b = conditional();
            return c ? a : b;
        }
        return c;
    }
};

}

static void defineFromString(std::map<std::string, Macro>& macros, const std::string& def)
{
    // "NAME=VALUE" or "NAME"
    const std::string::size_type eq = def.find('=');
    std::string name = def.substr(0, eq);
    std::string value = (eq == std::string::npos) ? "1" : def.substr(eq + 1);
    Macro m;
    std::string::size_type paren = name.find('(');
    if (paren != std::string::npos) {
        // function-like via -D"F(x)=x"
        m.functionLike = true;
        std::string params = name.substr(paren + 1);
        name = name.substr(0, paren);
        if (!params.empty() && params.back() == ')')
            params.pop_back();
        for (const std::string& p : util::split(params, ',')) {
            std::string pp = util::trim(p);
            if (pp == "...") {
                m.variadic = true;
                pp = "__VA_ARGS__";
            }
            if (!pp.empty())
                m.params.push_back(pp);
        }
    }
    m.name = name;
    m.body = tokenizeRaw(value, 0, nullptr);
    for (PPToken& t : m.body)
        t.line = 0;
    macros[name] = m;
}

std::vector<PPToken> Preprocessor::preprocess(const std::string& cfg, std::vector<MissingInclude>& missing, std::string& errorMsg, PPToken& errorTok)
{
    std::map<std::string, Macro> macros;
    // predefined
    if (mCpp) {
        std::string v = "202400L";
        switch (mSettings.standards.cpp) {
        case Standards::CPP03: v = "199711L"; break;
        case Standards::CPP11: v = "201103L"; break;
        case Standards::CPP14: v = "201402L"; break;
        case Standards::CPP17: v = "201703L"; break;
        case Standards::CPP20: v = mSettings.standards.stdValueCPP.empty() ? "202400L" : "202002L"; break;
        case Standards::CPP23: v = "202302L"; break;
        case Standards::CPP26: v = "202400L"; break;
        }
        defineFromString(macros, "__cplusplus=" + v);
    } else {
        std::string v = "202500L";
        switch (mSettings.standards.c) {
        case Standards::C89: v = ""; break;
        case Standards::C99: v = "199901L"; break;
        case Standards::C11: v = mSettings.standards.stdValueC.empty() ? "202500L" : "201112L"; break;
        case Standards::C17: v = "201710L"; break;
        case Standards::C23: v = "202311L"; break;
        case Standards::C2Y: v = "202500L"; break;
        }
        if (!v.empty())
            defineFromString(macros, "__STDC_VERSION__=" + v);
    }
    {
        Expander tmp(macros, mFileNames);
        Macro d;
        d.name = "__DATE__";
        d.body = tokenizeRaw(tmp.dateStr, 0, nullptr);
        macros["__DATE__"] = d;
        Macro t;
        t.name = "__TIME__";
        t.body = tokenizeRaw(tmp.timeStr, 0, nullptr);
        macros["__TIME__"] = t;
    }
    // config defines
    for (const std::string& d : util::split(cfg, ';')) {
        if (!d.empty())
            defineFromString(macros, d);
    }
    for (const std::string& u : mSettings.userUndefs)
        macros.erase(u);

    Expander expander(macros, mFileNames);
    std::vector<PPToken> output;
    std::vector<ETok> pending;
    std::set<int> pragmaOnce;

    auto flush = [&]() {
        if (pending.empty())
            return;
        std::vector<ETok> res = expander.expand(pending);
        for (ETok& e : res)
            output.push_back(e.t);
        pending.clear();
    };

    struct CondState {
        bool active;      // current branch active
        bool taken;       // some branch taken
        bool parentActive;
    };

    std::function<bool(int, int)> processFile = [&](int fileIndex, int depth) -> bool {
        if (depth > 400)
            return true;
        RawFile* rf = mRaw[fileIndex].get();
        const std::vector<LineToks> lines = splitLines(rf->tokens);
        std::vector<CondState> conds;
        auto isActive = [&]() { return conds.empty() || conds.back().active; };
        int lineOffset = 0;   // for #line
        for (std::size_t li = 0; li < lines.size(); ++li) {
            const LineToks& lt = lines[li];
            if (lt.toks.empty())
                continue;
            if (lt.toks[0]->str != "#") {
                if (!isActive())
                    continue;
                for (const PPToken* t : lt.toks) {
                    ETok e;
                    e.t = *t;
                    e.t.line += lineOffset;
                    pending.push_back(e);
                }
                continue;
            }
            // directive
            const std::string cmd = lt.toks.size() >= 2 ? lt.toks[1]->str : "";
            if (cmd == "if" || cmd == "ifdef" || cmd == "ifndef") {
                if (!isActive()) {
                    conds.push_back({false, true, false});
                    continue;
                }
                bool val = false;
                if (cmd == "ifdef" || cmd == "ifndef") {
                    const bool def = lt.toks.size() >= 3 && macros.count(lt.toks[2]->str);
                    val = (cmd == "ifdef") ? def : !def;
                } else {
                    flush();
                    std::vector<ETok> expr;
                    for (std::size_t k = 2; k < lt.toks.size(); ++k) {
                        ETok e;
                        e.t = *lt.toks[k];
                        expr.push_back(e);
                    }
                    val = evalCondition(expr, macros, expander, fileIndex);
                }
                conds.push_back({val, val, true});
                continue;
            }
            if (cmd == "elif") {
                if (conds.empty())
                    continue;
                CondState& c = conds.back();
                if (!c.parentActive || c.taken) {
                    c.active = false;
                    continue;
                }
                flush();
                std::vector<ETok> expr;
                for (std::size_t k = 2; k < lt.toks.size(); ++k) {
                    ETok e;
                    e.t = *lt.toks[k];
                    expr.push_back(e);
                }
                const bool val = evalCondition(expr, macros, expander, fileIndex);
                c.active = val;
                c.taken = val;
                continue;
            }
            if (cmd == "else") {
                if (conds.empty())
                    continue;
                CondState& c = conds.back();
                c.active = c.parentActive && !c.taken;
                c.taken = true;
                continue;
            }
            if (cmd == "endif") {
                if (!conds.empty())
                    conds.pop_back();
                continue;
            }
            if (!isActive())
                continue;
            if (cmd == "define" && lt.toks.size() >= 3) {
                flush();
                Macro m;
                m.name = lt.toks[2]->str;
                std::size_t k = 3;
                if (k < lt.toks.size() && lt.toks[k]->str == "(" && !lt.toks[k]->ws) {
                    m.functionLike = true;
                    ++k;
                    while (k < lt.toks.size() && lt.toks[k]->str != ")") {
                        if (lt.toks[k]->str == ",") {
                            ++k;
                            continue;
                        }
                        if (lt.toks[k]->str == "...") {
                            m.variadic = true;
                            m.params.push_back("__VA_ARGS__");
                        } else if (k + 1 < lt.toks.size() && lt.toks[k+1]->str == "...") {
                            m.variadic = true;
                            m.params.push_back(lt.toks[k]->str);
                            ++k;
                        } else
                            m.params.push_back(lt.toks[k]->str);
                        ++k;
                    }
                    ++k;
                }
                for (; k < lt.toks.size(); ++k)
                    m.body.push_back(*lt.toks[k]);
                macros[m.name] = m;
                continue;
            }
            if (cmd == "undef" && lt.toks.size() >= 3) {
                flush();
                macros.erase(lt.toks[2]->str);
                continue;
            }
            if (cmd == "include" && lt.toks.size() >= 3) {
                flush();
                std::string header;
                bool sys = false;
                std::vector<const PPToken*> htoks(lt.toks.begin() + 2, lt.toks.end());
                if (!htoks.empty() && htoks[0]->isName()) {
                    // macro include
                    std::vector<ETok> ex;
                    for (const PPToken* t : htoks) {
                        ETok e;
                        e.t = *t;
                        ex.push_back(e);
                    }
                    ex = expander.expand(ex);
                    htoks.clear();
                    static std::vector<PPToken> keep;
                    keep.clear();
                    for (ETok& e : ex)
                        keep.push_back(e.t);
                    for (PPToken& t : keep)
                        htoks.push_back(&t);
                }
                if (!htoks.empty() && htoks[0]->str.size() >= 2 && htoks[0]->str[0] == '"') {
                    header = htoks[0]->str.substr(1, htoks[0]->str.size() - 2);
                } else if (!htoks.empty() && htoks[0]->str == "<") {
                    sys = true;
                    for (std::size_t q = 1; q < htoks.size() && htoks[q]->str != ">"; ++q) {
                        if (q > 1 && htoks[q]->ws)
                            header += ' ';
                        header += htoks[q]->str;
                    }
                } else
                    continue;
                const std::string path = findInclude(header, sys, rf->path);
                if (path.empty()) {
                    missing.push_back({rf->path, lt.toks[0]->line + lineOffset, lt.toks[0]->col, header, sys});
                    continue;
                }
                const int fi = loadFile(path);
                if (fi < 0)
                    continue;
                if (pragmaOnce.count(fi))
                    continue;
                if (!processFile(fi, depth + 1))
                    return false;
                continue;
            }
            if (cmd == "pragma") {
                if (lt.toks.size() >= 3 && lt.toks[2]->str == "once")
                    pragmaOnce.insert(fileIndex);
                continue;
            }
            if (cmd == "error") {
                flush();
                std::string msg = "#error";
                for (std::size_t k = 2; k < lt.toks.size(); ++k)
                    msg += " " + lt.toks[k]->str;
                errorMsg = msg;
                errorTok = *lt.toks[0];
                errorTok.line += lineOffset;
                return false;
            }
            if (cmd == "line" && lt.toks.size() >= 3 && lt.toks[2]->isNumber()) {
                const int newLine = std::atoi(lt.toks[2]->str.c_str());
                // next physical line becomes newLine
                const int nextPhysical = lt.toks[0]->line + 1;
                lineOffset = newLine - nextPhysical;
                continue;
            }
        }
        return true;
    };

    const bool ok = processFile(0, 0);
    flush();
    if (!ok)
        return {};
    return output;
}
