extern bool isPathIgnored(const std::vector<std::string>& ignored, const std::string& path);

static bool isSourceExt(const std::string& path)
{
    const std::string ext = util::getFilenameExtension(path);
    static const char* exts[] = { ".cpp", ".cxx", ".cc", ".c++", ".c", ".ipp", ".ixx", ".tpp", ".txx", ".C", ".CPP" };
    for (const char* e : exts)
        if (ext == e)
            return true;
    return false;
}

static bool isCppFile(const std::string& path, const std::string& enforced)
{
    if (enforced == "c")
        return false;
    if (enforced == "c++")
        return true;
    const std::string ext = util::getFilenameExtension(path);
    if (ext == ".c" || ext == ".cl")
        return false;
    if (ext == ".h")
        return false;
    static const char* cppexts[] = { ".cpp", ".cxx", ".cc", ".c++", ".hpp", ".hxx", ".hh", ".tpp", ".txx", ".ipp", ".ixx", ".C", ".CPP", ".H", ".h++", ".hh" };
    for (const char* e : cppexts)
        if (ext == e)
            return true;
    return false;
}

static void listDir(const std::string& dir, std::vector<std::string>& out)
{
    DIR* d = opendir(dir.c_str());
    if (!d)
        return;
    std::vector<std::string> entries;
    while (struct dirent* e = readdir(d)) {
        const std::string name = e->d_name;
        if (name == "." || name == "..")
            continue;
        entries.push_back(name);
    }
    closedir(d);
    std::sort(entries.begin(), entries.end());
    std::vector<std::string> files;
    std::vector<std::string> dirs;
    for (const std::string& name : entries) {
        const std::string full = util::endsWith(dir, '/') ? dir + name : dir + "/" + name;
        if (util::isDirectory(full))
            dirs.push_back(full);
        else if (isSourceExt(full))
            files.push_back(full);
    }
    // files and directories sorted together by full path
    std::vector<std::pair<std::string, bool>> all;
    for (const std::string& f : files) all.emplace_back(f, false);
    for (const std::string& f : dirs) all.emplace_back(f, true);
    std::sort(all.begin(), all.end());
    for (const auto& a : all) {
        if (a.second)
            listDir(a.first, out);
        else
            out.push_back(a.first);
    }
}

void AnalysisContext::reportError(const std::list<FileLocation>& cs, Severity sev, const std::string& id, const std::string& msg, int cwe, bool inconclusive)
{
    ErrorMessage em(cs, file0, sev, msg, id, cwe, inconclusive);
    // suppression handling
    std::string file;
    int line = 0;
    if (!cs.empty()) {
        file = cs.back().file;
        line = cs.back().line;
    }
    for (Suppression& s : supprs.nomsg.get()) {
        if (s.isMatch(file, line, id, em.symbolNames, 0)) {
            s.matched = true;
            return;
        }
    }
    bool nofail = false;
    for (Suppression& s : supprs.nofail.get()) {
        if (s.isMatch(file, line, id, em.symbolNames, 0)) {
            s.matched = true;
            nofail = true;
        }
    }
    const bool hadError = out.anyError();
    const bool printed = out.report(em);
    (void)printed;
    if (nofail && !hadError) {
        // don't let this message affect the exit code
        out.resetAnyError();
    }
    if (id == "syntaxError" || id == "preprocessorErrorDirective" || id == "unknownMacro" || id == "internalAstError" || id == "cppcheckError" || id == "internalError") {
        criticalError = true;
        criticalIds.insert(id);
    }
}

static std::string displayCfg(const std::string& cfg)
{
    std::string ret;
    for (const std::string& part : util::split(cfg, ';')) {
        if (!ret.empty())
            ret += ';';
        if (part.find('=') == std::string::npos)
            ret += part + "=" + part;
        else
            ret += part;
    }
    return ret;
}

static std::string tokensSignature(const std::vector<PPToken>& toks)
{
    std::string s;
    for (const PPToken& t : toks) {
        s += t.str;
        s += ' ';
        s += std::to_string(t.fileIndex) + ":" + std::to_string(t.line) + " ";
    }
    return s;
}

static void printPreprocessed(const std::vector<PPToken>& toks, Preprocessor& pp)
{
    std::string ret;
    int prevfile = 0;
    int line = 1;
    bool first = true;
    for (const PPToken& tok : toks) {
        if (tok.fileIndex != prevfile) {
            ret += "\n#line " + std::to_string(tok.line) + " \"" + pp.files()[tok.fileIndex] + "\"\n";
            prevfile = tok.fileIndex;
            line = tok.line;
        }
        if (!first && line >= tok.line)
            ret += ' ';
        while (tok.line > line) {
            ret += '\n';
            line++;
        }
        if (tok.macroExpanded)
            ret += ' ';
        ret += tok.str;
        first = false;
    }
    std::cout << ret << std::endl;
}

int runAnalysis(Settings& settings, Suppressions& supprs, const CmdLineParser& parser)
{
    // collect files
    struct FileEntry {
        std::string path;
        std::size_t size;
        const FileSettings* fs;
    };
    std::vector<FileEntry> files;
    std::set<std::string> seen;
    const std::vector<std::string>& ignored = parser.getIgnoredPaths();
    if (!parser.getFileSettings().empty()) {
        for (const FileSettings& fs : parser.getFileSettings()) {
            struct stat st;
            std::size_t sz = 0;
            if (stat(fs.filename.c_str(), &st) == 0)
                sz = st.st_size;
            files.push_back({fs.filename, sz, &fs});
        }
    } else {
        for (const std::string& p0 : parser.getPathNames()) {
            const std::string p = util::simplifyPath(p0);
            std::vector<std::string> found;
            if (util::isDirectory(p)) {
                listDir(p.empty() ? "." : p, found);
            } else if (util::isFile(p)) {
                found.push_back(p);
            }
            for (const std::string& f0 : found) {
                const std::string f = util::simplifyPath(f0);
                if (seen.count(f))
                    continue;
                if (isPathIgnored(ignored, f))
                    continue;
                if (!settings.fileFilters.empty()) {
                    bool match = false;
                    for (const std::string& flt : settings.fileFilters)
                        if (matchglob(flt, f))
                            match = true;
                    if (!match)
                        continue;
                }
                seen.insert(f);
                struct stat st;
                std::size_t sz = 0;
                if (stat(f.c_str(), &st) == 0)
                    sz = st.st_size;
                files.push_back({f, sz, nullptr});
            }
        }
        if (files.empty()) {
            if (!settings.fileFilters.empty())
                CmdLineParser::printError("could not find any files matching the filter.");
            else
                CmdLineParser::printError("could not find or open any of the paths given.");
            return EXIT_FAILURE;
        }
    }

    ErrorOutput out(settings, supprs);
    // templates
    std::string tf = settings.templateFormat;
    std::string tl = settings.templateLocation;
    if (tf.empty() || tf == "selfcheck") {
        tf = "{file}:{line}:{column}: {inconclusive:}{severity}:{inconclusive: inconclusive:} {message} [{id}]\\n{code}";
        if (tl.empty())
            tl = "{file}:{line}:{column}: note: {info}\\n{code}";
    } else if (tf == "gcc") {
        tf = "{file}:{line}:{column}: warning: {message} [{id}]\\n{code}";
        if (tl.empty())
            tl = "{file}:{line}:{column}: note: {info}\\n{code}";
    } else if (tf == "daca2") {
        tf = "{file}:{line}:{column}: {severity}:{inconclusive:inconclusive:} {message} [{id}]";
        if (tl.empty())
            tl = "{file}:{line}:{column}: note: {info}";
    } else if (tf == "vs") {
        tf = "{file}({line}): {severity}{inconclusive:, inconclusive}: {message}";
    } else if (tf == "edit") {
        tf = "{file} +{line}: {severity}{inconclusive:, inconclusive}: {message}";
    } else if (tf == "cppcheck1") {
        tf = "{callstack}: ({severity}{inconclusive:, inconclusive}) {message}";
    } else if (tf == "simple") {
        tf = "{file}:{line}:{column}: {severity}:{inconclusive:inconclusive:} {message} [{id}]";
    }
    auto unescape = [](std::string s) {
        std::string r;
        for (std::size_t i = 0; i < s.size(); ++i) {
            if (s[i] == '\\' && i + 1 < s.size()) {
                if (s[i+1] == 'n') { r += '\n'; ++i; continue; }
                if (s[i+1] == 't') { r += '\t'; ++i; continue; }
                if (s[i+1] == 'r') { r += '\r'; ++i; continue; }
            }
            r += s[i];
        }
        return r;
    };
    out.templateFormat = unescape(tf);
    out.templateLocation = unescape(tl);
    settings.templateLocation = out.templateLocation;

    if (settings.outputFormat == Settings::OutputFormat::xml)
        out.xmlHeader();

    std::size_t totalSize = 0;
    for (const FileEntry& f : files)
        totalSize += f.size;

    FunctionUsageInfo usage;
    std::set<std::string> activeCheckers;
    bool anyCritical = false;
    std::set<std::string> criticalIds;
    std::size_t processedSize = 0;
    std::set<std::string> checkedFiles;

    for (std::size_t fi = 0; fi < files.size(); ++fi) {
        const FileEntry& fe = files[fi];
        const std::string& path = fe.path;
        checkedFiles.insert(path);
        const bool cpp = isCppFile(path, settings.enforcedLang);
        if (!settings.quiet)
            std::cout << "Checking " << path << " ..." << std::endl;

        AnalysisContext ctx{settings, supprs, out};
        ctx.file0 = path;
        ctx.cpp = cpp;
        ctx.usage = &usage;

        Preprocessor pp(settings, cpp);
        if (!pp.loadMain(path)) {
            // could not read file
        } else {
            std::set<std::string> configs;
            const bool userDefs = !settings.userDefines.empty();
            if (userDefs && !settings.force && settings.maxConfigs == 1) {
                configs.insert(settings.userDefines);
            } else {
                configs = pp.getConfigs();
                if (userDefs) {
                    std::set<std::string> c2;
                    for (const std::string& c : configs) {
                        if (c.empty())
                            c2.insert(settings.userDefines);
                        else
                            c2.insert(c);
                    }
                    configs = c2;
                }
            }
            std::vector<std::string> cfgList(configs.begin(), configs.end());
            std::vector<std::string> checkedSigs;
            std::set<std::string> reportedMissing;
            int checkedCount = 0;
            const int maxConfigs = settings.preprocessOnly ? 0x7fffffff : settings.maxConfigs;
            bool fileCritical = false;
            for (const std::string& cfg : cfgList) {
                if (checkedCount >= maxConfigs)
                    break;
                ++checkedCount;
                if (!settings.quiet && !cfg.empty() && !settings.preprocessOnly)
                    std::cout << "Checking " << path << ": " << displayCfg(cfg) << "..." << std::endl;
                std::vector<MissingInclude> missing;
                std::string errMsg;
                PPToken errTok;
                std::vector<PPToken> toks = pp.preprocess(cfg, missing, errMsg, errTok);
                ctx.fileNames = pp.files();
                if (!settings.preprocessOnly && (settings.missingInclude)) {
                    for (const MissingInclude& mi : missing) {
                        std::list<FileLocation> cs;
                        cs.emplace_back(mi.file, mi.line, mi.col);
                        if (mi.system)
                            ctx.reportError(cs, Severity::information, "missingIncludeSystem",
                                            "Include file: <" + mi.header + "> not found. Please note: Standard library headers do not need to be provided to get proper results.", 0);
                        else
                            ctx.reportError(cs, Severity::information, "missingInclude",
                                            "Include file: \"" + mi.header + "\" not found.", 0);
                    }
                }
                if (!errMsg.empty()) {
                    if (settings.preprocessOnly) {
                        std::cout << std::endl;
                        continue;
                    }
                    std::list<FileLocation> cs;
                    cs.emplace_back(pp.files()[errTok.fileIndex], errTok.line, errTok.col + 1);
                    ctx.reportError(cs, Severity::error, "preprocessorErrorDirective", errMsg, 0);
                    fileCritical = true;
                    continue;
                }
                if (settings.preprocessOnly) {
                    printPreprocessed(toks, pp);
                    continue;
                }
                const std::string sig = tokensSignature(toks);
                if (std::find(checkedSigs.begin(), checkedSigs.end(), sig) != checkedSigs.end())
                    continue;
                checkedSigs.push_back(sig);
                ctx.criticalError = false;
                analyzeTokens(ctx, toks, pp);
                if (ctx.criticalError)
                    fileCritical = true;
                else {
                    for (const CheckerInfo& c : allCheckers())
                        if (checkerActive(c, settings, cpp))
                            activeCheckers.insert(c.name);
                }
            }
            if (fileCritical) {
                anyCritical = true;
                criticalIds.insert(ctx.criticalIds.begin(), ctx.criticalIds.end());
            }
            if ((int)cfgList.size() > settings.maxConfigs && settings.isEnabled(Severity::information) && !settings.maxConfigsSet && !settings.force && !settings.preprocessOnly && settings.userDefines.empty()) {
                std::list<FileLocation> cs;
                cs.emplace_back(path, 0, 0);
                ctx.reportError(cs, Severity::information, "toomanyconfigs",
                                "Too many #ifdef configurations - cppcheck only checks " + std::to_string(settings.maxConfigs) +
                                " of " + std::to_string(cfgList.size()) + " configurations. Use --force to check all configurations.", 398);
            }
        }

        processedSize += fe.size;
        if (!settings.quiet && files.size() > 1) {
            const std::size_t percent = totalSize ? (processedSize * 100) / totalSize : 0;
            std::cout << (fi + 1) << "/" << files.size() << " files checked " << percent << "% done" << std::endl;
        }
    }

    if (settings.preprocessOnly)
        return EXIT_SUCCESS;

    // whole program analysis
    {
        AnalysisContext ctx{settings, supprs, out};
        ctx.usage = &usage;
        analyzeWholeProgram(ctx);
    }
    activeCheckers.insert("CheckBufferOverrun::analyseWholeProgram");
    activeCheckers.insert("CheckClass::analyseWholeProgram");
    activeCheckers.insert("CheckNullPointer::analyseWholeProgram");
    activeCheckers.insert("CheckUninitVar::analyseWholeProgram");

    // unmatched suppressions
    if (settings.isEnabled(Severity::information)) {
        AnalysisContext ctx{settings, supprs, out};
        for (const Suppression& s : supprs.nomsg.get()) {
            if (s.matched)
                continue;
            if (s.errorId == "unmatchedSuppression" || s.errorId == "*")
                continue;
            if (!s.fileName.empty()) {
                bool anyFile = false;
                for (const std::string& f : checkedFiles)
                    if (matchglob(s.fileName, f))
                        anyFile = true;
                if (!anyFile)
                    continue;
            }
            std::list<FileLocation> cs;
            if (!s.fileName.empty())
                cs.emplace_back(s.fileName, s.lineNumber == Suppression::NO_LINE ? 0 : s.lineNumber, 0);
            ctx.reportError(cs, Severity::information, "unmatchedSuppression", "Unmatched suppression: " + s.errorId, 0);
        }
    }

    std::vector<std::string> activeList;
    for (const CheckerInfo& c : allCheckers())
        if (activeCheckers.count(c.name))
            activeList.push_back(c.name);

    if (settings.isEnabled(Severity::information)) {
        std::string msg;
        if (anyCritical)
            msg = "Active checkers: There was critical errors (use --checkers-report=<filename> to see details)";
        else
            msg = "Active checkers: " + std::to_string(activeList.size()) + "/" + std::to_string(allCheckers().size()) + " (use --checkers-report=<filename> to see details)";
        ErrorMessage em({}, "", Severity::information, msg, "checkersReport", 0, false);
        out.report(em);
    }

    if (!settings.checkersReportFilename.empty()) {
        std::ofstream fout(settings.checkersReportFilename);
        fout << "Critical errors\n---------------\n";
        if (!anyCritical) {
            fout << "No critical errors encountered.\n";
            fout << "Note: There might still have been non-critical bailouts which might lead to false negatives.\n";
        } else {
            std::string ids;
            for (const std::string& c : criticalIds)
                ids += (ids.empty() ? "" : ",") + c;
            fout << "There were critical errors (" << ids << ").\n";
            fout << "These cause the analysis of the file to end prematurely.\n";
        }
        fout << "\n\nOpen source checkers\n--------------------\n";
        for (const CheckerInfo& c : allCheckers()) {
            const bool yes = activeCheckers.count(c.name) != 0;
            std::string line = yes ? "Yes  " : "No   ";
            line += c.name;
            if (!yes && c.requirement[0]) {
                std::string pad = c.name;
                while (pad.size() < 58)
                    pad += ' ';
                line = "No   " + pad + "require:" + c.requirement;
            }
            fout << line << "\n";
        }
    }

    if (settings.outputFormat == Settings::OutputFormat::xml)
        out.xmlFooter(activeList, criticalIds);

    if (out.anyError() && settings.exitCode)
        return settings.exitCode;
    return EXIT_SUCCESS;
}
