#include <cstring>

static const char* kKeywords[] = {
    "auto", "break", "case", "char", "const", "continue", "default", "do", "double", "else", "enum", "extern", "float", "for",
    "goto", "if", "inline", "int", "long", "register", "restrict", "return", "short", "signed", "sizeof", "static", "struct",
    "switch", "typedef", "union", "unsigned", "void", "volatile", "while", "_Bool", "bool", "class", "namespace", "new", "delete",
    "template", "typename", "this", "throw", "try", "catch", "virtual", "public", "private", "protected", "operator", "friend",
    "using", "explicit", "mutable", "constexpr", "nullptr", "true", "false", "static_cast", "dynamic_cast", "reinterpret_cast",
    "const_cast", "noexcept", "override", "final", "decltype", "typeid", "alignof", "static_assert", "thread_local", "wchar_t",
    nullptr
};

bool Token::isKeyword() const
{
    for (const char** k = kKeywords; *k; ++k)
        if (str == *k)
            return true;
    return false;
}

static bool isOpStr(const std::string& s)
{
    static const char* ops[] = { "+", "-", "*", "/", "%", "&", "|", "^", "~", "!", "=", "<", ">", "<=", ">=", "==", "!=",
                                 "&&", "||", "<<", ">>", "+=", "-=", "*=", "/=", "%=", "&=", "|=", "^=", "<<=", ">>=",
                                 "++", "--", "?", ":", nullptr };
    for (const char** o = ops; *o; ++o)
        if (s == *o)
            return true;
    return false;
}

static bool matchItem(const Token* tok, const char* item, std::size_t len)
{
    // alternatives separated by '|', but "|" alone and "||" are tokens
    if (len == 1 && item[0] == '|')
        return tok && tok->str == "|";
    if (len == 2 && item[0] == '|' && item[1] == '|')
        return tok && tok->str == "||";
    if (len >= 2 && item[0] == '!' && item[1] == '!') {
        if (!tok)
            return true;
        return tok->str != std::string(item + 2, len - 2);
    }
    std::size_t start = 0;
    bool allowEmpty = false;
    while (start <= len) {
        std::size_t end = start;
        while (end < len && item[end] != '|')
            ++end;
        // handle "||" and "|" as alternatives e.g. "&&|%oror%" - not supported specially
        const std::string alt(item + start, end - start);
        if (alt.empty()) {
            allowEmpty = true;
        } else if (tok) {
            if (alt == "%name%") { if (tok->isName()) return true; }
            else if (alt == "%var%") { if (tok->varId > 0) return true; }
            else if (alt == "%num%") { if (tok->isNumber()) return true; }
            else if (alt == "%str%") { if (tok->isString()) return true; }
            else if (alt == "%char%") { if (tok->isChar()) return true; }
            else if (alt == "%any%") { return true; }
            else if (alt == "%op%") { if (isOpStr(tok->str)) return true; }
            else if (alt == "%or%") { if (tok->str == "|") return true; }
            else if (alt == "%oror%") { if (tok->str == "||") return true; }
            else if (alt == "%assign%") { if (tok->isAssignmentOp()) return true; }
            else if (alt == "%comp%") { if (tok->isComparisonOp()) return true; }
            else if (alt == "%cop%") { if (isOpStr(tok->str) && !tok->isAssignmentOp()) return true; }
