    }
    return s;
}

bool Variable::isIntegral() const
{
    if (pointer || isArray || isClassType)
        return false;
    for (const Token* t = typeStart; t; t = t->next) {
        if (t->str == "float" || t->str == "double" || t->str == "void")
            return false;
        if (t == typeEnd)
            break;
    }
