        return false;
    for (const Token* t = typeStart; t; t = t->next) {
        if (t->str == "float" || t->str == "double")
            return true;
        if (t == typeEnd)
            break;
    }
    return false;
}

bool Variable::isBuiltin() const
{
    for (const Token* t = typeStart; t; t = t->next) {
        if (kBuiltinTypes.count(t->str) && t->str != "FILE")
            return true;
        if (t == typeEnd)
            break;
