TokenizeResult Tokenizer::tokenize(const std::vector<PPToken>& toks, const std::vector<std::string>& files, bool isCpp)
{
    TokenizeResult res;
    cpp = isCpp;
    list.files = files;
    createTokens(toks);
    if (!linkBrackets(res))
        return res;
    simplify();
    addBraces();
    list.reindex();
    createSymbolDatabase();
    createAst();
    list.reindex();
    return res;
}

bool Tokenizer::createTokens(const std::vector<PPToken>& toks)
{
    for (const PPToken& p : toks) {
        Token* t = list.append(p.str, p.fileIndex, p.line, p.col);
        t->macro = p.macroExpanded;
    }
    return true;
}

bool Tokenizer::linkBrackets(TokenizeResult& res)
{
    std::vector<Token*> stack;
    for (Token* t = list.front; t; t = t->next) {
        if (t->str == "(" || t->str == "[" || t->str == "{") {
            stack.push_back(t);
        } else if (t->str == ")" || t->str == "]" || t->str == "}") {
            const char open = t->str == ")" ? '(' : (t->str == "]" ? '[' : '{');
            if (stack.empty() || stack.back()->str[0] != open) {
                res.ok = false;
                if (stack.empty()) {
                    res.errTok = t;
                    res.errMsg = "syntax error";
                } else {
                    res.errTok = stack.back();
                    res.errMsg = "syntax error";
                }
                return false;
            }
            t->link = stack.back();
            stack.back()->link = t;
            stack.pop_back();
        }
    }
    if (!stack.empty()) {
        res.ok = false;
        res.errTok = stack.back();
        res.errMsg = "syntax error";
        return false;
    }
    return true;
}

void Tokenizer::simplify()
{
    for (Token* t = list.front; t; t = t->next) {
        // remove __attribute__((...)) and __declspec(...)
        while ((t->str == "__attribute__" || t->str == "__attribute" || t->str == "__declspec" || t->str == "_Alignas" || t->str == "alignas") &&
               t->next && t->next->str == "(") {
            Token* end = t->next->link;
            Token* after = end->next;
            Token* prev = t->prev;
            for (Token* x = t; x != after;) {
                Token* nx = x->next;
                list.erase(x);
                x = nx;
            }
            if (!after)
                return;
            t = after;
            (void)prev;
        }
        // [[attributes]]
        if (t->str == "[" && t->next && t->next->str == "[" && t->link && t->next->link && t->next->link->next == t->link) {
            Token* end = t->link;
            Token* after = end->next;
            for (Token* x = t; x != after;) {
                Token* nx = x->next;
                list.erase(x);
                x = nx;
            }
            if (!after)
                return;
            t = after;
        }
        // extern "C" {
        if (t->str == "extern" && t->next && t->next->str == "\"C\"" ) {
            Token* n = t->next->next;
            if (n && n->str == "{") {
                Token* close = n->link;
                Token* after = n->next;
                list.erase(t->next);
                list.erase(n);
                list.erase(close);
                Token* prev = t->prev;
                list.erase(t);
                t = prev ? prev : after;
                if (!t)
                    return;
                continue;
            } else {
                list.erase(t->next);
            }
        }
    }
}

// returns the last token of the statement starting at tok
static Token* statementEnd(Token* tok)
{
    if (!tok)
        return nullptr;
    if (tok->str == "{")
        return tok->link;
    if (tok->str == "if" && tok->next && tok->next->str == "(") {
        Token* body = tok->next->link->next;
        Token* end = statementEnd(body);
        if (end && end->next && end->next->str == "else")
            return statementEnd(end->next->next);
        return end;
    }
    if ((tok->str == "for" || tok->str == "while" || tok->str == "switch") && tok->next && tok->next->str == "(") {
        Token* body = tok->next->link->next;
        return statementEnd(body);
    }
    if (tok->str == "do") {
        Token* end = statementEnd(tok->next);
        if (end && end->next && end->next->str == "while" && end->next->next && end->next->next->str == "(") {
            Token* close = end->next->next->link;
            if (close->next && close->next->str == ";")
                return close->next;
            return close;
        }
        return end;
    }
    if (tok->str == "try") {
        Token* end = statementEnd(tok->next);
        while (end && end->next && end->next->str == "catch" && end->next->next && end->next->next->str == "(")
            end = statementEnd(end->next->next->link->next);
        return end;
    }
    // case labels: "case X :" stmt
    for (Token* t = tok; t; t = t->next) {
        if (t->str == "(" || t->str == "[" || (t->str == "{" && t->link))
            t = t->link;
        else if (t->str == ";")
            return t;
        else if (t->str == "}")
            return t->prev;
    }
    return nullptr;
}

void Tokenizer::addBraces()
{
    for (Token* t = list.front; t; t = t->next) {
        Token* bodyStart = nullptr;
        if ((t->str == "if" || t->str == "for" || t->str == "while" || t->str == "switch") && t->next && t->next->str == "(") {
            // 'while' of do-while: skip
            if (t->str == "while" && t->prev && t->prev->str == "}" && t->prev->link && t->prev->link->prev && t->prev->link->prev->str == "do")
                continue;
            bodyStart = t->next->link->next;
        } else if (t->str == "else" || t->str == "do") {
            bodyStart = t->next;
        } else
            continue;
        if (!bodyStart || bodyStart->str == "{")
            continue;
        if (t->str == "while" && bodyStart->str == ";")
            ; // empty loop body
        Token* end = statementEnd(bodyStart);
        if (!end)
            continue;
        Token* open = list.insertBefore(bodyStart, "{");
        Token* close = list.insertAfter(end, "}");
        open->link = close;
        close->link = open;
        // location of virtual braces
        open->line = bodyStart->line;
        open->col = bodyStart->col;
        close->line = end->line;
        close->col = end->col;
    }
}

static bool isTypeName(const Token* t, const std::set<std::string>& userTypes)
{
    if (!t || !t->isName())
        return false;
    return kBuiltinTypes.count(t->str) || userTypes.count(t->str);
}

namespace {
struct VarScopeStack {
    std::vector<std::map<std::string, Variable*>> frames;
    void push() { frames.emplace_back(); }
    void pop() { frames.pop_back(); }
    void add(Variable* v) { if (!frames.empty()) frames.back()[v->name] = v; }
    Variable* find(const std::string& n) const {
        for (auto it = frames.rbegin(); it != frames.rend(); ++it) {
            auto f = it->find(n);
            if (f != it->end())
                return f->second;
        }
        return nullptr;
    }
};
}

void Tokenizer::createSymbolDatabase()
{
    std::set<std::string> userTypes;
    // collect user type names: struct/class/union/enum names and typedef names
    for (Token* t = list.front; t; t = t->next) {
        if ((t->str == "struct" || t->str == "class" || t->str == "union" || t->str == "enum") && t->next && t->next->isName()) {
            Token* n = t->next;
            if (n->str == "class" || n->str == "struct")
                n = n->next;
            if (n && n->isName())
                userTypes.insert(n->str);
        }
        if (t->str == "typedef") {
            // name is last name before ';' at depth 0 (or inside parens for function pointers)
            Token* last = nullptr;
            for (Token* x = t->next; x && x->str != ";"; x = x->next) {
                if (x->str == "{" || x->str == "(" || x->str == "[") {
                    if (x->str == "(" && x->next && x->next->str == "*" && x->next->next && x->next->next->isName())
                        last = x->next->next;
                    x = x->link;
                    continue;
                }
                if (x->isName())
                    last = x;
            }
            if (last)
                userTypes.insert(last->str);
        }
        if (t->str == "using" && t->next && t->next->isName() && t->next->next && t->next->next->str == "=")
            userTypes.insert(t->next->str);
        if (t->str == "template" && t->next && t->next->str == "<") {
            for (Token* x = t->next->next; x && x->str != ">"; x = x->next)
                if ((x->str == "typename" || x->str == "class") && x->next && x->next->isName())
                    userTypes.insert(x->next->str);
        }
    }
    if (cpp) {
        userTypes.insert("string");
        userTypes.insert("vector");
    }

    db.scopes.emplace_back();
    Scope* global = &db.scopes.back();
    global->type = Scope::eGlobal;
    db.global = global;
    db.varById.push_back(nullptr);

    VarScopeStack vstack;
    vstack.push();

    auto newScope = [&](Scope::Type type, Scope* parent, Token* bodyStart) -> Scope* {
        db.scopes.emplace_back();
        Scope* s = &db.scopes.back();
        s->type = type;
        s->nestedIn = parent;
        s->bodyStart = bodyStart;
        s->bodyEnd = bodyStart ? bodyStart->link : nullptr;
        parent->nested.push_back(s);
        return s;
    };

    auto newVar = [&](Token* nameTok, Token* typeStart, Token* typeEnd, Scope* scope) -> Variable* {
        db.variables.emplace_back();
        Variable* v = &db.variables.back();
        v->name = nameTok->str;
        v->nameTok = nameTok;
        v->typeStart = typeStart;
        v->typeEnd = typeEnd;
        v->scope = scope;
        v->varId = (int)db.varById.size();
        db.varById.push_back(v);
        nameTok->varId = v->varId;
        nameTok->var = v;
        for (Token* t = typeStart; t && t != nameTok; t = t->next) {
            if (t->str == "*")
                v->pointer++;
            else if (t->str == "&" || t->str == "&&")
                v->isReference = true;
            else if (t->str == "static")
                v->isStatic = true;
            else if (t->str == "extern")
                v->isExtern = true;
            else if (t->str == "const") {
                // const after last '*' => const variable; before any '*' => const pointee
                bool starAfter = false;
                for (Token* x = t->next; x && x != nameTok; x = x->next)
                    if (x->str == "*")
                        starAfter = true;
                if (starAfter)
                    v->isConstPointee = true;
                else
                    v->isConst = true;
            }
            if (t->isName() && !kBuiltinTypes.count(t->str) && !kDeclSpecifiers.count(t->str) && t->str != "struct" && t->str != "union" && t->str != "enum" && t->str != "class" && t->str != "std" && t->str != "unsigned" && t->str != "signed")
                v->isClassType = true;
            if (t->str == "struct" || t->str == "union")
                v->isStruct = true;
            if (t == typeEnd)
                break;
        }
        if (v->pointer > 0 && v->isConst) {
            // "const int *p" => const pointee, not const pointer
            bool constBeforeStar = false;
            for (Token* t = typeStart; t && t != nameTok; t = t->next) {
                if (t->str == "*")
                    break;
                if (t->str == "const")
                    constBeforeStar = true;
            }
            if (constBeforeStar) {
                v->isConstPointee = true;
                bool constAfterStar = false;
                bool seenStar = false;
                for (Token* t = typeStart; t && t != nameTok; t = t->next) {
                    if (t->str == "*")
                        seenStar = true;
                    else if (seenStar && t->str == "const")
                        constAfterStar = true;
                }
                v->isConst = constAfterStar;
            }
        }
        // arrays
        Token* after = nameTok->next;
        while (after && after->str == "[") {
            v->isArray = true;
            long long dim = -1;
            if (after->next && after->next->isNumber() && after->next->next == after->link) {
                const std::string& n = after->next->str;
                char* end;
                dim = std::strtoll(n.c_str(), &end, 0);
                while (*end == 'u' || *end == 'U' || *end == 'l' || *end == 'L') ++end;
                if (*end) dim = -1;
            }
            v->dims.push_back(dim);
            after = after->link->next;
        }
        scope->varlist.push_back(v);
        vstack.add(v);
        return v;
    };

    // parse a declaration starting at 'start' in 'scope'. returns token after declaration or nullptr if not a declaration
    // fills declared variables
    std::function<Token*(Token*, Scope*, bool)> parseDeclaration;
    parseDeclaration = [&](Token* start, Scope* scope, bool allowInit) -> Token* {
        Token* t = start;
        Token* typeStart = start;
        bool sawType = false;
        bool sawStatic = false, sawExtern = false;
        // specifiers and type
        while (t) {
            if (kDeclSpecifiers.count(t->str)) {
                if (t->str == "static") sawStatic = true;
                if (t->str == "extern") sawExtern = true;
                t = t->next;
                continue;
            }
            if ((t->str == "struct" || t->str == "union" || t->str == "enum" || t->str == "class") && t->next && t->next->isName()) {
                t = t->next->next;
                sawType = true;
                break;
            }
            if (t->str == "unsigned" || t->str == "signed" || t->str == "long" || t->str == "short") {
                sawType = true;
                t = t->next;
                while (t && (t->str == "int" || t->str == "long" || t->str == "char" || t->str == "short" || t->str == "double" || t->str == "unsigned" || t->str == "signed"))
                    t = t->next;
                break;
            }
            if (t->str == "::" && t->next && t->next->isName()) {
                t = t->next;
                continue;
            }
            if (isTypeName(t, userTypes) || (t->isName() && t->next && t->next->str == "::")) {
                // qualified names
                while (t && t->isName() && t->next && t->next->str == "::" && t->next->next && t->next->next->isName())
                    t = t->next->next;
                sawType = true;
                t = t->next;
                // template args
                if (t && t->str == "<") {
                    Token* close = findClosingBracket(t);
                    if (close)
                        t = close->next;
                }
                break;
            }
            break;
        }
        if (!sawType || !t)
            return nullptr;
        // trailing const/volatile
        while (t && (t->str == "const" || t->str == "volatile"))
            t = t->next;
        Token* declStart = t;
        // declarators
        Token* last = nullptr;
        for (;;) {
            Token* d = declStart;
            while (d && (d->str == "*" || d->str == "&" || d->str == "&&" || d->str == "const" || d->str == "volatile" || d->str == "restrict" || d->str == "__restrict"))
                d = d->next;
            if (!d || !d->isName() || d->isKeyword() || (d->next && d->next->str == "::"))
                return last;
            Token* nameTok = d;
            Token* n = d->next;
            if (!n)
                return last;
            if (n->str == "(") {
                // function declaration or ctor init: not handled here
                if (!allowInit || !cpp)
                    return last;
                // C++ direct init "T x(args);" only for class types and if args look like expressions
                Token* close = n->link;
                if (!close->next || (close->next->str != ";" && close->next->str != ","))
                    return last;
                bool looksLikeParams = false;
                for (Token* x = n->next; x != close; x = x->next)
                    if (isTypeName(x, userTypes) && x->next && (x->next->isName() || x->next->str == "*" || x->next->str == "&"))
                        looksLikeParams = true;
                if (n->next == close || looksLikeParams)
                    return last;
            }
            if (!(n->str == ";" || n->str == "," || n->str == "=" || n->str == "[" || n->str == "(" || n->str == "{" || n->str == ")" || n->str == ":"))
                return last;
            Token* typeEnd = nameTok->prev;
            Variable* v = newVar(nameTok, typeStart, typeEnd, scope);
            v->isStatic = v->isStatic || sawStatic;
            v->isExtern = v->isExtern || sawExtern;
            Token* after = nameTok->next;
            while (after && after->str == "[")
                after = after->link->next;
            if (after && after->str == ":" && scope->isClassOrStruct()) {
                // bitfield
                after = after->next;
                while (after && after->str != ";" && after->str != ",")
                    after = after->next;
            }
            if (after && (after->str == "=" || after->str == "(" || after->str == "{")) {
                v->hasInit = true;
                v->initTok = (after->str == "=") ? after->next : after;
                // skip initializer
                Token* x = after->str == "=" ? after->next : after;
                for (; x && x->str != ";" && x->str != ","; x = x->next) {
                    if (x->str == "(" || x->str == "[" || x->str == "{")
                        x = x->link;
                    if (!x)
                        break;
                }
                after = x;
            }
            v->declEnd = after;
            last = after;
            if (!after || after->str != ",")
                return last;
            declStart = after->next;
            if (scope->type == Scope::eFunction && !allowInit)
                return last;
        }
    };

    // parse function arguments, create variables in function scope
    auto parseArgs = [&](Function* f, Scope* fscope) {
        Token* open = f->argStart;
        Token* close = open->link;
        Token* argStart = open->next;
        int index = 0;
        while (argStart && argStart != close) {
            Token* argEnd = argStart;
            while (argEnd != close && argEnd->str != ",") {
                if (argEnd->str == "(" || argEnd->str == "[" || argEnd->str == "{")
                    argEnd = argEnd->link;
                else if (argEnd->str == "<") {
                    Token* c = findClosingBracket(argEnd);
                    if (c) argEnd = c;
                }
                argEnd = argEnd->next;
            }
            // find name: last name token before argEnd that is not a type keyword, skipping [] and default value
            Token* nameTok = nullptr;
            Token* stop = argEnd;
            for (Token* x = argStart; x != argEnd; x = x->next) {
                if (x->str == "=") { stop = x; break; }
            }
            for (Token* x = argStart; x != stop; x = x->next) {
                if (x->str == "[" || (x->str == "(" && x->link)) {
                    if (x->str == "(" && x->next && x->next->str == "*" && x->next->next && x->next->next->isName())
                        nameTok = x->next->next;
                    x = x->link;
                    continue;
                }
                if (x->isName() && !kBuiltinTypes.count(x->str) && !kDeclSpecifiers.count(x->str) && x->str != "struct" && x->str != "union" && x->str != "enum" && x->str != "class" && x != argStart && !(x->next && x->next->str == "::") && !(x->prev && (x->prev->str == "struct" || x->prev->str == "union" || x->prev->str == "enum")))
                    nameTok = x;
                else if (x->isName() && x == argStart && !isTypeName(x, userTypes) && !kDeclSpecifiers.count(x->str) && x->next == stop)
                    nameTok = nullptr;
            }
            if (nameTok && !(argStart->str == "void" && argStart->next == argEnd)) {
                Token* typeEnd = nameTok->prev;
                Variable* v = newVar(nameTok, argStart, typeEnd, fscope);
                v->isArgument = true;
                v->argIndex = index;
                f->args.push_back(v);
                // array argument
                if (nameTok->next && nameTok->next->str == "[") {
                    v->isArray = false;
                    v->pointer++;
                    v->dims.clear();
                }
            } else if (!(argStart->str == "void" && argStart->next == argEnd) && argStart != argEnd) {
                // unnamed argument
                f->args.push_back(nullptr);
            }
            ++index;
            argStart = (argEnd == close) ? close : argEnd->next;
        }
    };

    // Recursive scope walker
    std::function<void(Scope*, Token*, Token*)> walk;

    auto setVarIdsInRange = [&](Token* from, Token* to, Scope* scope) {
        for (Token* x = from; x && x != to; x = x->next) {
            if (x->isName() && x->varId == 0 && !x->isKeyword() && !(x->prev && (x->prev->str == "." || x->prev->str == "->")) &&
                !(x->next && x->next->str == "::") && !(x->prev && x->prev->str == "::" && x->prev->prev && x->prev->prev->isName())) {
                Variable* v = vstack.find(x->str);
                if (v) {
                    x->varId = v->varId;
                    x->var = v;
                }
            }
            x->scope = scope;
        }
    };

    walk = [&](Scope* scope, Token* start, Token* end) {
        vstack.push();
        // add members for class scopes
        Token* t = start;
        bool atStatementStart = true;
        while (t && t != end) {
            t->scope = scope;
            if (t->str == ";") {
                atStatementStart = true;
                t = t->next;
                continue;
            }
            if (t->str == "}" ) {
                atStatementStart = true;
                t = t->next;
                continue;
            }
            if (scope->isExecutable()) {
                // control scopes
                if ((t->str == "if" || t->str == "while" || t->str == "for" || t->str == "switch") && t->next && t->next->str == "(") {
                    Token* open = t->next;
                    Token* close = open->link;
                    Token* body = close->next;
                    if (t->str == "while" && body && body->str == ";") {
                        // do-while tail
                        setVarIdsInRange(open, close->next, scope);
                        t = body;
                        continue;
                    }
                    if (!body || body->str != "{") {
                        setVarIdsInRange(open, close->next, scope);
                        t = close->next;
                        continue;
                    }
                    Scope::Type ty = t->str == "if" ? Scope::eIf : t->str == "while" ? Scope::eWhile : t->str == "for" ? Scope::eFor : Scope::eSwitch;
                    Scope* s = newScope(ty, scope, body);
                    s->classDef = t;
                    s->condStart = open;
                    t->scope = scope;
                    vstack.push();
                    if (ty == Scope::eFor) {
                        // for-init declaration
                        Token* init = open->next;
                        Token* declEnd = parseDeclaration(init, s, true);
                        (void)declEnd;
                    }
                    setVarIdsInRange(open, close->next, s);
                    open->scope = scope;
                    walk(s, body->next, body->link);
                    body->scope = s;
                    body->link->scope = s;
                    vstack.pop();
                    t = body->link->next;
                    atStatementStart = true;
                    continue;
                }
                if (t->str == "else" && t->next && t->next->str == "{") {
                    Scope* s = newScope(Scope::eElse, scope, t->next);
                    s->classDef = t;
                    walk(s, t->next->next, t->next->link);
                    t->next->scope = s;
                    t->next->link->scope = s;
                    t = t->next->link->next;
                    continue;
                }
                if (t->str == "do" && t->next && t->next->str == "{") {
                    Scope* s = newScope(Scope::eDo, scope, t->next);
                    s->classDef = t;
                    walk(s, t->next->next, t->next->link);
                    t->next->scope = s;
                    t->next->link->scope = s;
                    t = t->next->link->next;
                    continue;
                }
                if (t->str == "try" && t->next && t->next->str == "{") {
                    Scope* s = newScope(Scope::eTry, scope, t->next);
                    s->classDef = t;
                    walk(s, t->next->next, t->next->link);
                    t = t->next->link->next;
                    continue;
                }
                if (t->str == "catch" && t->next && t->next->str == "(" && t->next->link->next && t->next->link->next->str == "{") {
                    Token* body = t->next->link->next;
                    Scope* s = newScope(Scope::eCatch, scope, body);
                    s->classDef = t;
                    vstack.push();
                    parseDeclaration(t->next->next, s, false);
                    walk(s, body->next, body->link);
                    vstack.pop();
                    t = body->link->next;
                    continue;
                }
                if (t->str == "{") {
                    // lambda or initializer list or block
                    if (atStatementStart) {
                        Scope* s = newScope(Scope::eUnconditional, scope, t);
                        walk(s, t->next, t->link);
                        t->scope = s;
                        t->link->scope = s;
                        t = t->link->next;
                        continue;
                    }
                    // lambda: ") {" preceded by "] (" ... or "] {"
                    if (cpp && t->prev && (t->prev->str == ")" || t->prev->str == "]" || t->prev->str == "mutable")) {
                        Token* p = t->prev;
                        if (p->str == "mutable") p = p->prev;
                        Token* lbr = nullptr;
                        if (p->str == ")" && p->link->prev && p->link->prev->str == "]")
                            lbr = p->link->prev->link;
                        else if (p->str == "]")
                            lbr = p->link;
                        if (lbr) {
                            Scope* s = newScope(Scope::eLambda, scope, t);
                            vstack.push();
                            if (p->str == ")") {
                                db.functions.emplace_back();
                                Function* f = &db.functions.back();
                                f->argStart = p->link;
                                f->name = "lambda";
                                parseArgs(f, s);
                            }
                            walk(s, t->next, t->link);
                            vstack.pop();
                            t = t->link->next;
                            continue;
                        }
                    }
                    setVarIdsInRange(t, t->link, scope);
                    t = t->link->next;
                    continue;
                }
                if (atStatementStart && t->isName() && t->next && t->next->str == ":" && !t->isKeyword()) {
                    // label
                    t = t->next->next;
                    continue;
                }
                if (atStatementStart && (t->str == "case" || t->str == "default")) {
                    Token* x = t;
                    while (x && x != end && x->str != ":") {
                        x->scope = scope;
                        if (x->str == "(") x = x->link;
                        x = x->next;
                    }
                    setVarIdsInRange(t, x, scope);
                    t = x ? x->next : x;
                    atStatementStart = true;
                    continue;
                }
                if (atStatementStart) {
                    Token* declEnd = parseDeclaration(t, scope, true);
                    if (declEnd) {
                        // set varids in initializers
                        Token* stop = declEnd->str == ";" ? declEnd : declEnd;
                        // set varids for initializer tokens (variables declared are already in stack)
                        setVarIdsInRange(t, stop, scope);
                        t = stop;
                        atStatementStart = false;
                        continue;
                    }
                }
                // ordinary token
                if (t->isName() && t->varId == 0)
                    setVarIdsInRange(t, t->next, scope);
                atStatementStart = false;
                t = t->next;
                continue;
            }

            // non-executable scope: global, namespace, class
            if (t->str == "namespace" && t->next) {
                Token* x = t->next;
                std::string name;
                while (x && x->str != "{" && x->str != ";" && x->str != "=") {
                    if (x->isName()) name += x->str;
                    x = x->next;
                }
                if (x && x->str == "{") {
                    Scope* s = newScope(Scope::eNamespace, scope, x);
                    s->className = name;
                    walk(s, x->next, x->link);
                    t = x->link->next;
                    continue;
                }
                t = x ? x->next : x;
                continue;
            }
            if (t->str == "template" && t->next && t->next->str == "<") {
                Token* close = findClosingBracket(t->next);
                t = close ? close->next : t->next;
                continue;
            }
            if ((t->str == "public" || t->str == "private" || t->str == "protected") && t->next && t->next->str == ":") {
                t = t->next->next;
                continue;
            }
            if (t->str == "typedef") {
                // typedef struct {...} X; -> create struct scope for members
                Token* x = t->next;
                if (x && (x->str == "struct" || x->str == "union")) {
                    Token* b = x->next;
                    if (b && b->isName()) b = b->next;
                    if (b && b->str == "{") {
                        Scope* s = newScope(x->str == "union" ? Scope::eUnion : Scope::eStruct, scope, b);
                        s->classDef = x;
                        Token* nameAfter = b->link->next;
                        s->className = (x->next->isName()) ? x->next->str : (nameAfter && nameAfter->isName() ? nameAfter->str : "");
                        db.classScopes.push_back(s);
                        walk(s, b->next, b->link);
                        t = b->link->next;
                        while (t && t->str != ";") t = t->next;
                        continue;
                    }
                }
                while (t && t != end && t->str != ";") {
                    if (t->str == "{" || t->str == "(") t = t->link;
                    t = t->next;
                }
                continue;
            }
            if (t->str == "using" || t->str == "static_assert") {
                while (t && t != end && t->str != ";") {
                    if (t->str == "(" || t->str == "{") t = t->link;
                    t = t->next;
                }
                continue;
            }
            if ((t->str == "class" || t->str == "struct" || t->str == "union") && t->next && (t->next->isName() || t->next->str == "{")) {
                Token* nameTok = t->next->isName() ? t->next : nullptr;
                Token* x = t->next;
                while (x && x != end && x->str != "{" && x->str != ";" && x->str != "(" && x->str != "=") {
                    if (x->str == "<") { Token* c = findClosingBracket(x); if (c) x = c; }
                    x = x->next;
                }
                if (x && x->str == "{") {
                    Scope* s = newScope(t->str == "class" ? Scope::eClass : t->str == "struct" ? Scope::eStruct : Scope::eUnion, scope, x);
                    s->classDef = t;
                    s->className = nameTok ? nameTok->str : "";
                    db.classScopes.push_back(s);
                    walk(s, x->next, x->link);
                    // variables declared after struct body: struct S {...} s;
                    Token* after = x->link->next;
                    if (after && after->isName()) {
                        Token* de = parseDeclarationAfterBody(after, scope, t, x->link);
                        (void)de;
                    }
                    t = x->link->next;
                    while (t && t != end && t->str != ";") {
                        if (t->isName()) setVarIdsInRange(t, t->next, scope);
                        t = t->next;
                    }
                    continue;
                }
            }
            if (t->str == "enum") {
                Token* x = t->next;
                while (x && x != end && x->str != "{" && x->str != ";")
                    x = x->next;
                if (x && x->str == "{") {
                    Scope* s = newScope(Scope::eEnum, scope, x);
                    s->classDef = t;
                    for (Token* e = x->next; e && e != x->link; e = e->next)
                        e->scope = s;
                    t = x->link->next;
                    continue;
                }
            }
            // function definition / declaration?
            {
                Token* x = t;
                bool isStatic = false, isInline = false, isVirtual = false, isExtern = false;
                Token* retStart = t;
                // skip specifiers
                while (x && (kDeclSpecifiers.count(x->str))) {
                    if (x->str == "static") isStatic = true;
                    if (x->str == "inline" || x->str == "__inline" || x->str == "__inline__") isInline = true;
                    if (x->str == "virtual") isVirtual = true;
                    if (x->str == "extern") isExtern = true;
                    x = x->next;
                }
                // find '(' of function: name followed by '(' at this level before ';' '{' '='
                Token* nameTok = nullptr;
                for (Token* y = x; y && y != end; y = y->next) {
                    if (y->str == ";" || y->str == "{" || y->str == "=" || y->str == "}")
                        break;
                    if (y->str == "<") {
                        Token* c = findClosingBracket(y);
                        if (c) { y = c; continue; }
                    }
                    if (y->str == "(") {
                        if (y->prev && (y->prev->isName() || (y->prev->str == ">" ) || y->prev->str == "~")) {
                            Token* p = y->prev;
                            if (p->isName() && !p->isKeyword()) nameTok = p;
                            else if (p->isName() && p->str != "sizeof") nameTok = p;
                            // operator overloads
                            if (p->prev && p->prev->str == "operator")
                                nameTok = p->prev;
                        } else if (y->prev && y->prev->str != "operator" && y->prev->prev && y->prev->prev->str == "operator") {
                            nameTok = y->prev->prev;
                        }
                        // function pointer variable "int (*fp)(int)"
                        if (y->next && y->next->str == "*") { nameTok = nullptr; }
                        break;
                    }
                    if (y->str == "[")
                        break;
                }
                if (nameTok) {
                    Token* open = nameTok->next;
                    if (nameTok->str == "operator") {
                        open = nameTok->next;
                        while (open && open->str != "(") open = open->next;
                        if (open && open->next && open->next->str == ")" && open->next->next && open->next->next->str == "(")
                            open = open->next->next;
                    }
                    if (open && open->str == "(") {
                        Token* close = open->link;
                        Token* after = close->next;
                        bool isConst = false;
                        while (after && (after->str == "const" || after->str == "noexcept" || after->str == "override" || after->str == "final" ||
                                         after->str == "volatile" || after->str == "&" || after->str == "&&" || after->str == "throw" || after->str == "mutable")) {
                            if (after->str == "const") isConst = true;
                            if ((after->str == "throw" || after->str == "noexcept") && after->next && after->next->str == "(")
                                after = after->next->link;
                            after = after->next;
                        }
                        if (after && after->str == "->") {
                            while (after && after->str != "{" && after->str != ";")
                                after = after->next;
                        }
                        bool hasInitList = false;
                        if (after && after->str == ":" && cpp) {
                            hasInitList = true;
                            while (after && after != end && after->str != "{") {
                                if (after->str == "(") after = after->link;
                                else if (after->str == "{" ) break;
                                after = after->next;
                                if (after && after->str == "{" && after->prev && after->prev->isName() && after->link && after->link->next && (after->link->next->str == "," || after->link->next->str == "{")) {
                                    after = after->link->next;
                                }
                            }
                        }
                        if (after && (after->str == "{" || after->str == ";" || (after->str == "=" && after->next && (after->next->str == "0" || after->next->str == "default" || after->next->str == "delete")))) {
                            // looks like a function (declaration or definition); check it's not a variable with ctor init
                            bool looksLikeDecl = true;
                            if (after->str == ";" && scope->type != Scope::eGlobal && !scope->isClassOrStruct() && scope->type != Scope::eNamespace)
                                looksLikeDecl = false;
                            if (looksLikeDecl) {
                                db.functions.emplace_back();
                                Function* f = &db.functions.back();
                                f->name = nameTok->str;
                                if (nameTok->str == "operator") {
                                    f->isOperator = true;
                                    for (Token* o = nameTok->next; o != open; o = o->next) f->name += o->str;
                                }
                                f->tokenDef = nameTok;
                                f->argStart = open;
                                f->retStart = retStart;
                                f->isStatic = isStatic;
                                f->isInline = isInline;
                                f->isVirtual = isVirtual;
                                f->isExtern = isExtern;
                                f->isConst = isConst;
                                f->nestedIn = scope;
                                // class qualification
                                if (nameTok->prev && nameTok->prev->str == "::" && nameTok->prev->prev && nameTok->prev->prev->isName()) {
                                    f->className = nameTok->prev->prev->str;
                                    f->isMember = true;
                                    if (nameTok->prev->prev->str == nameTok->str)
                                        f->isConstructor = true;
                                    if (nameTok->prev->str == "::" && nameTok->str[0] == '~')
                                        f->isDestructor = true;
                                } else if (scope->isClassOrStruct()) {
                                    f->className = scope->className;
                                    f->isMember = true;
                                    if (nameTok->str == scope->className)
                                        f->isConstructor = true;
                                }
                                if (nameTok->prev && nameTok->prev->str == "~") {
                                    f->isDestructor = true;
                                    f->isConstructor = false;
                                }
                                {
                                    bool rv = false;
                                    for (Token* r = retStart; r && r != nameTok; r = r->next) {
                                        if (r->str == "void") rv = true;
                                        if (r->str == "*" ) rv = false;
                                    }
                                    f->returnsVoid = rv;
                                }
                                nameTok->func = f;
                                db.functionList.push_back(f);
                                scope->functions.push_back(f);
                                Scope* classScope = nullptr;
                                if (f->isMember && !scope->isClassOrStruct()) {
                                    for (Scope* cs : db.classScopes)
                                        if (cs->className == f->className)
                                            classScope = cs;
                                } else if (scope->isClassOrStruct())
                                    classScope = scope;
                                if (after->str == "{") {
                                    f->hasBody = true;
                                    Scope* fs = newScope(Scope::eFunction, scope, after);
                                    fs->function = f;
                                    fs->className = f->name;
                                    fs->classDef = nameTok;
                                    f->bodyScope = fs;
                                    f->bodyStart = after;
                                    f->bodyEnd = after->link;
                                    db.functionScopes.push_back(fs);
                                    vstack.push();
                                    if (classScope) {
                                        for (Variable* mv : classScope->varlist)
                                            vstack.add(mv);
                                    }
                                    vstack.push();
                                    parseArgs(f, fs);
                                    setVarIdsInRange(open, close->next, fs);
                                    if (hasInitList)
                                        setVarIdsInRange(close->next, after, fs);
                                    walk(fs, after->next, after->link);
                                    after->scope = fs;
                                    after->link->scope = fs;
                                    vstack.pop();
                                    vstack.pop();
                                    t = after->link->next;
                                    atStatementStart = true;
                                    continue;
                                } else {
                                    // declaration: parse args into a temporary scope
                                    db.scopes.emplace_back();
                                    Scope* tmp = &db.scopes.back();
                                    tmp->type = Scope::eFunction;
                                    tmp->nestedIn = scope;
                                    vstack.push();
                                    parseArgs(f, tmp);
                                    vstack.pop();
                                    t = after;
                                    while (t && t != end && t->str != ";") t = t->next;
                                    continue;
                                }
                            }
                        }
                    }
                }
            }
            // variable declaration at global/class scope
            {
                Token* declEnd = parseDeclaration(t, scope, true);
                if (declEnd) {
                    for (Variable* v : scope->varlist) {
                        if (scope->type == Scope::eGlobal || scope->type == Scope::eNamespace)
                            v->isGlobal = true;
                        else if (scope->isClassOrStruct())
                            v->isMember = true;
                    }
                    setVarIdsInRange(t, declEnd, scope);
                    t = declEnd;
                    continue;
                }
            }
            if (t->str == "{" && t->link) {
                t = t->link->next;
                continue;
            }
            if (t->str == "(" && t->link) {
                setVarIdsInRange(t, t->link, scope);
                t = t->link->next;
                continue;
            }
            t = t->next;
        }
        vstack.pop();
    };

    walk(global, list.front, nullptr);

    // mark locals
    for (Scope& s : db.scopes) {
        for (Variable* v : s.varlist) {
            if (v->isArgument)
                continue;
            if (s.isExecutable())
                v->isLocal = true;
            else if (s.type == Scope::eGlobal || s.type == Scope::eNamespace)
                v->isGlobal = true;
            else if (s.isClassOrStruct())
                v->isMember = true;
        }
    }
    // link function calls by name
    std::map<std::string, Function*> byName;
    for (Function* f : db.functionList)
        if (!byName.count(f->name) || f->hasBody)
            byName[f->name] = f;
    for (Token* t = list.front; t; t = t->next) {
        if (t->isName() && !t->func && t->varId == 0 && t->next && t->next->str == "(") {
            auto it = byName.find(t->str);
            if (it != byName.end())
                t->func = it->second;
        }
    }
}
EOF
