#include "symbols.h"
#include <set>
#include <string>
#include <cstring>

Token* findClosingBracket(Token* tok)
{
    if (!tok || tok->str != "<")
        return nullptr;
    int depth = 0;
    for (Token* t = tok; t; t = t->next) {
        if (t->str == "(" || t->str == "[" || t->str == "{") {
            t = t->link;
            if (!t) return nullptr;
            continue;
        }
        if (t->str == ";" || t->str == "&&" || t->str == "||" || t->str == "}" || t->str == ")" || t->str == "]")
            return nullptr;
        if (t->str == "<")
            depth++;
        else if (t->str == ">") {
            if (--depth == 0)
                return t;
        } else if (t->str == ">>") {
            depth -= 2;
            if (depth <= 0)
                return t;
        }
    }
    return nullptr;
}

namespace {

static const std::set<std::string> kTypeWords = {
    "void", "char", "short", "int", "long", "float", "double", "signed", "unsigned", "bool", "_Bool", "wchar_t",
    "size_t", "ssize_t", "ptrdiff_t", "intptr_t", "uintptr_t", "int8_t", "int16_t", "int32_t", "int64_t",
    "uint8_t", "uint16_t", "uint32_t", "uint64_t", "const", "volatile", "struct", "union", "enum", "FILE", "char16_t", "char32_t"
};

class AstBuilder {
public:
    bool cpp;
    std::set<std::string> userTypes;
    Token* cur = nullptr;
    Token* end = nullptr;   // exclusive end

    bool atEnd() const { return !cur || cur == end; }

    static void setOps(Token* op, Token* a, Token* b) {
        op->astOp1 = a;
        op->astOp2 = b;
        if (a) a->astParent = op;
        if (b) b->astParent = op;
    }

    bool isTypeTok(const Token* t) const {
        return t && (kTypeWords.count(t->str) || (t->isName() && userTypes.count(t->str) && t->varId == 0));
    }

    // is '(' at t a cast?
    bool isCast(Token* t) const {
        if (!t || t->str != "(" || !t->link)
            return false;
        Token* x = t->next;
        if (!isTypeTok(x))
            return false;
        bool sawType = false;
        while (x && x != t->link) {
            if (isTypeTok(x) || (x->isName() && x->varId == 0 && x->prev && (x->prev->str == "struct" || x->prev->str == "union" || x->prev->str == "enum")))
                sawType = true;
            else if (x->str == "*" || x->str == "&" || x->str == "::" || (x->isName() && x->varId == 0 && x->next && x->next->str == "::"))
                ;
            else if (x->str == "<") {
                Token* c = findClosingBracket(x);
                if (!c) return false;
                x = c;
            } else
                return false;
            x = x->next;
        }
        if (!sawType)
            return false;
        Token* after = t->link->next;
        if (!after)
            return false;
        if (after->isName() || after->isNumber() || after->isString() || after->isChar() || after->str == "(" ||
            after->str == "!" || after->str == "~" || after->str == "-" || after->str == "+" || after->str == "*" || after->str == "&" ||
            after->str == "++" || after->str == "--" || after->str == "{")
            return true;
        return false;
    }

    Token* parseExpr() { return parseComma(); }

    Token* parseComma() {
        Token* lhs = parseAssign();
        while (!atEnd() && cur->str == ",") {
            Token* op = cur;
            cur = cur->next;
            Token* rhs = parseAssign();
            setOps(op, lhs, rhs);
            lhs = op;
        }
        return lhs;
    }

    Token* parseAssign() {
        Token* lhs = parseTernary();
        if (!atEnd() && cur->isAssignmentOp()) {
            Token* op = cur;
            cur = cur->next;
            Token* rhs = parseAssign();
            setOps(op, lhs, rhs);
            return op;
        }
        return lhs;
    }

    Token* parseTernary() {
        Token* cond = parseBinary(0);
        if (!atEnd() && cur->str == "?") {
            Token* q = cur;
            cur = cur->next;
            Token* a = parseAssign();
            if (!atEnd() && cur->str == ":") {
                Token* colon = cur;
                cur = cur->next;
                Token* b = parseAssign();
                setOps(colon, a, b);
                setOps(q, cond, colon);
            } else {
                setOps(q, cond, a);
            }
            return q;
        }
        return cond;
    }

    static int binPrec(const std::string& s) {
        if (s == "||") return 1;
        if (s == "&&") return 2;
        if (s == "|") return 3;
        if (s == "^") return 4;
        if (s == "&") return 5;
        if (s == "==" || s == "!=") return 6;
        if (s == "<" || s == ">" || s == "<=" || s == ">=" || s == "<=>") return 7;
        if (s == "<<" || s == ">>") return 8;
        if (s == "+" || s == "-") return 9;
        if (s == "*" || s == "/" || s == "%") return 10;
        return -1;
    }

    Token* parseBinary(int minPrec) {
        Token* lhs = parseUnary();
        for (;;) {
            if (atEnd())
                break;
            const int p = binPrec(cur->str);
            if (p < 0 || p < minPrec)
                break;
            Token* op = cur;
            cur = cur->next;
            Token* rhs = parseBinary(p + 1);
            setOps(op, lhs, rhs);
            lhs = op;
        }
        return lhs;
    }

    Token* parseUnary() {
        if (atEnd())
            return nullptr;
        Token* t = cur;
        if (t->str == "!" || t->str == "~" || t->str == "-" || t->str == "+" || t->str == "*" || t->str == "&" || t->str == "++" || t->str == "--") {
            cur = cur->next;
            Token* operand = parseUnary();
            setOps(t, operand, nullptr);
            t->isUnaryOp = true;
            return t;
        }
        if (t->str == "sizeof" || t->str == "alignof" || t->str == "_Alignof") {
            cur = cur->next;
            if (!atEnd() && cur->str == "(" && cur->link) {
                Token* open = cur;
                Token* save = cur->link->next;
                // parse inside as expression if possible
                if (!isTypeTok(open->next)) {
                    Token* saveEnd = end;
                    cur = open->next;
                    end = open->link;
                    Token* inner = parseExpr();
                    end = saveEnd;
                    setOps(open, inner, nullptr);
                } else {
                    open->astOp1 = nullptr;
                }
                cur = save;
                setOps(t, open, nullptr);
                t->isUnaryOp = true;
                return parsePostfixOps(t);
            }
            Token* operand = parseUnary();
            setOps(t, operand, nullptr);
            t->isUnaryOp = true;
            return t;
        }
        if (cpp && (t->str == "new")) {
            cur = cur->next;
            // new T [n] / new T (args)
            Token* typeTok = cur;
            while (!atEnd() && (cur->isName() || cur->str == "::" || cur->str == "*")) {
                if (cur->next && cur->next->str == "<") {
                    Token* c = findClosingBracket(cur->next);
                    if (c) { cur = c->next; continue; }
                }
                cur = cur->next;
            }
            Token* arg = nullptr;
            if (!atEnd() && (cur->str == "[" || cur->str == "(" || cur->str == "{")) {
                Token* open = cur;
                Token* saveEnd = end;
                cur = open->next;
                end = open->link;
                arg = parseExpr();
                end = saveEnd;
                cur = open->link->next;
                setOps(open, typeTok, arg);
                setOps(t, open, nullptr);
            } else
                setOps(t, typeTok, nullptr);
            t->isUnaryOp = true;
            return t;
        }
        if (cpp && t->str == "delete") {
            cur = cur->next;
            if (!atEnd() && cur->str == "[" && cur->next && cur->next->str == "]")
                cur = cur->next->next;
            Token* operand = parseUnary();
            setOps(t, operand, nullptr);
            t->isUnaryOp = true;
            return t;
        }
        if (t->str == "throw") {
            cur = cur->next;
            Token* operand = atEnd() || cur->str == ";" ? nullptr : parseAssign();
            setOps(t, operand, nullptr);
            return t;
        }
        if (t->str == "(" && isCast(t)) {
            cur = t->link->next;
            Token* operand = parseUnary();
            setOps(t, operand, nullptr);
            t->isCast = true;
            return t;
        }
        return parsePostfix();
    }

    Token* parsePrimary() {
        if (atEnd())
            return nullptr;
        Token* t = cur;
        if (t->str == "(" && t->link) {
            Token* saveEnd = end;
            cur = t->next;
            end = t->link;
            Token* inner = (cur == end) ? nullptr : parseExpr();
            end = saveEnd;
            cur = t->link->next;
            // parenthesized expression: return inner directly (cppcheck drops parens)
            return inner ? inner : t;
        }
        if (t->str == "{" && t->link) {
            Token* saveEnd = end;
            cur = t->next;
            end = t->link;
            Token* inner = (cur == end) ? nullptr : parseExpr();
            end = saveEnd;
            cur = t->link->next;
            setOps(t, inner, nullptr);
            return t;
        }
        if (cpp && t->str == "[" && t->link) {
            // lambda
            Token* x = t->link->next;
            if (x && x->str == "(" && x->link)
                x = x->link->next;
            while (x && x->str != "{" && x != end)
                x = x->next;
            if (x && x->str == "{" && x->link) {
                cur = x->link->next;
                return t;
            }
            cur = t->link->next;
            return t;
        }
        if (cpp && (t->str == "static_cast" || t->str == "dynamic_cast" || t->str == "reinterpret_cast" || t->str == "const_cast") && t->next && t->next->str == "<") {
            Token* c = findClosingBracket(t->next);
            if (c && c->next && c->next->str == "(") {
                Token* open = c->next;
                Token* saveEnd = end;
                cur = open->next;
                end = open->link;
                Token* inner = parseExpr();
                end = saveEnd;
                cur = open->link->next;
                setOps(open, t, inner);
                open->isCast = true;
                return open;
            }
        }
        // names, literals
        cur = cur->next;
        // qualified names: a::b
        while (!atEnd() && cur->str == "::" && cur->next && cur->next->isName()) {
            Token* op = cur;
            Token* rhs = cur->next;
            cur = rhs->next;
            setOps(op, t, rhs);
            t = op;
        }
        // template args in expression: f<int>(...)
        if (cpp && !atEnd() && cur->str == "<" && t->isName() && t->varId == 0) {
            Token* c = findClosingBracket(cur);
            if (c && c->next && (c->next->str == "(" || c->next->str == "{" || c->next->str == "::")) {
                cur = c->next;
            }
        }
        return t;
    }

    Token* parsePostfixOps(Token* lhs) {
        for (;;) {
            if (atEnd())
                break;
            Token* t = cur;
            if (t->str == "(" && t->link) {
                Token* saveEnd = end;
                cur = t->next;
                end = t->link;
                Token* args = (cur == end) ? nullptr : parseExpr();
                end = saveEnd;
                cur = t->link->next;
                setOps(t, lhs, args);
                lhs = t;
                continue;
            }
            if (t->str == "[" && t->link) {
                Token* saveEnd = end;
                cur = t->next;
                end = t->link;
                Token* idx = (cur == end) ? nullptr : parseExpr();
                end = saveEnd;
                cur = t->link->next;
                setOps(t, lhs, idx);
                lhs = t;
                continue;
            }
            if ((t->str == "." || t->str == "->") && t->next) {
                Token* member = t->next;
                cur = member->next;
                setOps(t, lhs, member);
                lhs = t;
                continue;
            }
            if (t->str == "++" || t->str == "--") {
                cur = cur->next;
                setOps(t, lhs, nullptr);
                lhs = t;
                continue;
            }
            if (cpp && t->str == "{" && lhs && lhs->isName() && t->link) {
                // T{...}
                Token* saveEnd = end;
                cur = t->next;
                end = t->link;
                Token* args = (cur == end) ? nullptr : parseExpr();
                end = saveEnd;
                cur = t->link->next;
                setOps(t, lhs, args);
                lhs = t;
                continue;
            }
            break;
        }
        return lhs;
    }

    Token* parsePostfix() {
        Token* lhs = parsePrimary();
        return parsePostfixOps(lhs);
    }
};

}

static Token* parseRange(AstBuilder& b, Token* start, Token* end)
{
    if (!start || start == end)
        return nullptr;
    b.cur = start;
    b.end = end;
    Token* root = b.parseExpr();
    // guard: if parser didn't consume everything, try to continue parsing separate expressions
    int guard = 0;
    while (b.cur && b.cur != end && guard++ < 1000) {
        Token* before = b.cur;
        b.parseExpr();
        if (b.cur == before)
            b.cur = b.cur->next;
    }
    return root;
}

static Token* findStatementEnd(Token* t)
{
    for (; t; t = t->next) {
        if (t->str == "(" || t->str == "[")
            t = t->link;
        else if (t->str == "{") {
            // initializer list or lambda body inside expression
            t = t->link;
        } else if (t->str == ";" || t->str == "}")
            return t;
        if (!t)
            return nullptr;
    }
    return nullptr;
}

void Tokenizer::createAst()
{
    AstBuilder b;
    b.cpp = cpp;
    for (Token* t = list.front; t; t = t->next) {
        if ((t->str == "struct" || t->str == "class" || t->str == "union" || t->str == "enum") && t->next && t->next->isName())
            b.userTypes.insert(t->next->str);
        if (t->str == "typedef") {
            Token* last = nullptr;
            for (Token* x = t->next; x && x->str != ";"; x = x->next) {
                if (x->str == "{" || x->str == "(" || x->str == "[") {
                    if (x->str == "(" && x->next && x->next->str == "*" && x->next->next && x->next->next->isName())
                        last = x->next->next;
                    x = x->link;
                    if (!x) break;
                    continue;
                }
                if (x->isName())
                    last = x;
            }
            if (last)
                b.userTypes.insert(last->str);
        }
    }

    // declarations: build '=' for initializers
    for (Variable& v : db.variables) {
        if (!v.hasInit || !v.initTok || v.isArgument)
            continue;
        Token* eq = v.initTok->prev;
        if (!eq)
            continue;
        if (eq->str == "=") {
            Token* end = v.declEnd;
            Token* rhs = parseRange(b, v.initTok, end);
            AstBuilder::setOps(eq, v.nameTok, rhs);
        } else if (v.initTok->str == "(" || v.initTok->str == "{") {
            Token* open = v.initTok;
            Token* inner = parseRange(b, open->next, open->link);
            AstBuilder::setOps(open, v.nameTok, inner);
        }
    }

    // statements in function bodies
    for (Scope* fs : db.functionScopes) {
        (void)fs;
    }
    for (Scope& sc : db.scopes) {
        if (!sc.isExecutable() || !sc.bodyStart)
            continue;
        Token* t = sc.bodyStart->next;
        Token* end = sc.bodyEnd;
        while (t && t != end) {
            if (t->scope != &sc && t->str == "{" && t->link) {
                t = t->link->next;
                continue;
            }
            if (t->str == "{" && t->link) {
                // nested scope handled separately
                t = t->link->next;
                continue;
            }
            if (t->str == ";" || t->str == "}") {
                t = t->next;
                continue;
            }
            if ((t->str == "if" || t->str == "while" || t->str == "switch") && t->next && t->next->str == "(") {
                Token* open = t->next;
                Token* root = parseRange(b, open->next, open->link);
                AstBuilder::setOps(open, root, nullptr);
                open->astOp1 = root;
                if (root) root->astParent = open;
                t = open->link->next;
                continue;
            }
            if (t->str == "for" && t->next && t->next->str == "(") {
                Token* open = t->next;
                Token* close = open->link;
                Token* s1 = nullptr;
                Token* s2 = nullptr;
                int depth = 0;
                for (Token* x = open->next; x != close; x = x->next) {
                    if (x->str == "(" || x->str == "[" || x->str == "{") { x = x->link; continue; }
                    if (x->str == ";" && depth == 0) {
                        if (!s1) s1 = x; else if (!s2) s2 = x;
                    }
                }
                if (s1 && s2) {
                    // init: declarations were handled; parse non-decl init expression
                    bool isDecl = false;
                    for (Token* x = open->next; x != s1; x = x->next)
                        if (x->var && x->var->nameTok == x)
                            isDecl = true;
                    if (!isDecl)
                        parseRange(b, open->next, s1);
                    Token* cond = parseRange(b, s1->next, s2);
                    Token* inc = parseRange(b, s2->next, close);
                    s1->astOp1 = cond;
                    if (cond) cond->astParent = s1;
                    s2->astOp1 = inc;
                    if (inc) inc->astParent = s2;
                } else if (cpp) {
                    // range for
                    Token* colon = nullptr;
                    for (Token* x = open->next; x != close; x = x->next) {
                        if (x->str == "(" || x->str == "[" || x->str == "{") { x = x->link; continue; }
                        if (x->str == ":") { colon = x; break; }
                    }
                    if (colon)
                        parseRange(b, colon->next, close);
                }
                t = close->next;
                continue;
            }
            if (t->str == "else" || t->str == "do" || t->str == "try") {
                t = t->next;
                continue;
            }
            if (t->str == "catch" && t->next && t->next->str == "(") {
                t = t->next->link->next;
                continue;
            }
            if ((t->str == "case") ) {
                Token* x = t->next;
                while (x && x != end && x->str != ":") x = x->next;
                Token* root = parseRange(b, t->next, x);
                AstBuilder::setOps(t, root, nullptr);
                t = x ? x->next : x;
                continue;
            }
            if (t->str == "default" && t->next && t->next->str == ":") {
                t = t->next->next;
                continue;
            }
            if (t->isName() && t->next && t->next->str == ":" && !t->isKeyword() && t->varId == 0) {
                t = t->next->next;
                continue;
            }
            if (t->str == "return") {
                Token* se = findStatementEnd(t);
                Token* root = parseRange(b, t->next, se);
                AstBuilder::setOps(t, root, nullptr);
                t = se;
                continue;
            }
            if (t->str == "break" || t->str == "continue" || t->str == "goto") {
                Token* se = findStatementEnd(t);
                t = se;
                continue;
            }
            Token* se = findStatementEnd(t);
            // declaration statement?
            bool isDecl = false;
            for (Token* x = t; x && x != se; x = x->next) {
                if (x->var && x->var->nameTok == x && !x->var->isArgument) {
                    isDecl = true;
                    break;
                }
                if (x->str == "=" || x->str == "(")
                    break;
            }
            if (!isDecl)
                parseRange(b, t, se);
            t = se;
        }
    }
}
