std::string exprString(const Token* tok)
{
    if (!tok)
        return "";
    // collect subtree tokens
    std::vector<const Token*> stack{tok};
    const Token* minTok = tok;
    const Token* maxTok = tok;
    while (!stack.empty()) {
        const Token* t = stack.back();
        stack.pop_back();
        if (t->index < minTok->index) minTok = t;
        if (t->index > maxTok->index) maxTok = t;
        if ((t->str == "(" || t->str == "[" || t->str == "{") && t->link && !t->isCast && t->astOp1 && t->link->index > maxTok->index)
            maxTok = t->link;
        if (t->str == "(" && t->isCast && t->link && t->link->index > maxTok->index && t->astOp1 == nullptr)
            maxTok = t->link;
        if (t->astOp1) stack.push_back(t->astOp1);
        if (t->astOp2) stack.push_back(t->astOp2);
    }
    // extend for parentheses that enclose subexpressions: include matching parens inside range
    std::string ret;
    const Token* prev = nullptr;
    int depth = 0;
    for (const Token* t = minTok; t; t = t->next) {
        if (prev && (prev->isName() || prev->isNumber()) && (t->isName() || t->isNumber()))
            ret += ' ';
        ret += t->str;
        if (t->str == "(" || t->str == "[") depth++;
        if (t->str == ")" || t->str == "]") depth--;
        prev = t;
        if (t == maxTok)
            break;
    }
    // close unbalanced
    const Token* t = maxTok ? maxTok->next : nullptr;
    while (depth > 0 && t) {
        if (t->str == ")" || t->str == "]") {
            ret += t->str;
            depth--;
        } else
            break;
        t = t->next;
    }
    // strip unbalanced leading '('
    while (depth < 0 && !ret.empty() && (ret.back() == ')' || ret.back() == ']')) {
        ret.pop_back();
        depth++;
    }
    return ret;
}

namespace {

struct VarState {
    enum K { UNKNOWN, KNOWN, UNINIT } kind = UNKNOWN;
    long long value = 0;
    std::vector<std::pair<const Token*, std::string>> path;
};

typedef std::map<int, VarState> State;

static bool parseInt(const std::string& s, long long& out)
{
    std::string n = s;
    while (!n.empty() && (n.back() == 'u' || n.back() == 'U' || n.back() == 'l' || n.back() == 'L'))
        n.pop_back();
    if (n.empty() || !std::isdigit((unsigned char)n[0]))
        return false;
    char* end = nullptr;
    errno = 0;
    unsigned long long v;
    if (n.size() > 2 && n[0] == '0' && (n[1] == 'x' || n[1] == 'X'))
        v = std::strtoull(n.c_str() + 2, &end, 16);
    else if (n.size() > 2 && n[0] == '0' && (n[1] == 'b' || n[1] == 'B'))
        v = std::strtoull(n.c_str() + 2, &end, 2);
    else if (n.size() > 1 && n[0] == '0')
        v = std::strtoull(n.c_str(), &end, 8);
    else
        v = std::strtoull(n.c_str(), &end, 10);
    if (*end)
        return false;
    out = (long long)v;
    return true;
}

static bool charValue(const std::string& s, long long& out)
{
    if (s.size() < 3 || s[0] != '\'')
        return false;
    if (s[1] == '\\') {
        switch (s[2]) {
        case 'n': out = '\n'; return true;
        case 't': out = '\t'; return true;
        case 'r': out = '\r'; return true;
        case '0': out = 0; return true;
        case '\\': out = '\\'; return true;
        case '\'': out = '\''; return true;
        case '"': out = '"'; return true;
        default: return false;
        }
    }
    if (s.size() == 3) {
        out = (unsigned char)s[1];
        if (out >= 128) out -= 256;
        return true;
    }
    return false;
}

class ValueFlow {
public:
    Tokenizer& tz;
    const Settings& settings;
    explicit ValueFlow(Tokenizer& t, const Settings& s) : tz(t), settings(s) {}

    static void setKnown(Token* tok, long long v, const std::vector<std::pair<const Token*, std::string>>& path = {}) {
        for (const Value& val : tok->values)
            if (val.kind == Value::INT && val.known && val.intvalue == v)
                return;
        Value val;
        val.kind = Value::INT;
        val.intvalue = v;
        val.known = true;
        val.errorPath = path;
        tok->values.push_back(val);
    }
    static void setUninit(Token* tok) {
        for (const Value& val : tok->values)
            if (val.kind == Value::UNINIT)
                return;
        Value val;
        val.kind = Value::UNINIT;
        tok->values.push_back(val);
    }

    // is the variable token used as an lvalue (written) at this position
    static bool isWriteTarget(const Token* tok) {
        const Token* p = tok->astParent;
        if (!p)
            return false;
        if (p->isAssignmentOp() && p->astOp1 == tok)
            return true;
        return false;
    }

    bool isAddressOf(const Token* tok) const {
        const Token* p = tok->astParent;
        return p && p->str == "&" && p->isUnaryOp && p->astOp1 == tok;
    }

    bool inSizeof(const Token* tok) const {
        for (const Token* p = tok->astParent; p; p = p->astParent)
            if (p->str == "sizeof")
                return true;
        return false;
    }

    // evaluate expression; returns true if known
    bool evaluate(Token* tok, State& st, long long& out) {
        if (!tok)
            return false;
        long long v;
        if (tok->isNumber()) {
            if (parseInt(tok->str, v)) {
                setKnown(tok, v);
                out = v;
                return true;
            }
            return false;
        }
        if (tok->isChar() && charValue(tok->str, v)) {
            setKnown(tok, v);
            out = v;
            return true;
        }
        if (tok->str == "NULL" || tok->str == "nullptr" || tok->str == "false") {
            setKnown(tok, 0);
            out = 0;
            return true;
        }
        if (tok->str == "true") {
            setKnown(tok, 1);
            out = 1;
            return true;
        }
        if (tok->varId > 0) {
            auto it = st.find(tok->varId);
            if (it != st.end() && it->second.kind == VarState::KNOWN) {
                setKnown(tok, it->second.value, it->second.path);
                out = it->second.value;
                return true;
            }
            return false;
        }
        if (tok->isCast) {
            if (evaluate(tok->astOp1, st, out)) {
                setKnown(tok, out);
                return true;
            }
            return false;
        }
        if (tok->isUnaryOp && tok->astOp1 && !tok->astOp2) {
            long long a;
            if (tok->str == "-" && evaluate(tok->astOp1, st, a)) { out = -a; setKnown(tok, out); return true; }
            if (tok->str == "+" && evaluate(tok->astOp1, st, a)) { out = a; setKnown(tok, out); return true; }
            if (tok->str == "!" && evaluate(tok->astOp1, st, a)) { out = !a; setKnown(tok, out); return true; }
            if (tok->str == "~" && evaluate(tok->astOp1, st, a)) { out = ~a; setKnown(tok, out); return true; }
            return false;
        }
        if (tok->astOp1 && tok->astOp2 && tok->str != "=" && !tok->isAssignmentOp()) {
            const std::string& op = tok->str;
            if (op == "(" || op == "[" || op == "." || op == "->" || op == "," || op == "?" || op == "::")
                return false;
            long long a, b;
            // x - x
            if (op == "-" && tok->astOp1->varId && tok->astOp1->varId == tok->astOp2->varId && !tok->astOp1->astOp1) {
                out = 0;
                setKnown(tok, 0);
                return true;
            }
            const bool ka = evaluate(tok->astOp1, st, a);
            const bool kb = evaluate(tok->astOp2, st, b);
            if (op == "&&" && ka && !a) { out = 0; setKnown(tok, 0); return true; }
            if (op == "||" && ka && a) { out = 1; setKnown(tok, 1); return true; }
            if (!ka || !kb)
                return false;
            if (op == "+") out = a + b;
            else if (op == "-") out = a - b;
            else if (op == "*") out = a * b;
            else if (op == "/") { if (b == 0) return false; out = a / b; }
            else if (op == "%") { if (b == 0) return false; out = a % b; }
            else if (op == "<<") { if (b < 0 || b >= 64) return false; out = a << b; }
            else if (op == ">>") { if (b < 0 || b >= 64) return false; out = a >> b; }
            else if (op == "&") out = a & b;
            else if (op == "|") out = a | b;
            else if (op == "^") out = a ^ b;
            else if (op == "&&") out = a && b;
            else if (op == "||") out = a || b;
            else if (op == "==") out = a == b;
            else if (op == "!=") out = a != b;
            else if (op == "<") out = a < b;
            else if (op == ">") out = a > b;
            else if (op == "<=") out = a <= b;
            else if (op == ">=") out = a >= b;
            else return false;
            setKnown(tok, out);
            return true;
        }
        return false;
    }

    // collect varIds written in token range
    static void collectWrites(const Token* start, const Token* end, std::set<int>& out) {
        for (const Token* t = start; t && t != end; t = t->next) {
            if (t->varId == 0)
                continue;
            const Token* p = t->astParent;
            if (p && ((p->isAssignmentOp() && p->astOp1 == t) || p->isIncDec() || (p->str == "&" && p->isUnaryOp)))
                out.insert(t->varId);
            // declarations inside
            if (t->var && t->var->nameTok == t)
                out.insert(t->varId);
            // passed to function (could be modified via reference in C++)
            if (p && (p->str == "(" || p->str == ",") && !p->isCast)
                out.insert(t->varId);
            if (p && (p->str == "[" ) && p->astOp1 == t)
                out.insert(t->varId);
            if (p && (p->str == "." || p->str == "->") && p->astOp1 == t)
                out.insert(t->varId);
        }
    }

    static bool isNoReturnCall(const Token* t) {
        return t && t->isName() && (t->str == "exit" || t->str == "abort" || t->str == "_Exit" || t->str == "quick_exit") && t->next && t->next->str == "(";
    }

    // returns true if block always exits (return/break/continue/throw/goto)
    static bool blockExits(const Token* open) {
        if (!open || open->str != "{" || !open->link)
            return false;
        const Token* close = open->link;
        // last statement
        const Token* last = close->prev;
        if (!last)
            return false;
        if (last->str == ";") {
            // find start of last statement
            const Token* t = last->prev;
            while (t && t != open && t->str != ";" && t->str != "{" && t->str != "}") {
                if (t->str == ")" || t->str == "]")
                    t = t->link;
                t = t->prev;
            }
            const Token* s = t ? t->next : nullptr;
            if (s && (s->str == "return" || s->str == "break" || s->str == "continue" || s->str == "throw" || s->str == "goto"))
                return true;
            if (isNoReturnCall(s))
                return true;
        }
        if (last->str == "}" && last->link) {
            // if/else both exit
            const Token* lo = last->link;
            if (lo->prev && lo->prev->str == "else") {
                const Token* ifClose = lo->prev->prev;
                if (ifClose && ifClose->str == "}" && blockExits(ifClose->link) && blockExits(lo))
                    return true;
            }
            if (lo->prev && lo->prev->str == ")" ) {
                // nothing
            }
            if (lo->scope && lo->scope->type == Scope::eUnconditional)
                return blockExits(lo);
        }
        return false;
    }

    void processExpression(Token* root, State& st) {
        if (!root)
            return;
        // post-order evaluation with side effects in order
        if (root->isAssignmentOp()) {
            Token* lhs = root->astOp1;
            Token* rhs = root->astOp2;
            processExpression(rhs, st);
            if (lhs && lhs->varId == 0)
                processExpression(lhs, st);
            else if (lhs && lhs->varId && root->str != "=") {
                // compound: read
                markRead(lhs, st);
            }
            if (lhs && lhs->varId) {
                VarState vs;
                long long v;
                if (root->str == "=") {
                    if (evaluate(rhs, st, v)) {
                        vs.kind = VarState::KNOWN;
                        vs.value = v;
                        vs.path.push_back({rhs, "Assignment '" + exprString(root) + "', assigned value is " + std::to_string(v)});
                    }
                } else {
                    auto it = st.find(lhs->varId);
                    long long r;
                    if (it != st.end() && it->second.kind == VarState::KNOWN && evaluate(rhs, st, r)) {
                        long long a = it->second.value;
                        bool ok = true;
                        const std::string op = root->str.substr(0, root->str.size() - 1);
                        if (op == "+") v = a + r;
                        else if (op == "-") v = a - r;
                        else if (op == "*") v = a * r;
                        else if (op == "/" && r) v = a / r;
                        else if (op == "%" && r) v = a % r;
                        else if (op == "&") v = a & r;
                        else if (op == "|") v = a | r;
                        else if (op == "^") v = a ^ r;
                        else if (op == "<<" && r >= 0 && r < 64) v = a << r;
                        else if (op == ">>" && r >= 0 && r < 64) v = a >> r;
                        else ok = false;
                        if (ok) {
                            vs.kind = VarState::KNOWN;
                            vs.value = v;
                            vs.path = it->second.path;
                            vs.path.push_back({root, "Compound assignment '" + root->str + "', assigned value is " + std::to_string(v)});
                        }
                    }
                }
                if (lhs->var && (lhs->var->isArray || lhs->var->isClassType))
                    vs.kind = VarState::UNKNOWN;
                st[lhs->varId] = vs;
            }
            return;
        }
        if (root->isIncDec() && root->astOp1 && root->astOp1->varId) {
            Token* v = root->astOp1;
            markRead(v, st);
            auto it = st.find(v->varId);
            if (it != st.end() && it->second.kind == VarState::KNOWN) {
                it->second.value += (root->str == "++") ? 1 : -1;
                it->second.path.push_back({root, std::string(root->str == "++" ? "Assignment" : "Assignment") + " '" + exprString(root) + "', assigned value is " + std::to_string(it->second.value)});
                it->second.kind = VarState::UNKNOWN;
            } else
                st[v->varId] = VarState();
            return;
        }
        if (root->str == "&" && root->isUnaryOp && root->astOp1) {
            // address taken -> unknown
            Token* t = root->astOp1;
            while (t && (t->str == "." || t->str == "[" ) && t->astOp1)
                t = t->astOp1;
            if (t && t->varId) {
                st[t->varId] = VarState();
                return;
            }
            processExpression(root->astOp1, st);
            return;
        }
        if (root->str == "sizeof")
            return;
        if (root->str == "?" && root->astOp1 && root->astOp2) {
            processExpression(root->astOp1, st);
            long long c;
            if (evaluate(root->astOp1, st, c) && root->astOp2->str == ":") {
                processExpression(c ? root->astOp2->astOp1 : root->astOp2->astOp2, st);
            } else {
                State a = st, b = st;
                if (root->astOp2->str == ":") {
                    processExpression(root->astOp2->astOp1, a);
                    processExpression(root->astOp2->astOp2, b);
                }
                st = merge(a, b);
            }
            return;
        }
        if (root->str == "&&" || root->str == "||") {
            processExpression(root->astOp1, st);
            State b = st;
            processExpression(root->astOp2, b);
            st = merge(st, b);
            evaluate(root, st, *(new long long));
            return;
        }
        if (root->str == "(" && !root->isCast && root->astOp1) {
            // function call
            processExpression(root->astOp1, st);
            // args
            std::vector<Token*> args;
            std::function<void(Token*)> collect = [&](Token* a) {
                if (!a) return;
                if (a->str == ",") { collect(a->astOp1); collect(a->astOp2); return; }
                args.push_back(a);
            };
            collect(root->astOp2);
            for (Token* a : args)
                processExpression(a, st);
            for (Token* a : args) {
                if (a->varId && a->var && (a->var->isArray || a->var->isPointer()))
                    ; // pointee may change, pointer value unchanged
                if (a->varId && tz.cpp && a->var && !a->var->isPointer() && !a->var->isArray) {
                    // may be passed by reference
                    const Function* f = root->astOp1->func;
                    bool byRef = !f;
                    if (f && a->var) {
                        // find arg index
                        int idx = 0;
                        for (Token* x : args) { if (x == a) break; ++idx; }
                        if (idx < (int)f->args.size() && f->args[idx] && f->args[idx]->isReference && !f->args[idx]->isConst)
                            byRef = true;
                        else if (idx >= (int)f->args.size())
                            byRef = false;
                    }
                    if (byRef)
                        st[a->varId] = VarState();
                }
            }
            // globals unknown after call
            for (auto& kv : st) {
                const Variable* v = tz.db.getVariable(kv.first);
                if (v && (v->isGlobal || v->isStatic) && kv.second.kind == VarState::KNOWN)
                    kv.second = VarState();
            }
            evaluate(root, st, *(new long long));
            return;
        }
        if (root->varId) {
            markRead(root, st);
            return;
        }
        processExpression(root->astOp1, st);
        processExpression(root->astOp2, st);
        long long dummy;
        evaluate(root, st, dummy);
    }

    void markRead(Token* tok, State& st) {
        auto it = st.find(tok->varId);
        if (it == st.end())
            return;
        if (it->second.kind == VarState::KNOWN)
            setKnown(tok, it->second.value, it->second.path);
        else if (it->second.kind == VarState::UNINIT) {
            if (!isAddressOf(tok) && !inSizeof(tok))
                setUninit(tok);
        }
    }

    static State merge(const State& a, const State& b) {
        State r;
        std::set<int> keys;
        for (const auto& kv : a) keys.insert(kv.first);
        for (const auto& kv : b) keys.insert(kv.first);
        for (int k : keys) {
            auto ia = a.find(k);
            auto ib = b.find(k);
            if (ia == a.end() || ib == b.end())
                continue;
            if (ia->second.kind == VarState::KNOWN && ib->second.kind == VarState::KNOWN && ia->second.value == ib->second.value)
                r[k] = ia->second;
            else if (ia->second.kind == VarState::UNINIT && ib->second.kind == VarState::UNINIT)
                r[k] = ia->second;
            else
                r[k] = VarState();
        }
        return r;
    }

    // walk statements between start and end (exclusive)
    void walk(Token* start, Token* end, State& st) {
        Token* t = start;
        while (t && t != end) {
            if (t->str == ";" || t->str == "}") {
                t = t->next;
                continue;
            }
            if (t->str == "{" && t->link) {
                walk(t->next, t->link, st);
                t = t->link->next;
                continue;
            }
            if (t->str == "if" && t->next && t->next->str == "(") {
                Token* open = t->next;
                processExpression(open->astOp1, st);
                long long c;
                const bool known = evaluate(open->astOp1, st, c);
                Token* body = open->link->next;
                if (!body || body->str != "{") {
                    t = open->link->next;
                    continue;
                }
                Token* after = body->link->next;
                Token* elseBody = nullptr;
                if (after && after->str == "else" && after->next && after->next->str == "{")
                    elseBody = after->next;
