std::string exprString(const Token* tok)
{
    if (!tok)
        return "";
    // collect subtree tokens
    std::vector<const Token*> stack{tok};
    const Token* minTok = tok;
    const Token* maxTok = tok;
    while (!stack.empty()) {
        const Token* t = stack.back();
        stack.pop_back();
        if (t->index < minTok->index) minTok = t;
        if (t->index > maxTok->index) maxTok = t;
        if ((t->str == "(" || t->str == "[" || t->str == "{") && t->link && !t->isCast && t->astOp1 && t->link->index > maxTok->index)
            maxTok = t->link;
        if (t->str == "(" && t->isCast && t->link && t->link->index > maxTok->index && t->astOp1 == nullptr)
            maxTok = t->link;
        if (t->astOp1) stack.push_back(t->astOp1);
        if (t->astOp2) stack.push_back(t->astOp2);
    }
    // extend for parentheses that enclose subexpressions: include matching parens inside range
    std::string ret;
    const Token* prev = nullptr;
    int depth = 0;
    for (const Token* t = minTok; t; t = t->next) {
        if (prev && (prev->isName() || prev->isNumber()) && (t->isName() || t->isNumber()))
            ret += ' ';
        ret += t->str;
        if (t->str == "(" || t->str == "[") depth++;
        if (t->str == ")" || t->str == "]") depth--;
        prev = t;
        if (t == maxTok)
            break;
    }
    // close unbalanced
    const Token* t = maxTok ? maxTok->next : nullptr;
    while (depth > 0 && t) {
        if (t->str == ")" || t->str == "]") {
            ret += t->str;
            depth--;
        } else
            break;
        t = t->next;
    }
    // strip unbalanced leading '('
    while (depth < 0 && !ret.empty() && (ret.back() == ')' || ret.back() == ']')) {
        ret.pop_back();
        depth++;
    }
    return ret;
}

namespace {

struct VarState {
    enum K { UNKNOWN, KNOWN, UNINIT } kind = UNKNOWN;
    long long value = 0;
    std::vector<std::pair<const Token*, std::string>> path;
};

typedef std::map<int, VarState> State;

static bool parseInt(const std::string& s, long long& out)
{
    std::string n = s;
    while (!n.empty() && (n.back() == 'u' || n.back() == 'U' || n.back() == 'l' || n.back() == 'L'))
        n.pop_back();
    if (n.empty() || !std::isdigit((unsigned char)n[0]))
        return false;
    char* end = nullptr;
    errno = 0;
    unsigned long long v;
    if (n.size() > 2 && n[0] == '0' && (n[1] == 'x' || n[1] == 'X'))
        v = std::strtoull(n.c_str() + 2, &end, 16);
    else if (n.size() > 2 && n[0] == '0' && (n[1] == 'b' || n[1] == 'B'))
        v = std::strtoull(n.c_str() + 2, &end, 2);
    else if (n.size() > 1 && n[0] == '0')
        v = std::strtoull(n.c_str(), &end, 8);
    else
        v = std::strtoull(n.c_str(), &end, 10);
    if (*end)
        return false;
    out = (long long)v;
    return true;
}

static bool charValue(const std::string& s, long long& out)
{
    if (s.size() < 3 || s[0] != '\'')
        return false;
    if (s[1] == '\\') {
        switch (s[2]) {
        case 'n': out = '\n'; return true;
        case 't': out = '\t'; return true;
        case 'r': out = '\r'; return true;
        case '0': out = 0; return true;
        case '\\': out = '\\'; return true;
        case '\'': out = '\''; return true;
        case '"': out = '"'; return true;
        default: return false;
        }
    }
    if (s.size() == 3) {
        out = (unsigned char)s[1];
        if (out >= 128) out -= 256;
        return true;
    }
    return false;
}

class ValueFlow {
public:
    Tokenizer& tz;
    const Settings& settings;
    explicit ValueFlow(Tokenizer& t, const Settings& s) : tz(t), settings(s) {}

    static void setKnown(Token* tok, long long v, const std::vector<std::pair<const Token*, std::string>>& path = {}) {
        for (const Value& val : tok->values)
            if (val.kind == Value::INT && val.known && val.intvalue == v)
                return;
        Value val;
        val.kind = Value::INT;
        val.intvalue = v;
        val.known = true;
        val.errorPath = path;
        tok->values.push_back(val);
    }
    static void setUninit(Token* tok) {
        for (const Value& val : tok->values)
            if (val.kind == Value::UNINIT)
                return;
