        val.kind = Value::UNINIT;
        tok->values.push_back(val);
    }

    // is the variable token used as an lvalue (written) at this position
    static bool isWriteTarget(const Token* tok) {
        const Token* p = tok->astParent;
        if (!p)
            return false;
        if (p->isAssignmentOp() && p->astOp1 == tok)
            return true;
        return false;
    }

    bool isAddressOf(const Token* tok) const {
        const Token* p = tok->astParent;
        return p && p->str == "&" && p->isUnaryOp && p->astOp1 == tok;
    }

    bool inSizeof(const Token* tok) const {
        for (const Token* p = tok->astParent; p; p = p->astParent)
            if (p->str == "sizeof")
                return true;
