    }

    // evaluate expression; returns true if known
    bool evaluate(Token* tok, State& st, long long& out) {
        if (!tok)
            return false;
        long long v;
        if (tok->isNumber()) {
            if (parseInt(tok->str, v)) {
                setKnown(tok, v);
                out = v;
                return true;
            }
            return false;
        }
        if (tok->isChar() && charValue(tok->str, v)) {
            setKnown(tok, v);
            out = v;
            return true;
        }
        if (tok->str == "NULL" || tok->str == "nullptr" || tok->str == "false") {
            setKnown(tok, 0);
            out = 0;
            return true;
        }
        if (tok->str == "true") {
            setKnown(tok, 1);
            out = 1;
            return true;
        }
        if (tok->varId > 0) {
            auto it = st.find(tok->varId);
            if (it != st.end() && it->second.kind == VarState::KNOWN) {
