            if (tok->str == "+" && evaluate(tok->astOp1, st, a)) { out = a; setKnown(tok, out); return true; }
            if (tok->str == "!" && evaluate(tok->astOp1, st, a)) { out = !a; setKnown(tok, out); return true; }
            if (tok->str == "~" && evaluate(tok->astOp1, st, a)) { out = ~a; setKnown(tok, out); return true; }
