            else if (op == "*") out = a * b;
            else if (op == "/") { if (b == 0) return false; out = a / b; }
            else if (op == "%") { if (b == 0) return false; out = a % b; }
            else if (op == "<<") { if (b < 0 || b >= 64) return false; out = a << b; }
            else if (op == ">>") { if (b < 0 || b >= 64) return false; out = a >> b; }
            else if (op == "&") out = a & b;
            else if (op == "|") out = a | b;
            else if (op == "^") out = a ^ b;
            else if (op == "&&") out = a && b;
            else if (op == "||") out = a || b;
            else if (op == "==") out = a == b;
            else if (op == "!=") out = a != b;
            else if (op == "<") out = a < b;
            else if (op == ">") out = a > b;
            else if (op == "<=") out = a <= b;
            else if (op == ">=") out = a >= b;
