    void markRead(Token* tok, State& st) {
        auto it = st.find(tok->varId);
        if (it == st.end())
            return;
        if (it->second.kind == VarState::KNOWN)
            setKnown(tok, it->second.value, it->second.path);
        else if (it->second.kind == VarState::UNINIT) {
            if (!isAddressOf(tok) && !inSizeof(tok))
                setUninit(tok);
        }
    }

    static State merge(const State& a, const State& b) {
        State r;
        std::set<int> keys;
        for (const auto& kv : a) keys.insert(kv.first);
        for (const auto& kv : b) keys.insert(kv.first);
        for (int k : keys) {
            auto ia = a.find(k);
            auto ib = b.find(k);
            if (ia == a.end() || ib == b.end())
                continue;
            if (ia->second.kind == VarState::KNOWN && ib->second.kind == VarState::KNOWN && ia->second.value == ib->second.value)
                r[k] = ia->second;
            else if (ia->second.kind == VarState::UNINIT && ib->second.kind == VarState::UNINIT)
                r[k] = ia->second;
            else
                r[k] = VarState();
        }
        return r;
    }

    // walk statements between start and end (exclusive)
    void walk(Token* start, Token* end, State& st) {
        Token* t = start;
        while (t && t != end) {
            if (t->str == ";" || t->str == "}") {
                t = t->next;
                continue;
            }
            if (t->str == "{" && t->link) {
                walk(t->next, t->link, st);
                t = t->link->next;
                continue;
            }
            if (t->str == "if" && t->next && t->next->str == "(") {
                Token* open = t->next;
                processExpression(open->astOp1, st);
                long long c;
                const bool known = evaluate(open->astOp1, st, c);
                Token* body = open->link->next;
                if (!body || body->str != "{") {
                    t = open->link->next;
                    continue;
                }
                Token* after = body->link->next;
                Token* elseBody = nullptr;
                if (after && after->str == "else" && after->next && after->next->str == "{")
                    elseBody = after->next;
                State sa = st, sb = st;
                if (!known || c)
                    walk(body->next, body->link, sa);
                if (elseBody && (!known || !c))
                    walk(elseBody->next, elseBody->link, sb);
                const bool aExit = blockExits(body);
                const bool bExit = elseBody && blockExits(elseBody);
                if (known)
                    st = c ? sa : sb;
                else if (aExit && !bExit)
                    st = sb;
                else if (bExit && !aExit)
                    st = sa;
                else
                    st = merge(sa, sb);
                t = elseBody ? elseBody->link->next : body->link->next;
                continue;
            }
            if ((t->str == "while" || t->str == "for" || t->str == "switch") && t->next && t->next->str == "(") {
                Token* open = t->next;
                Token* body = open->link->next;
                if (t->str == "while" && body && body->str == ";") {
                    // do-while tail
                    processExpression(open->astOp1, st);
                    t = body->next;
                    continue;
                }
                std::set<int> writes;
                collectWrites(open, body && body->str == "{" ? body->link : open->link, writes);
                // for-init executes first
                if (t->str == "for") {
                    // process init
                    Token* s1 = nullptr;
                    for (Token* x = open->next; x != open->link; x = x->next) {
                        if (x->str == "(" || x->str == "[" || x->str == "{") { x = x->link; continue; }
                        if (x->str == ";") { s1 = x; break; }
                    }
                    if (s1) {
                        for (Token* x = open->next; x != s1; x = x->next) {
                            if (x->astParent == nullptr && (x->astOp1 || x->varId)) {
                                processExpression(x, st);
                            }
                        }
                    }
                }
                for (int w : writes)
                    st[w] = VarState();
                if (t->str != "for")
                    processExpression(open->astOp1, st);
                if (body && body->str == "{") {
                    State sb = st;
                    walk(body->next, body->link, sb);
                    st = merge(st, sb);
                    for (int w : writes)
                        st[w] = VarState();
                    t = body->link->next;
                } else
                    t = open->link->next;
                continue;
            }
            if (t->str == "do" && t->next && t->next->str == "{") {
                Token* body = t->next;
                std::set<int> writes;
                collectWrites(body, body->link, writes);
                for (int w : writes)
                    st[w] = VarState();
                State sb = st;
                walk(body->next, body->link, sb);
                st = merge(st, sb);
                for (int w : writes)
                    st[w] = VarState();
                t = body->link->next;
                continue;
            }
            if (t->str == "else") {
                t = t->next;
                continue;
            }
            if (t->str == "case" || t->str == "default") {
                while (t && t != end && t->str != ":")
                    t = t->next;
                if (t) t = t->next;
                continue;
            }
            if (t->str == "return" || t->str == "throw") {
                processExpression(t->astOp1, st);
                while (t && t != end && t->str != ";")
                    t = t->next;
                continue;
            }
            if (t->str == "goto" || t->str == "break" || t->str == "continue") {
                while (t && t != end && t->str != ";")
                    t = t->next;
                continue;
            }
            // statement: find end, process roots in order
            Token* se = t;
            while (se && se != end && se->str != ";") {
                if (se->str == "(" || se->str == "[" || (se->str == "{" && se->link))
                    se = se->link;
                se = se->next;
            }
            // declarations: uninit state
            for (Token* x = t; x && x != se; x = x->next) {
                if (x->var && x->var->nameTok == x && x->var->isLocal) {
                    Variable* v = x->var;
                    if (!v->hasInit && !v->isStatic && !v->isExtern && !v->isArray && !v->isClassType && !v->isReference)
                        st[v->varId].kind = VarState::UNINIT;
                    else
                        st[v->varId] = VarState();
                }
                if (x->astParent == nullptr && (x->astOp1 || x->astOp2 || x->varId || x->isNumber())) {
                    if (x->var && x->var->nameTok == x)
                        continue;
                    processExpression(x, st);
                }
                if (x->str == "(" || x->str == "[" || (x->str == "{" && x->link)) {
                    // roots inside brackets are handled through AST; skip nested
                    if (x->astParent == nullptr && !x->astOp1 && x->link)
                        ;
                }
            }
            t = se;
        }
    }

    void run() {
        for (Scope* fs : tz.db.functionScopes) {
            State st;
            walk(fs->bodyStart->next, fs->bodyEnd, st);
        }
        // global initializers and remaining constant expressions
        for (Token* t = tz.list.front; t; t = t->next) {
            if (t->isNumber()) {
                long long v;
                if (parseInt(t->str, v))
                    setKnown(t, v);
            }
        }
    }
};

}

void runValueFlow(Tokenizer& tz, const Settings& settings)
{
    ValueFlow vf(tz, settings);
    vf.run();
}
