#include "checks.h"
#include "util.h"
#include <map>
#include <set>
#include <algorithm>
#include <functional>
#include <iostream>
#include <cstdlib>

// ---------------------------------------------------------------------------
// helpers

static bool isVarRead(const Token* tok)
{
    // returns true if variable token is read (rvalue) at this position
    const Token* p = tok->astParent;
    if (!p)
        return true;
    if (p->isAssignmentOp() && p->astOp1 == tok)
        return p->str != "=";
    if (p->str == "&" && p->isUnaryOp)
        return false;
    if (p->str == "sizeof")
        return false;
    return true;
}

static const Token* skipUnaryAndCasts(const Token* t)
{
    while (t && (t->isCast || (t->str == "(" && !t->astOp2 && t->astOp1 && !t->astOp1->isName())))
        t = t->astOp1;
    return t;
}

// ---------------------------------------------------------------------------
// Bounds checking

static void checkArrayIndex(CheckContext& c)
{
    for (Token* t = c.tz.list.front; t; t = t->next) {
        if (t->str != "[" || !t->astOp1 || !t->astOp2)
            continue;
        const Token* arr = t->astOp1;
        if (!arr->varId || !arr->var)
            continue;
        const Variable* v = arr->var;
        if (!v->isArray || v->dims.empty() || v->isArgument)
            continue;
        // which dimension?
        int dimIndex = 0;
        const Token* idxTok = t->astOp2;
        long long dim = v->dims[0];
        (void)dimIndex;
        if (dim <= 0)
            continue;
        // declaration itself
        if (arr == v->nameTok)
            continue;
        // &arr[N] is allowed for one past end
        const Value* val = idxTok->getKnownIntValue();
        if (!val)
            continue;
        const long long idx = val->intvalue;
        bool addressOf = false;
        if (t->astParent && t->astParent->str == "&" && t->astParent->isUnaryOp)
            addressOf = true;
        if (idx >= dim && !(addressOf && idx == dim)) {
            std::string dims;
            for (long long d : v->dims)
                dims += "[" + std::to_string(d) + "]";
            std::vector<std::pair<const Token*, std::string>> path = val->errorPath;
            path.push_back({t, "Array index out of bounds"});
            c.reportPath(path, Severity::error, "arrayIndexOutOfBounds",
                         "$symbol:" + v->name + "\nArray '" + v->name + dims + "' accessed at index " + std::to_string(idx) + ", which is out of bounds.", 788);
        } else if (idx < 0) {
            std::string dims;
            for (long long d : v->dims)
                dims += "[" + std::to_string(d) + "]";
            std::vector<std::pair<const Token*, std::string>> path = val->errorPath;
            path.push_back({t, "Negative array index"});
            c.reportPath(path, Severity::error, "negativeIndex",
                         "$symbol:" + v->name + "\nArray '" + v->name + dims + "' accessed at index " + std::to_string(idx) + ", which is out of bounds.", 786);
        }
    }
}

// ---------------------------------------------------------------------------
// Null pointer

static void checkNullPointer(CheckContext& c)
{
    for (Token* t = c.tz.list.front; t; t = t->next) {
        if (!t->varId || !t->var || !t->var->isPointer())
            continue;
        const Token* p = t->astParent;
        if (!p)
            continue;
        bool deref = false;
        if (p->str == "*" && p->isUnaryOp && p->astOp1 == t)
            deref = true;
        else if (p->str == "[" && p->astOp1 == t)
            deref = true;
        else if (p->str == "->" && p->astOp1 == t)
            deref = true;
        if (!deref)
            continue;
        // address-of deref: &p[0], &p->x is not a deref of value
        if ((p->str == "[" || p->str == "->") && p->astParent && p->astParent->str == "&" && p->astParent->isUnaryOp)
            continue;
        const Value* val = nullptr;
        for (const Value& v : t->values)
            if (v.kind == Value::INT && v.known && v.intvalue == 0)
                val = &v;
        if (!val)
            continue;
        std::vector<std::pair<const Token*, std::string>> path = val->errorPath;
        path.push_back({t, "Null pointer dereference"});
        c.reportPath(path, Severity::error, "nullPointer", "$symbol:" + t->str + "\nNull pointer dereference: $symbol", 476);
    }
}

// ---------------------------------------------------------------------------
// Other

static void checkZeroDivision(CheckContext& c)
{
    for (Token* t = c.tz.list.front; t; t = t->next) {
        if ((t->str != "/" && t->str != "%" && t->str != "/=" && t->str != "%=") || !t->astOp1 || !t->astOp2)
            continue;
        // floating point division is not checked
        const Token* rhs = t->astOp2;
        const Value* val = rhs->getKnownIntValue();
        if (!val || val->intvalue != 0)
            continue;
        bool isFloat = false;
        for (const Token* x : {t->astOp1, t->astOp2}) {
            if (x->var && x->var->isFloat())
                isFloat = true;
            if (x->isNumber() && (x->str.find('.') != std::string::npos || ((x->str.find('e') != std::string::npos || x->str.find('E') != std::string::npos) && x->str.find('x') == std::string::npos)))
                isFloat = true;
        }
        if (isFloat)
            continue;
        std::vector<std::pair<const Token*, std::string>> path = val->errorPath;
        path.push_back({t, "Division by zero"});
        c.reportPath(path, Severity::error, "zerodiv", "Division by zero.", 369);
    }
}

// ---------------------------------------------------------------------------
// Uninitialized variables

static void checkUninitVar(CheckContext& c)
{
    std::set<int> reported;
    for (Token* t = c.tz.list.front; t; t = t->next) {
        if (!t->varId || !t->var)
            continue;
        bool uninit = false;
        for (const Value& v : t->values)
            if (v.kind == Value::UNINIT)
                uninit = true;
        if (!uninit)
            continue;
        if (!isVarRead(t))
            continue;
        const Token* p = t->astParent;
        // pointer: only deref or use counts
        if (reported.count(t->varId))
            continue;
        reported.insert(t->varId);
        (void)p;
        c.report(t, Severity::error, "uninitvar", "$symbol:" + t->str + "\nUninitialized variable: $symbol", 457);
    }
}

// ---------------------------------------------------------------------------
// UnusedVar

struct VarUsage {
    const Variable* var;
    bool read = false;
    bool written = false;
    bool addressTaken = false;
    bool used = false;   // any use
    std::vector<const Token*> writes;  // assignment tokens for unread reporting
};

static bool isRecordType(const Variable* v)
{
    return v->isClassType;
}

static void checkUnusedVar(CheckContext& c, std::vector<std::pair<const Token*, std::string>>& structMemberMsgs)
{
    if (!c.style())
        return;
    (void)structMemberMsgs;
    for (Scope* fs : c.tz.db.functionScopes) {
        std::vector<const Variable*> vars;
        std::function<void(const Scope*)> collect = [&](const Scope* s) {
            for (const Variable* v : s->varlist)
                if (v->isLocal && !v->isStatic && !v->isExtern && !v->isReference)
                    vars.push_back(v);
            for (const Scope* n : s->nested)
                if (n->type != Scope::eLambda)
                    collect(n);
        };
        collect(fs);
        std::sort(vars.begin(), vars.end(), [](const Variable* a, const Variable* b) { return a->nameTok->index < b->nameTok->index; });
        std::map<int, VarUsage> usage;
        for (const Variable* v : vars) {
            VarUsage u;
            u.var = v;
            usage[v->varId] = u;
        }
        // scan uses
        for (Token* t = fs->bodyStart; t && t != fs->bodyEnd; t = t->next) {
            if (!t->varId)
                continue;
            auto it = usage.find(t->varId);
            if (it == usage.end())
                continue;
            VarUsage& u = it->second;
            const Variable* v = u.var;
            if (t == v->nameTok) {
                if (v->hasInit) {
                    u.written = true;
                    // initialization: '=' token
                    const Token* eq = v->initTok ? v->initTok->prev : nullptr;
                    if (eq && eq->str == "=") {
                        // initialized with a value
                        bool isCtor = v->isClassType && c.cpp;
                        if (!isCtor)
                            u.writes.push_back(eq);
                    } else if (v->initTok && (v->initTok->str == "{" || v->initTok->str == "(")) {
                        if (!v->isClassType)
                            u.writes.push_back(v->initTok);
                    }
                }
                continue;
            }
            u.used = true;
            const Token* p = t->astParent;
            // walk up member access / array index for writes like s.a = 1 or arr[0] = 1
            const Token* top = t;
            while (top->astParent && ((top->astParent->str == "." && top->astParent->astOp1 == top) || (top->astParent->str == "[" && top->astParent->astOp1 == top)))
                top = top->astParent;
            p = top->astParent;
            if (p && p->str == "=" && p->astOp1 == top) {
                u.written = true;
                if (top == t || !v->isPointer())
                    u.writes.push_back(p);
                else
                    u.read = true;
                if (top != t && v->isPointer())
                    u.read = true;
                continue;
            }
            if (p && p->isAssignmentOp() && p->astOp1 == top) {
                // compound assignment: writes, doesn't count as read of previous value
                u.written = true;
                u.writes.push_back(p);
                if (top != t && v->isPointer())
                    u.read = true;
                continue;
            }
            if (p && p->isIncDec() && p->astOp1 == top) {
                // ++ reads and writes. If the result is used, it's a read
                u.written = true;
                if (p->astParent) {
                    u.read = true;
                } else {
                    u.writes.push_back(p);
                    u.read = u.read; // previous value consumed
                    u.consumedByIncDec.push_back(p);
                }
                continue;
            }
            if (p && p->str == "&" && p->isUnaryOp) {
                u.addressTaken = true;
                u.read = true;
                continue;
            }
            u.read = true;
        }
        // report unread writes
        std::vector<std::pair<const Token*, std::string>> unread;
        for (const Variable* v : vars) {
            VarUsage& u = usage[v->varId];
            if (u.read || u.addressTaken)
                continue;
            if (v->isClassType && c.cpp)
                continue;
            if (u.writes.empty())
                continue;
            // which writes to report: writes that are not followed by another plain write before end
            for (std::size_t i = 0; i < u.writes.size(); ++i) {
                const Token* w = u.writes[i];
                // an initialization followed by a plain assignment (no read) is not reported (redundant)
                bool skip = false;
                if (i + 1 < u.writes.size()) {
                    const Token* nw = u.writes[i + 1];
                    if (nw->str == "=" && w->scope == nw->scope) {
                        skip = true;
                        // consumed by ++?
                    }
                    if (std::find(u.consumedByIncDec.begin(), u.consumedByIncDec.end(), nw) != u.consumedByIncDec.end())
                        skip = true;
                }
                if (skip)
                    continue;
                std::string name = v->name;
                const Token* lhs = w->astOp1;
                if (lhs && lhs != v->nameTok && (lhs->str == "." || lhs->str == "["))
                    name = exprString(lhs);
                if (w->str == "{" || w->str == "(")
                    name = v->name;
                unread.push_back({w, name});
            }
        }
        std::sort(unread.begin(), unread.end(), [](const std::pair<const Token*, std::string>& a, const std::pair<const Token*, std::string>& b) {
            return a.first->index < b.first->index;
        });
        for (const auto& u : unread)
            c.report(u.first, Severity::style, "unreadVariable", "$symbol:" + u.second + "\nVariable '$symbol' is assigned a value that is never used.", 563);
        // unused / unassigned
        for (const Variable* v : vars) {
            VarUsage& u = usage[v->varId];
            if (!u.used && !u.written) {
                if (v->isClassType && c.cpp)
                    continue;
                c.report(v->nameTok, Severity::style, "unusedVariable", "$symbol:" + v->name + "\nUnused variable: $symbol", 563);
            } else if (!u.written && u.read && !u.addressTaken) {
                if (v->isClassType || v->isArray)
                    continue;
                c.report(v->nameTok, Severity::style, "unassignedVariable", "$symbol:" + v->name + "\nVariable '$symbol' is not assigned a value.", 665);
            }
        }
    }
}

static void checkStructMemberUsage(CheckContext& c)
{
    if (!c.style())
        return;
    for (Scope* s : c.tz.db.classScopes) {
        if (s->type != Scope::eStruct && s->type != Scope::eUnion && !(s->type == Scope::eClass))
            continue;
        if (s->type == Scope::eClass)
            continue;
        if (s->className.empty())
            continue;
        if (s->type == Scope::eUnion)
            continue;
        // if struct has member functions skip
        if (!s->functions.empty())
            continue;
        for (const Variable* v : s->varlist) {
            if (!v->isMember)
                continue;
            bool used = false;
            for (const Token* t = c.tz.list.front; t; t = t->next) {
                if (t->str == v->name && t != v->nameTok && t->prev && (t->prev->str == "." || t->prev->str == "->")) {
                    used = true;
                    break;
                }
                if (t->str == v->name && t != v->nameTok && t->scope && t->scope->type != Scope::eStruct && !(t->prev && (t->prev->str == "." || t->prev->str == "->"))) {
                    // designated initializer .x = or plain use
                }
            }
            // struct used with initializer lists or memcpy etc are considered
            if (!used) {
                // check if struct variable is ever initialized via {..} or passed somewhere (cppcheck still reports)
                c.report(v->nameTok, Severity::style, "unusedStructMember", "$symbol:" + s->className + "::" + v->name + "\nstruct member '$symbol' is never used.", 563);
            }
        }
    }
}

// ---------------------------------------------------------------------------

static void collectFunctionUsage(CheckContext& c)
{
    FunctionUsageInfo* usage = c.actx.usage;
    if (!usage)
        return;
    const std::string file = c.actx.file0;
    for (Function* f : c.tz.db.functionList) {
        if (!f->hasBody)
            continue;
        if (f->tokenDef->fileIndex != 0)
            continue;
        FunctionUsageInfo::Decl d;
        d.name = f->name;
        d.file = c.fileOf(f->tokenDef);
        d.line = f->tokenDef->line;
        d.col = f->tokenDef->col;
        d.isStatic = f->isStatic || f->isInline;
        d.isMain = (f->name == "main" || f->name == "wmain" || f->name == "WinMain" || f->name == "_tmain");
        d.isMember = f->isMember || f->isOperator || f->isConstructor || f->isDestructor;
        d.fileOrder = (int)usage->definitions.size();
        bool dup = false;
        for (const auto& e : usage->definitions)
            if (e.name == d.name && e.file == d.file && e.line == d.line)
                dup = true;
        if (!dup)
            usage->definitions.push_back(d);
    }
    for (Token* t = c.tz.list.front; t; t = t->next) {
        if (!t->isName() || t->varId)
            continue;
        if (t->func && t->func->tokenDef == t)
            continue;
        bool isUse = false;
        if (t->next && t->next->str == "(")
            isUse = true;
        else if (t->prev && (t->prev->str == "=" || t->prev->str == "(" || t->prev->str == "," || t->prev->str == "&" || t->prev->str == "return" || t->prev->str == "{"))
            isUse = true;
        if (!isUse)
            continue;
        // declarations of functions are not uses
        if (t->next && t->next->str == "(" && t->prev && (t->prev->isName() || t->prev->str == "*") && !t->prev->isKeyword() && t->scope && !t->scope->isExecutable())
            continue;
        if (t->next && t->next->str == "(" && t->prev && t->prev->isName() && t->prev->str != "return" && t->prev->str != "else" && t->prev->str != "case" && t->prev->str != "new" && t->prev->str != "throw" && t->prev->str != "delete")
            continue;
        usage->usedNames.insert(t->str);
        usage->usedInFiles[t->str].insert(file);
    }
}

void analyzeWholeProgram(AnalysisContext& ctx)
{
    if (!ctx.settings.unusedFunction || !ctx.usage)
        return;
    FunctionUsageInfo* usage = ctx.usage;
    std::vector<const FunctionUsageInfo::Decl*> unused, staticCands;
    std::set<std::string> reported;
    for (const auto& d : usage->definitions) {
        if (d.isMain || d.isMember)
            continue;
        const bool used = usage->usedNames.count(d.name) != 0;
        if (!used) {
            if (reported.insert(d.name).second)
                unused.push_back(&d);
        }
    }
    for (const auto& d : usage->definitions) {
        if (d.isMain || d.isMember || d.isStatic)
            continue;
        const bool used = usage->usedNames.count(d.name) != 0;
        if (!used)
            continue;
        const auto& files = usage->usedInFiles[d.name];
        bool usedElsewhere = false;
        for (const std::string& f : files)
            if (f != d.file)
                usedElsewhere = true;
        // defined in multiple files?
        if (!usedElsewhere)
            staticCands.push_back(&d);
    }
    for (const auto* d : unused) {
        std::list<FileLocation> cs;
        cs.emplace_back(d->file, d->line, d->col);
        ctx.file0 = d->file;
        ctx.reportError(cs, Severity::style, "unusedFunction", "$symbol:" + d->name + "\nThe function '$symbol' is never used.", 561);
    }
    for (const auto* d : staticCands) {
        std::list<FileLocation> cs;
        cs.emplace_back(d->file, d->line, d->col);
        ctx.file0 = d->file;
        ctx.reportError(cs, Severity::style, "staticFunction", "$symbol:" + d->name + "\nThe function '$symbol' should have static linkage since it is not used outside of its translation unit.", 0);
    }
}

// ---------------------------------------------------------------------------

static void debugDump(Tokenizer& tz)
{
    for (Token* t = tz.list.front; t; t = t->next) {
        std::cerr << t->str;
        if (t->varId) std::cerr << "@" << t->varId;
        if (t->astParent) std::cerr << "^" << t->astParent->str;
        for (const Value& v : t->values) {
            if (v.kind == Value::INT) std::cerr << "{" << v.intvalue << "}";
            else if (v.kind == Value::UNINIT) std::cerr << "{U}";
        }
        std::cerr << ((t->next && t->next->line != t->line) ? "\n" : " ");
    }
    std::cerr << "\n";
    for (const Scope& s : tz.db.scopes) {
        std::cerr << "scope type=" << s.type << " name=" << s.className << " vars:";
        for (const Variable* v : s.varlist)
            std::cerr << " " << v->name << "(" << v->varId << (v->isLocal ? ",L" : "") << (v->isArgument ? ",A" : "") << (v->isGlobal ? ",G" : "") << (v->isMember ? ",M" : "") << (v->isPointer() ? ",P" : "") << (v->isArray ? ",[]" : "") << ")";
        std::cerr << "\n";
    }
    for (const Function* f : tz.db.functionList)
        std::cerr << "function " << f->name << " body=" << f->hasBody << " static=" << f->isStatic << "\n";
}

bool analyzeTokens(AnalysisContext& ctx, const std::vector<PPToken>& tokens, Preprocessor& pp)
{
    (void)pp;
    Tokenizer tz;
    TokenizeResult res = tz.tokenize(tokens, ctx.fileNames, ctx.cpp);
    CheckContext c{ctx, tz, ctx.settings, ctx.cpp};
    if (!res.ok) {
        if (res.errTok)
            c.report(res.errTok, Severity::error, res.errId, res.errMsg, 0);
        else
            ctx.reportError({}, Severity::error, res.errId, res.errMsg, 0);
        return false;
    }
    runValueFlow(tz, ctx.settings);
    if (std::getenv("CPPC_DEBUG"))
        debugDump(tz);

    // check classes in name order
