static void checkRedundantAssignment(CheckContext& c)
{
    if (!c.style())
        return;
    struct Item { const Token* w1; const Token* w2; std::string name; };
    std::vector<Item> items;
    for (Scope* fs : c.tz.db.functionScopes) {
        for (Token* t = fs->bodyStart; t && t != fs->bodyEnd; t = t->next) {
            if (t->str != "=" || !t->astOp1 || !t->astOp1->varId || !t->astOp1->var)
                continue;
            const Token* lhs = t->astOp1;
            const Variable* v = lhs->var;
            if (lhs == v->nameTok)
                continue;  // initialization
            if (v->isReference || v->isArray || (v->isClassType && c.cpp) || v->isArgument && v->isPointer())
                continue;
            if (!(v->isLocal || v->isGlobal || v->isArgument || v->isStatic))
                continue;
            if (t->astParent)
                continue;
            const Token* se = statementEndOf(t);
            if (!se || se->str != ";")
                continue;
            const bool global = v->isGlobal || v->isStatic || v->isMember;
            FwdResult fr = forwardAnalyze(lhs, se, v->varId, fs, global);
            if (fr.read || fr.bail || !fr.killTok)
                continue;
            // the kill must be in the same scope (straight-line)
            if (fr.killTok->scope != t->scope)
                continue;
            items.push_back({t, fr.killTok, v->name});
        }
    }
    for (const Item& it : items) {
        std::vector<std::pair<const Token*, std::string>> path;
        path.push_back({it.w1, it.name + " is assigned"});
        path.push_back({it.w2, it.name + " is overwritten"});
        c.reportPath(path, Severity::style, "redundantAssignment",
                     "$symbol:" + it.name + "\nVariable '$symbol' is reassigned a value before the old one has been used.", 563);
    }
