static bool isSimpleInit(const Token* tok)
{
    if (!tok)
        return true;
    std::vector<const Token*> st{tok};
    while (!st.empty()) {
        const Token* t = st.back();
        st.pop_back();
        if (!t) continue;
        if (t->str == "(" && !t->isCast)
            return false;
        if (t->varId)
            return false;
        if (t->isName() && !t->isKeyword() && t->str != "NULL")
            return false;
        st.push_back(t->astOp1);
        st.push_back(t->astOp2);
    }
    return true;
}

