static void checkVariableScope(CheckContext& c)
{
    if (!c.style())
        return;
    std::vector<const Variable*> vars;
    for (const Variable& v : c.tz.db.variables)
        if (v.isLocal && !v.isConst && !v.isStatic && v.scope && v.scope->isExecutable())
            vars.push_back(&v);
    std::sort(vars.begin(), vars.end(), [](const Variable* a, const Variable* b) { return a->nameTok->index < b->nameTok->index; });
    for (const Variable* var : vars) {
        if (var->nameTok->macro)
            continue;
        const bool isPtrOrRef = var->isPointer() || var->isReference;
        const bool isSimpleType = var->isBuiltin() || (!c.cpp && var->isStruct);
        if (!isPtrOrRef && !isSimpleType)
            continue;
        if (var->isArray && !c.cpp && false)
            continue;
        const Token* tok = var->nameTok->next;
        while (tok && tok->str == "[")
            tok = tok->link->next;
        if (tok && tok->str == "=") {
            if (!isSimpleInit(tok->astOp2))
                continue;
        } else if (tok && (tok->str == "{" || tok->str == "(")) {
