            if (tok->str == "{" && tok->scope != scope && tok->scope && tok->scope->bodyStart == tok && tok->scope->type != Scope::eLambda) {
                if (used) {
                    bool used2 = false;
                    if (!checkInnerScope(tok, var, used2) || used2) {
                        reduce = false;
                        break;
