static bool checkInnerScope(const Token* tok, const Variable* var, bool& used)
{
    const Scope* scope = tok->scope;
    bool loopVariable = scope->isLoop();
    bool noContinue = true;
    const Token* end = tok->link;
    if (scope->type == Scope::eDo && end->next && end->next->str == "while")
        end = end->next->next->link;
    else if (loopVariable && tok->prev && tok->prev->str == ")")
        tok = tok->prev->link;
