    if ((scope->type == Scope::eIf || scope->type == Scope::eSwitch) && scope->condStart) {
        for (const Token* x = scope->condStart; x != scope->condStart->link; x = x->next)
            if (x->varId == var->varId)
                return false;
    }
    bool bFirstAssignment = false;
    const Token* forHeadEnd = nullptr;
