                    if (semi->varId == var->varId)
                        return false;
                    semi = semi->next;
                }
            }
            bFirstAssignment = true;
        }
        if (!bFirstAssignment && tok->str == "*" && tok->next && tok->next->varId == var->varId)
            return false;
        if (tok->str == "=" && tok->next && tok->next->varId == var->varId && (var->isArray || var->isPointer()))
