// ---------------------------------------------------------------------------
// Condition

static bool hasVarInExpr(const Token* tok)
{
    std::vector<const Token*> st{tok};
    while (!st.empty()) {
        const Token* t = st.back();
        st.pop_back();
        if (!t) continue;
        if (t->varId) return true;
        if (t->str == "sizeof") continue;
        st.push_back(t->astOp1);
        st.push_back(t->astOp2);
    }
    return false;
}

static bool isVarLiteralComparison(const Token* tok)
{
    if (!tok || (tok->str != "==" && tok->str != "!="))
        return false;
    const Token* a = tok->astOp1;
    const Token* b = tok->astOp2;
    if (!a || !b)
        return false;
    return (a->varId && (b->isNumber() || b->isChar())) || (b->varId && (a->isNumber() || a->isChar()));
}

static void checkAlwaysTrueFalse(CheckContext& c)
{
    if (!c.style())
        return;
    std::set<const Token*> done;
    std::function<void(const Token*)> checkCond = [&](const Token* cond) {
        if (!cond)
            return;
        if (cond->str == "&&" || cond->str == "||") {
            checkCond(cond->astOp1);
            checkCond(cond->astOp2);
        }
        const Value* v = cond->getKnownIntValue();
        if (!v)
            return;
        if (!hasVarInExpr(cond))
            return;
        if (isVarLiteralComparison(cond))
            return;
        if (cond->macro)
            return;
        if (!done.insert(cond).second)
            return;
        std::vector<std::pair<const Token*, std::string>> path = v->errorPath;
        if (path.empty())
            return;
        const std::string expr = exprString(cond);
        const std::string tf = v->intvalue ? "true" : "false";
        path.push_back({cond, "Condition '" + expr + "' is always " + tf});
        c.reportPath(path, Severity::style, "knownConditionTrueFalse", "$symbol:" + expr + "\nCondition '$symbol' is always " + tf, 571);
    };
    for (Token* t = c.tz.list.front; t; t = t->next) {
        if ((t->str == "if" || t->str == "while") && t->next && t->next->str == "(" && t->next->astOp1) {
            if (t->str == "while" && t->next->link->next && t->next->link->next->str == ";")
                ; // do-while condition
            checkCond(t->next->astOp1);
        }
    }
}

// ---------------------------------------------------------------------------
// Other: duplicate expressions / known comparisons

static bool sameExpr(const Token* a, const Token* b)
{
    if (!a || !b)
        return a == b;
    if (a->str != b->str || a->varId != b->varId)
        return false;
    if (a->isUnaryOp != b->isUnaryOp || a->isCast != b->isCast)
        return false;
    if (a->str == "(" && !a->isCast)
        return false; // function call may have side effects
    if (a->isIncDec() || a->isAssignmentOp())
        return false;
    return sameExpr(a->astOp1, b->astOp1) && sameExpr(a->astOp2, b->astOp2);
}

static std::string spacedExpr(const Token* tok)
{
    // expression with spaces between tokens, e.g. "x == 5"
    const Token* a = tok->astOp1;
    const Token* b = tok->astOp2;
    return exprString(a) + " " + tok->str + " " + exprString(b);
}

static void checkDuplicateExpression(CheckContext& c)
{
    if (!c.style())
        return;
    for (Token* t = c.tz.list.front; t; t = t->next) {
        if (!t->astOp1 || !t->astOp2)
            continue;
        if (isVarLiteralComparison(t)) {
            const Token* var = t->astOp1->varId ? t->astOp1 : t->astOp2;
            const Value* vv = var->getKnownIntValue();
            const Value* res = t->getKnownIntValue();
            if (vv && res && !vv->errorPath.empty()) {
                const Token* assignTok = vv->errorPath.front().first;
                const std::string tf = res->intvalue ? "true" : "false";
                const std::string expr = spacedExpr(t);
                std::vector<std::pair<const Token*, std::string>> path;
                path.push_back({assignTok, "'" + var->str + "' is assigned value '" + exprString(assignTok) + "' here."});
                path.push_back({t, "The comparison '" + expr + "' is always " + tf + "."});
                c.reportPath(path, Severity::style, "knownConditionTrueFalse", "$symbol:" + expr + "\nThe comparison '$symbol' is always " + tf + ".", 570);
                continue;
            }
        }
        static const std::set<std::string> ops = {"||", "&&", "==", "!=", "<", "<=", ">", ">=", "-", "/", "%", "&", "|", "^"};
