            if (ctor->bodyStart) {
                std::set<const Function*> visited;
                std::function<void(const Token*, const Token*)> scanBody = [&](const Token* s, const Token* e) {
                    for (const Token* t = s; t && t != e; t = t->next) {
                        if (t->isName()) {
                            const Token* p = t->astParent;
                            const Token* top = t;
                            if (p && (p->str == "." || p->str == "->") && p->astOp2 == t && p->astOp1 && p->astOp1->str == "this")
                                top = p;
                            p = top->astParent;
                            if (p && p->isAssignmentOp() && p->astOp1 == top)
                                initialized.insert(t->str);
                            else if (p && (p->str == "(" || p->str == ",") && !p->isCast)
                                initialized.insert(t->str);   // passed to function
                            else if (p && p->str == "&" && p->isUnaryOp)
                                initialized.insert(t->str);
                            else if (p && p->str == "[" && p->astOp1 == top)
                                initialized.insert(t->str);
                            // member function call
                            if (t->next && t->next->str == "(" && !t->varId) {
                                bool found = false;
                                for (Function* f : funcs) {
                                    if (f->name == t->str && f->hasBody && !f->isConstructor) {
                                        found = true;
                                        if (visited.insert(f).second)
                                            scanBody(f->bodyStart, f->bodyEnd);
                                    }
                                }
                                if (!found && t->str != "sizeof" && !t->isKeyword())
                                    callsMember = callsMember || false;
                            }
                        }
                    }
                };
                scanBody(ctor->bodyStart, ctor->bodyEnd);
            }
            (void)callsMember;
            for (const Variable* v : members) {
                if (!memberNeedsInit(v))
                    continue;
                if (initialized.count(v->name))
                    continue;
                const std::string what = isCopy ? "copy constructor" : "constructor";
                c.report(ctor->tokenDef, Severity::warning, "uninitMemberVar",
                         "$symbol:" + cls->className + "::" + v->name + "\nMember variable '$symbol' is not initialized in the " + what + ".", 398);
            }
        }
    }
}

static void checkVirtualDestructor(CheckContext& c)
{
    // collect deleted pointer types
    std::set<std::string> deletedTypes;
    for (const Token* t = c.tz.list.front; t; t = t->next) {
        if (t->str != "delete")
            continue;
        const Token* v = t->next;
        if (v && v->str == "[") v = v->link->next;
        if (v && v->varId && v->var) {
            for (const Token* x = v->var->typeStart; x && x != v->var->nameTok; x = x->next)
                if (x->isName())
                    deletedTypes.insert(x->str);
        }
    }
    for (Scope* derived : c.tz.db.classScopes) {
        for (const std::string& baseName : baseClasses(derived)) {
            const Scope* base = findClass(c, baseName);
            if (!base)
                continue;
            if (!deletedTypes.count(baseName))
                continue;
            // find destructor in base
            const Function* dtor = nullptr;
            for (Function* f : classFunctions(c, base))
                if (f->isDestructor)
                    dtor = f;
            if (dtor && dtor->isVirtual)
                continue;
            if (dtor && !isAccessPublic(base, dtor->tokenDef))
                continue;
            const Token* loc = dtor ? dtor->tokenDef : base->classDef;
            c.report(loc, Severity::error, "virtualDestructor",
                     "$symbol:" + baseName + "\n$symbol:" + derived->className + "\nClass '" + baseName + "' which is inherited by class '" + derived->className + "' does not have a virtual destructor.", 404);
        }
    }
}

static void checkExplicitConstructors(CheckContext& c)
{
    if (!c.style())
        return;
    for (Scope* cls : c.tz.db.classScopes) {
        if (!cls->isClassOrStruct() || cls->className.empty())
            continue;
        // abstract classes are skipped
        bool abstract = false;
        for (Function* f : classFunctions(c, cls)) {
            const Token* close = f->argStart->link;
            const Token* t = close->next;
            while (t && (t->str == "const" || t->str == "override" || t->str == "noexcept")) t = t->next;
            if (t && t->str == "=" && t->next && t->next->str == "0")
                abstract = true;
        }
        if (abstract)
            continue;
        for (Function* f : classFunctions(c, cls)) {
            if (!f->isConstructor || f->name != cls->className || f->nestedIn != cls)
                continue;
            bool isExplicit = false;
            for (const Token* t = f->retStart; t && t != f->tokenDef; t = t->next)
                if (t->str == "explicit")
                    isExplicit = true;
            if (isExplicit)
                continue;
            // count args and defaults
            const Token* open = f->argStart;
            int args = 0, required = 0;
            bool isCopyMove = false;
            const Token* argStart = open->next;
            while (argStart && argStart != open->link) {
                const Token* argEnd = argStart;
                bool hasDefault = false;
                while (argEnd != open->link && argEnd->str != ",") {
                    if (argEnd->str == "=") hasDefault = true;
                    if (argEnd->str == cls->className) isCopyMove = true;
                    if (argEnd->str == "(" || argEnd->str == "[" || argEnd->str == "{") argEnd = argEnd->link;
                    else if (argEnd->str == "<") { Token* cl = findClosingBracket(const_cast<Token*>(argEnd)); if (cl) argEnd = cl; }
                    argEnd = argEnd->next;
                }
                if (!(argStart->str == "void" && argStart->next == argEnd)) {
                    args++;
                    if (!hasDefault) required++;
                }
                argStart = argEnd == open->link ? argEnd : argEnd->next;
            }
            if (args == 0 || required > 1)
                continue;
            if (isCopyMove && args == 1)
                continue;
            if (required == 0 && args > 0)
                ; // default args only
            if (required != 1 && !(required == 0 && args >= 1))
                continue;
            if (required == 0)
                continue;
            c.report(f->tokenDef, Severity::style, "noExplicitConstructor",
                     "$symbol:" + cls->className + "\nClass '$symbol' has a constructor with 1 argument that is not explicit.", 398);
        }
    }
}

static int argCount(const Function* f)
{
    return (int)f->args.size();
}

static std::string bodyString(const Function* f)
{
    std::string s;
    if (!f->bodyStart)
        return s;
    for (const Token* t = f->bodyStart; t && t != f->bodyEnd; t = t->next)
        s += t->str + " ";
    return s;
}

static void checkOverride(CheckContext& c, bool useless)
{
    if (!c.style())
        return;
    if (!useless && c.settings.standards.cpp < Standards::CPP11)
        return;
    for (Scope* derived : c.tz.db.classScopes) {
        std::vector<std::string> bases = baseClasses(derived);
        if (bases.empty())
            continue;
        for (Function* f : classFunctions(c, derived)) {
            if (f->nestedIn != derived || f->isConstructor || f->isDestructor)
                continue;
            bool hasOverride = false;
            for (const Token* t = f->argStart->link->next; t && t->str != "{" && t->str != ";"; t = t->next)
                if (t->str == "override" || t->str == "final")
                    hasOverride = true;
            // find virtual base function
            std::function<const Function*(const std::string&, int)> findBase = [&](const std::string& bname, int depth) -> const Function* {
                if (depth > 10) return nullptr;
                const Scope* b = findClass(c, bname);
                if (!b) return nullptr;
                for (Function* bf : classFunctions(c, b)) {
                    if (bf->nestedIn == b && bf->name == f->name && bf->isVirtual && argCount(bf) == argCount(f) && bf->isConst == f->isConst)
                        return bf;
                }
                for (const std::string& bb : baseClasses(b)) {
                    const Function* r = findBase(bb, depth + 1);
                    if (r) return r;
                }
                return nullptr;
            };
            const Function* bf = nullptr;
            for (const std::string& bn : bases) {
                bf = findBase(bn, 0);
                if (bf) break;
            }
            if (!bf)
                continue;
            std::vector<std::pair<const Token*, std::string>> path;
            path.push_back({bf->tokenDef, "Virtual function in base class"});
            path.push_back({f->tokenDef, "Function in derived class"});
            if (!useless) {
                if (hasOverride)
                    continue;
                c.reportPath(path, Severity::style, "missingOverride",
                             "$symbol:" + f->name + "\nThe function '$symbol' overrides a function in a base class but is not marked with a 'override' specifier.", 0);
            } else {
                if (!f->hasBody || !bf->hasBody)
                    continue;
                if (bodyString(f) != bodyString(bf))
                    continue;
                c.reportPath(path, Severity::style, "uselessOverride",
                             "$symbol:" + f->name + "\nThe function '$symbol' overrides a function in a base class but is identical to the overridden function", 0);
            }
        }
    }
}

void runCheckClass(CheckContext& c)
{
    if (!c.cpp)
        return;
    checkConstructors(c);
    checkVirtualDestructor(c);
    checkExplicitConstructors(c);
    checkOverride(c, false);
    checkOverride(c, true);
}
