static bool isAccessPublic(const Scope* cls, const Token* tok)
{
    // determine access of a member declared at tok
    bool pub = cls->type != Scope::eClass;
    for (const Token* t = cls->bodyStart->next; t && t != tok; t = t->next) {
        if (t->str == "{" && t->link) { t = t->link; continue; }
        if (t->str == "public" && t->next && t->next->str == ":") pub = true;
        else if ((t->str == "private" || t->str == "protected") && t->next && t->next->str == ":") pub = false;
    }
    return pub;
}

static const Scope* findClass(CheckContext& c, const std::string& name)
{
