static std::vector<std::string> baseClasses(const Scope* cls)
{
    std::vector<std::string> ret;
    const Token* t = cls->classDef ? cls->classDef->next : nullptr;
    if (t && t->isName()) t = t->next;
    if (!t || t->str != ":")
        return ret;
    for (t = t->next; t && t != cls->bodyStart; t = t->next) {
        if (t->str == "public" || t->str == "private" || t->str == "protected" || t->str == "virtual" || t->str == ",")
            continue;
        if (t->isName() && (t->next == cls->bodyStart || t->next->str == "," || t->next->str == "<")) {
            ret.push_back(t->str);
            if (t->next->str == "<") {
                Token* close = findClosingBracket(const_cast<Token*>(t->next));
                if (close) t = close;
            }
        }
    }
    return ret;
}

static bool memberNeedsInit(const Variable* v)
{
    if (v->isStatic || v->isReference)
        return false;
    if (v->hasInit)
        return false;
    if (v->isConst && !v->isPointer())
        return false;
    if (v->isArray)
        return false;
    if (v->isPointer())
        return true;
    return v->isBuiltin() && !v->isClassType;
}

static void checkConstructors(CheckContext& c)
{
    for (Scope* cls : c.tz.db.classScopes) {
