        std::vector<Function*> ctors;
        for (Function* f : funcs)
            if (f->isConstructor && f->name == cls->className)
                ctors.push_back(f);
        std::vector<const Variable*> members;
        for (const Variable* v : cls->varlist)
            if (v->isMember)
                members.push_back(v);
        if (ctors.empty()) {
            if (!c.style())
                continue;
            bool privateVar = false;
            for (const Variable* v : members) {
                if (v->isStatic || isAccessPublic(cls, v->nameTok))
                    continue;
                if (memberNeedsInit(v))
                    privateVar = true;
            }
            if (privateVar) {
                const std::string kind = cls->type == Scope::eClass ? "class" : "struct";
                c.report(cls->classDef, Severity::style, "noConstructor",
                         "$symbol:" + cls->className + "\nThe " + kind + " '$symbol' does not declare a constructor although it has private member variables which likely require initialization.", 398);
            }
            continue;
        }
        if (!c.warning())
            continue;
        for (Function* ctor : ctors) {
            // = delete
            const Token* close = ctor->argStart->link;
            const Token* after = close->next;
            bool isDefault = false;
            if (after && after->str == "=" && after->next && after->next->str == "delete")
                continue;
            if (after && after->str == "=" && after->next && after->next->str == "default")
                isDefault = true;
            if (!ctor->hasBody && !isDefault)
                continue;
            // copy constructor?
            bool isCopy = false;
            if (ctor->args.size() == 1 && ctor->args[0]) {
                const Variable* a = ctor->args[0];
                for (const Token* t = a->typeStart; t && t != a->nameTok; t = t->next)
                    if (t->str == cls->className)
                        isCopy = a->isReference;
            } else if (ctor->args.size() == 1 && !ctor->args[0]) {
                for (const Token* t = ctor->argStart->next; t != close; t = t->next)
                    if (t->str == cls->className)
                        isCopy = true;
            }
            // empty default ctor in class with other ctors is skipped
            if (ctor->args.empty() && !isDefault && ctors.size() > 1 && ctor->bodyStart && ctor->bodyStart->next == ctor->bodyEnd && close->next == ctor->bodyStart)
                continue;
            std::set<std::string> initialized;
            // initializer list
            for (const Token* t = close->next; t && t != ctor->bodyStart; t = t->next) {
                if (t->isName() && t->next && (t->next->str == "(" || t->next->str == "{"))
                    initialized.insert(t->str);
                if (t->str == "(" || t->str == "{") t = t->link;
            }
            bool callsMember = false;
            if (ctor->bodyStart) {
                std::set<const Function*> visited;
                std::function<void(const Token*, const Token*)> scanBody = [&](const Token* s, const Token* e) {
                    for (const Token* t = s; t && t != e; t = t->next) {
                        if (t->isName()) {
                            const Token* p = t->astParent;
                            const Token* top = t;
                            if (p && (p->str == "." || p->str == "->") && p->astOp2 == t && p->astOp1 && p->astOp1->str == "this")
                                top = p;
                            p = top->astParent;
                            if (p && p->isAssignmentOp() && p->astOp1 == top)
                                initialized.insert(t->str);
                            else if (p && (p->str == "(" || p->str == ",") && !p->isCast)
                                initialized.insert(t->str);   // passed to function
                            else if (p && p->str == "&" && p->isUnaryOp)
                                initialized.insert(t->str);
                            else if (p && p->str == "[" && p->astOp1 == top)
                                initialized.insert(t->str);
                            // member function call
                            if (t->next && t->next->str == "(" && !t->varId) {
                                bool found = false;
                                for (Function* f : funcs) {
                                    if (f->name == t->str && f->hasBody && !f->isConstructor) {
                                        found = true;
                                        if (visited.insert(f).second)
                                            scanBody(f->bodyStart, f->bodyEnd);
                                    }
                                }
                                if (!found && t->str != "sizeof" && !t->isKeyword())
                                    callsMember = callsMember || false;
                            }
                        }
                    }
                };
                scanBody(ctor->bodyStart, ctor->bodyEnd);
            }
            (void)callsMember;
            for (const Variable* v : members) {
                if (!memberNeedsInit(v))
                    continue;
                if (initialized.count(v->name))
                    continue;
                const std::string what = isCopy ? "copy constructor" : "constructor";
                c.report(ctor->tokenDef, Severity::warning, "uninitMemberVar",
                         "$symbol:" + cls->className + "::" + v->name + "\nMember variable '$symbol' is not initialized in the " + what + ".", 398);
            }
        }
    }
}

