#include "checks.h"
#include "fwd.h"
#include <set>
#include <map>

namespace {
enum class AState { ALLOC, FREED, ESCAPED };

struct LeakScanner {
    CheckContext& c;
    int varId;
    std::string name;
    const Token* allocTok;
    bool isArrayAlloc;
    bool reportedLeak = false;
    LeakScanner(CheckContext& cc, int v, const std::string& n, const Token* a, bool arr) : c(cc), varId(v), name(n), allocTok(a), isArrayAlloc(arr) {}

    void leak(const Token* at) {
        if (reportedLeak)
            return;
        reportedLeak = true;
        c.report(at, Severity::error, "memleak", "$symbol:" + name + "\nMemory leak: $symbol", 401);
    }

    bool usesVar(const Token* start, const Token* end) const {
        for (const Token* t = start; t && t != end; t = t->next)
            if (t->varId == varId)
                return true;
        return false;
    }

    // returns state after sequence; 'returned' set if all paths return
    AState scan(const Token* start, const Token* end, AState st, bool& returned) {
        returned = false;
        for (const Token* t = start; t && t != end; t = t->next) {
            if (st != AState::ALLOC)
                return st;
            if (t->str == "{" && t->link && t->scope && t->scope->bodyStart == t) {
                const Scope* s = t->scope;
                if (s->type == Scope::eIf) {
                    const Token* close = t->link;
                    const Token* elseOpen = nullptr;
                    if (close->next && close->next->str == "else" && close->next->next && close->next->next->str == "{")
                        elseOpen = close->next->next;
                    // condition uses var?
                    bool ra = false, rb = false;
                    AState a = scan(t->next, close, st, ra);
                    AState b = elseOpen ? scan(elseOpen->next, elseOpen->link, st, rb) : st;
                    if (ra && rb) {
                        returned = true;
                        return AState::ESCAPED;
                    }
                    if (ra) st = b;
                    else if (rb) st = a;
                    else if (a == AState::ESCAPED || b == AState::ESCAPED) st = AState::ESCAPED;
                    else if (a == AState::ALLOC || b == AState::ALLOC) st = (a == AState::FREED || b == AState::FREED) ? AState::ESCAPED : AState::ALLOC;
                    else st = AState::FREED;
                    t = elseOpen ? elseOpen->link : close;
                    continue;
                }
                if (s->isLoop() || s->type == Scope::eSwitch) {
                    bool r = false;
                    AState a = scan(t->next, t->link, st, r);
                    if (a != AState::ALLOC)
                        st = AState::ESCAPED;
                    t = t->link;
                    continue;
                }
                bool r = false;
                AState a = scan(t->next, t->link, st, r);
                if (r) { returned = true; return a; }
                st = a;
                t = t->link;
                continue;
            }
            if (t->str == "return") {
                const Token* se = statementEndOf(t);
                if (usesVar(t, se))
                    return AState::ESCAPED;
                leak(t);
                returned = true;
                return AState::ESCAPED;
            }
            if (t->str == "throw" || t->str == "break" || t->str == "continue" || t->str == "goto")
                return AState::ESCAPED;
            if (t->str == "exit" || t->str == "abort")
                return AState::ESCAPED;
            if (t->str == "delete") {
                const Token* v = t->next;
                bool arr = false;
                if (v && v->str == "[" && v->next && v->next->str == "]") {
                    arr = true;
                    v = v->next->next;
                }
                if (v && v->str == "(") v = v->next;
                if (v && v->varId == varId) {
                    if (arr != isArrayAlloc) {
                        std::vector<std::pair<const Token*, std::string>> path;
                        path.push_back({allocTok, "Mismatching allocation and deallocation: " + name});
                        path.push_back({v, "Mismatching allocation and deallocation: " + name});
                        c.reportPath(path, Severity::error, "mismatchAllocDealloc", "$symbol:" + name + "\nMismatching allocation and deallocation: $symbol", 762);
                    }
                    return AState::FREED;
                }
                continue;
            }
            if (t->varId == varId) {
                const Token* p = t->astParent;
                if (!p)
                    continue;
                if (p->str == "*" && p->isUnaryOp) continue;
                if (p->str == "[" && p->astOp1 == t) continue;
                if (p->str == "->" && p->astOp1 == t) continue;
                if (p->isComparisonOp() || p->str == "!" || p->str == "&&" || p->str == "||") continue;
                if (p->str == "(" && p->prev && (p->prev->str == "if" || p->prev->str == "while")) continue;
                if (p->str == "=" && p->astOp1 == t) {
                    // reassigned
                    return AState::ESCAPED;
                }
                // assigned elsewhere, passed to function, address taken etc
                return AState::ESCAPED;
            }
        }
        return st;
    }
};
}

static bool isNewExpr(const Token* tok, bool& isArray)
{
    if (!tok || tok->str != "new")
        return false;
    isArray = false;
    const Token* t = tok->next;
    while (t && (t->isName() || t->str == "::" || t->str == "*"))
        t = t->next;
    if (t && t->str == "[")
        isArray = true;
    return true;
}

void checkLeakAutoVar(CheckContext& c)
{
    if (!c.cpp)
        return;
    for (Scope* fs : c.tz.db.functionScopes) {
        for (Token* t = fs->bodyStart; t && t != fs->bodyEnd; t = t->next) {
            if (t->str != "=" || !t->astOp1 || !t->astOp1->varId || !t->astOp1->var || !t->astOp2)
                continue;
            const Variable* v = t->astOp1->var;
            if (!v->isLocal || !v->isPointer() || v->isStatic)
                continue;
            bool arr = false;
            if (!isNewExpr(t->astOp2, arr))
                continue;
            if (t->astParent)
                continue;
            const Token* se = statementEndOf(t);
            LeakScanner ls(c, v->varId, v->name, t->astOp2, arr);
            // scan rest of the variable's scope and up to function end
            const Scope* s = t->scope;
            const Token* start = se ? se->next : nullptr;
            AState st = AState::ALLOC;
            bool returned = false;
            while (s) {
                st = ls.scan(start, s->bodyEnd, st, returned);
                if (returned || st != AState::ALLOC)
                    break;
                if (s == v->scope || s == fs) {
                    ls.leak(s->bodyEnd);
                    break;
                }
                start = s->bodyEnd->next;
                s = s->nestedIn;
            }
        }
    }
}
