            const Token* se = statementEndOf(t);
            FwdResult fr = forwardAnalyze(t, se, v->varId, fs, false);
            if (fr.read || fr.bail)
                continue;
            if (v->isPointer()) {
                if (printWarning && p->str == "=")
                    c.report(t, Severity::warning, "uselessAssignmentPtrArg", "Assignment of function parameter has no effect outside the function. Did you forget dereferencing it?", 398);
            } else if (printStyle) {
                c.report(t, Severity::style, "uselessAssignmentArg", "Assignment of function parameter has no effect outside the function.", 398);
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Check function usage: missing return

static bool isNameCall(const Token* tok)
{
    return tok && tok->isName() && tok->next && tok->next->str == "(" && !tok->isKeyword();
}

static const Token* checkMissingReturnScope(const Token* tok)
{
    const Token* lastStatement = nullptr;
    while ((tok = tok->prev) != nullptr) {
        if (tok->str == ")")
            tok = tok->link;
        if (tok->str == "{")
            return lastStatement ? lastStatement : tok->next;
        if (tok->str == "}") {
            const Scope* sc = tok->scope;
            for (const Token* prev = tok->link->prev; prev && prev->scope == sc && !(prev->str == ";" || prev->str == "{" || prev->str == "}"); prev = prev->prev) {
                if (prev->str == "return" || prev->str == "throw")
                    return nullptr;
                if (prev->str == "goto")
                    return nullptr;
            }
            if (!sc)
                return nullptr;
            if (sc->type == Scope::eSwitch) {
                bool hasDefault = false;
                bool reachable = false;
                for (const Token* st = tok->link->next; st != tok; st = st->next) {
                    if (reachable && st->str == "break" && st->next && st->next->str == ";") {
                        if (st->prev && st->prev->str == "}" && !checkMissingReturnScope(st->prev))
                            reachable = false;
                        else
                            return st;
                    }
                    if (st->str == "return" || st->str == "throw")
                        reachable = false;
                    if (st->str == "case" || st->str == "default")
                        reachable = true;
                    if (st->str == "default" && st->next && st->next->str == ":")
                        hasDefault = true;
                    else if (st->str == "{" && st->scope && (st->scope->isLoop() || st->scope->type == Scope::eSwitch) && st->scope->bodyStart == st)
                        st = st->link;
                }
                if (!hasDefault)
                    return tok->link;
            } else if (sc->type == Scope::eIf) {
                const Token* condition = sc->condStart ? sc->condStart->astOp1 : nullptr;
                if (condition && condition->hasKnownIntValue() && condition->getKnownIntValue()->intvalue == 1)
                    return checkMissingReturnScope(tok);
                return tok;
            } else if (sc->type == Scope::eElse) {
                const Token* errorToken = checkMissingReturnScope(tok);
                if (errorToken)
                    return errorToken;
                tok = tok->link;
                if (tok->prev && tok->prev->str == "else" && tok->prev->prev && tok->prev->prev->str == "}")
                    return checkMissingReturnScope(tok->prev->prev);
                return tok;
            }
            return nullptr;
        }
        if (tok->str == "return" || tok->str == "throw")
            return nullptr;
        if (tok->str == "goto")
            return nullptr;
        if (isNameCall(tok))
            return nullptr;
        if (tok->prev && (tok->prev->str == ";" || tok->prev->str == "{" || tok->prev->str == "}") && tok->isName() && tok->next && tok->next->str == ":")
            return tok;
        if (tok->str == ";" && tok->next && tok->next->str != "}" && !lastStatement)
            lastStatement = tok->next;
    }
    return nullptr;
}

void checkMissingReturn(CheckContext& c)
{
    for (Scope* fs : c.tz.db.functionScopes) {
        const Function* f = fs->function;
        if (!f || f->returnsVoid || f->isConstructor || f->isDestructor)
            continue;
        if (f->name == "main")
            continue;
        // return type must exist
        if (f->retStart == f->tokenDef)
            continue;
        bool hasType = false;
        for (const Token* t = f->retStart; t && t != f->tokenDef; t = t->next)
            if (t->isName() && t->str != "static" && t->str != "inline" && t->str != "extern")
                hasType = true;
        if (!hasType)
            continue;
        bool isAuto = false;
        for (const Token* t = f->retStart; t && t != f->tokenDef; t = t->next)
            if (t->str == "auto")
                isAuto = true;
        if (isAuto)
            continue;
        const Token* errorToken = checkMissingReturnScope(fs->bodyEnd);
        if (errorToken)
            c.report(errorToken, Severity::error, "missingReturn", "Found an exit path from function with non-void return type that has missing return statement", 758);
    }
}

// ---------------------------------------------------------------------------
// Other: unreachable code

void checkUnreachableCode(CheckContext& c)
{
    if (!c.style())
        return;
    for (Scope* fs : c.tz.db.functionScopes) {
        for (const Token* t = fs->bodyStart; t && t != fs->bodyEnd; t = t->next) {
            if (!(t->str == "return" || t->str == "break" || t->str == "continue" || t->str == "throw" || t->str == "goto"))
                continue;
            if (t->prev && !(t->prev->str == ";" || t->prev->str == "{" || t->prev->str == "}" || t->prev->str == ":"))
                continue;
            const Token* se = statementEndOf(t);
            if (!se || se->str != ";")
                continue;
            const Token* n = se->next;
            if (!n || n->str == "}" || n->str == "case" || n->str == "default")
                continue;
            if (n->isName() && n->next && n->next->str == ":")
                continue;  // label
            if (n->str == "{" )
                continue;
            if (n->str == "break" && t->str == "return")
                continue;
            if (n->macro)
                continue;
            // inside switch: statements after break following case are fine
            c.report(n, Severity::style, "unreachableCode", "Statements following '" + t->str + "' will never be executed.", 561);
        }
    }
}

// ---------------------------------------------------------------------------
// Other: sign of unsigned

void checkSignOfUnsignedVariable(CheckContext& c)
{
    if (!c.style())
        return;
    for (Token* t = c.tz.list.front; t; t = t->next) {
        if (!t->isComparisonOp() || !t->astOp1 || !t->astOp2)
            continue;
        const Token* a = t->astOp1;
        const Token* b = t->astOp2;
        auto isUnsignedVar = [](const Token* x) {
            if (!x->varId || !x->var || x->var->isPointer() || x->var->isArray)
                return false;
            for (const Token* tt = x->var->typeStart; tt && tt != x->var->nameTok; tt = tt->next) {
                if (tt->str == "unsigned" || tt->str == "size_t" || tt->str == "uint8_t" || tt->str == "uint16_t" || tt->str == "uint32_t" || tt->str == "uint64_t")
                    return true;
            }
            return false;
        };
        auto isZero = [](const Token* x) { return x->isNumber() && (x->str == "0" || x->str == "0U" || x->str == "0u" || x->str == "0L"); };
        if (isUnsignedVar(a) && isZero(b)) {
            if (t->str == "<")
                c.report(t, Severity::style, "unsignedLessThanZero", "$symbol:" + a->str + "\nChecking if unsigned expression '$symbol' is less than zero.", 570);
            else if (t->str == ">=")
                c.report(t, Severity::style, "unsignedPositive", "$symbol:" + a->str + "\nUnsigned expression '$symbol' can't be negative so it is unnecessary to test it.", 570);
        } else if (isUnsignedVar(b) && isZero(a)) {
            if (t->str == ">")
                c.report(t, Severity::style, "unsignedLessThanZero", "$symbol:" + b->str + "\nChecking if unsigned expression '$symbol' is less than zero.", 570);
            else if (t->str == "<=")
                c.report(t, Severity::style, "unsignedPositive", "$symbol:" + b->str + "\nUnsigned expression '$symbol' can't be negative so it is unnecessary to test it.", 570);
        }
    }
}

// ---------------------------------------------------------------------------
// Other: shadow variables

void checkShadowVariables(CheckContext& c)
{
    if (!c.style())
        return;
    std::vector<const Variable*> vars;
    for (const Variable& v : c.tz.db.variables)
        if (v.isLocal && v.scope && v.scope->isExecutable())
            vars.push_back(&v);
    std::sort(vars.begin(), vars.end(), [](const Variable* a, const Variable* b) { return a->nameTok->index < b->nameTok->index; });
    for (const Variable* v : vars) {
        const Token* shadowed = nullptr;
        std::string kind;
        // enclosing scopes
        for (const Scope* s = v->scope->nestedIn; s && !shadowed; s = s->nestedIn) {
            for (const Variable* o : s->varlist) {
                if (o == v || o->name != v->name)
                    continue;
                if (o->nameTok->index > v->nameTok->index && !o->isGlobal)
                    continue;
                if (o->isMember)
                    continue;
                shadowed = o->nameTok;
                kind = o->isArgument ? "argument" : "variable";
                break;
            }
            if (s->type == Scope::eGlobal || s->type == Scope::eNamespace) {
                if (!shadowed) {
                    for (const Function* f : c.tz.db.functionList) {
                        if (f->name == v->name && f->nestedIn == s) {
                            shadowed = f->tokenDef;
                            kind = "function";
                            break;
                        }
                    }
                }
            }
            if (s->type == Scope::eFunction && s->function) {
                // arguments live in function scope
            }
        }
        if (!shadowed)
            continue;
        std::vector<std::pair<const Token*, std::string>> path;
        path.push_back({shadowed, "Shadowed declaration"});
        path.push_back({v->nameTok, "Shadow variable"});
        const std::string id = kind == "argument" ? "shadowArgument" : (kind == "function" ? "shadowFunction" : "shadowVariable");
        c.reportPath(path, Severity::style, id, "$symbol:" + v->name + "\nLocal variable '$symbol' shadows outer " + kind, 398);
    }
}

// ---------------------------------------------------------------------------
// String: literal compared with char*

void checkStringCompare(CheckContext& c)
{
    if (!c.warning())
        return;
    for (Token* t = c.tz.list.front; t; t = t->next) {
        if ((t->str != "==" && t->str != "!=") || !t->astOp1 || !t->astOp2)
            continue;
        const Token* var = nullptr;
        const Token* lit = nullptr;
        if (t->astOp1->isString() && t->astOp2->varId) { lit = t->astOp1; var = t->astOp2; }
        else if (t->astOp2->isString() && t->astOp1->varId) { lit = t->astOp2; var = t->astOp1; }
        if (!var || !var->var)
            continue;
        if (!(var->var->isPointer() || var->var->isArray))
            continue;
        if (var->var->isClassType)
            continue;
        (void)lit;
        c.report(t, Severity::warning, "literalWithCharPtrCompare", "$symbol:" + var->str + "\nString literal compared with variable '$symbol'. Did you intend to use strcmp() instead?", 595);
    }
}
