static const Token* checkMissingReturnScope(const Token* tok)
{
    const Token* lastStatement = nullptr;
    while ((tok = tok->prev) != nullptr) {
        if (tok->str == ")")
            tok = tok->link;
        if (tok->str == "{")
            return lastStatement ? lastStatement : tok->next;
        if (tok->str == "}") {
            const Scope* sc = tok->scope;
            for (const Token* prev = tok->link->prev; prev && prev->scope == sc && !(prev->str == ";" || prev->str == "{" || prev->str == "}"); prev = prev->prev) {
