        auto it = swapped.find(a->str);
        if (it != swapped.end() && it->second == b->str)
            return sameExprPublic(a->astOp1, b->astOp2) && sameExprPublic(a->astOp2, b->astOp1);
    }
    return false;
}

static bool oppositeCond(const Token* a, const Token* b)
{
    if (!a || !b)
        return false;
    if (a->str == "!" && a->isUnaryOp && sameExprPublic(a->astOp1, b))
        return true;
    if (b->str == "!" && b->isUnaryOp && sameExprPublic(b->astOp1, a))
        return true;
    if (!a->astOp1 || !a->astOp2 || !b->astOp1 || !b->astOp2)
        return false;
    static const std::map<std::string, std::string> opp = {{"==", "!="}, {"!=", "=="}, {"<", ">="}, {">=", "<"}, {">", "<="}, {"<=", ">"}};
    auto it = opp.find(a->str);
    if (it == opp.end())
        return false;
    if (b->str == it->second && sameExprPublic(a->astOp1, b->astOp1) && sameExprPublic(a->astOp2, b->astOp2))
        return true;
    // swapped operands: a: x < y, b: y <= x is opposite? (x<y) opposite (x>=y) == (y<=x)
    static const std::map<std::string, std::string> swapped = {{"<", ">"}, {">", "<"}, {"<=", ">="}, {">=", "<="}, {"==", "=="}, {"!=", "!="}};
    auto sw = swapped.find(it->second);
    if (sw != swapped.end() && b->str == sw->second && sameExprPublic(a->astOp1, b->astOp2) && sameExprPublic(a->astOp2, b->astOp1))
        return true;
