}

static void collectVars(const Token* t, std::set<int>& out)
{
    if (!t) return;
    if (t->varId) out.insert(t->varId);
    collectVars(t->astOp1, out);
    collectVars(t->astOp2, out);
}

static bool hasSideEffectsOrCalls(const Token* t)
{
    if (!t) return false;
    if (t->isIncDec() || t->isAssignmentOp())
        return true;
    if (t->str == "(" && !t->isCast)
        return true;
    return hasSideEffectsOrCalls(t->astOp1) || hasSideEffectsOrCalls(t->astOp2);
}

static bool isModifiedIn(const Token* start, const Token* end, const std::set<int>& vars)
{
    for (const Token* t = start; t && t != end; t = t->next) {
        if (!t->varId || !vars.count(t->varId))
            continue;
        const Token* p = t->astParent;
        if (p && ((p->isAssignmentOp() && p->astOp1 == t) || p->isIncDec() || (p->str == "&" && p->isUnaryOp)))
            return true;
        if (p && (p->str == "(" || p->str == ",") && !p->isCast) {
            // passed to function: may be modified (pointers / C++ refs)
            if (t->var && (t->var->isPointer() || t->var->isArray))
                return true;
        }
    }
    // function calls may modify globals
    return false;
}

static const Token* ifCond(const Scope* s)
{
    return s && s->condStart ? s->condStart->astOp1 : nullptr;
}

static bool blockExits(const Token* open)
{
    if (!open || !open->link)
        return false;
    const Token* last = open->link->prev;
    if (!last || last->str != ";")
        return false;
    const Token* t = last->prev;
    while (t && t != open && t->str != ";" && t->str != "{" && t->str != "}") {
        if (t->str == ")" || t->str == "]")
            t = t->link;
        t = t->prev;
    }
    const Token* s = t ? t->next : nullptr;
    return s && (s->str == "return" || s->str == "throw" || (s->str == "exit" && s->next && s->next->str == "("));
}

static void duplicateCondition(CheckContext& c)
{
    if (!c.style())
        return;
    for (Scope& sc : c.tz.db.scopes) {
        if (sc.type != Scope::eIf)
            continue;
        const Token* close = sc.bodyEnd;
        if (close->next && close->next->str == "else")
            continue;
        const Token* nxt = close->next;
        if (!nxt || nxt->str != "if" || !nxt->next || nxt->next->str != "(")
            continue;
        const Token* c1 = ifCond(&sc);
        const Token* c2 = nxt->next->astOp1;
        if (!c1 || !c2 || hasSideEffectsOrCalls(c1))
            continue;
        if (!sameExprPublic(c1, c2))
            continue;
        if (blockExits(sc.bodyStart))
            continue;
        std::set<int> vars;
        collectVars(c1, vars);
        if (isModifiedIn(sc.bodyStart, sc.bodyEnd, vars))
            continue;
        std::vector<std::pair<const Token*, std::string>> path;
        path.push_back({c1, "First condition"});
        path.push_back({c2, "Second condition"});
        c.reportPath(path, Severity::style, "duplicateCondition", "The if condition is the same as the previous if condition", 398);
    }
}

static void multiCondition(CheckContext& c)
{
    if (!c.style())
        return;
    for (Scope& sc : c.tz.db.scopes) {
        if (sc.type != Scope::eIf)
            continue;
        // only first if of a chain
        const Token* kw = sc.classDef;
        if (kw && kw->prev && kw->prev->str == "else")
            continue;
        if (kw && kw->prev && kw->prev->str == "{" && kw->prev->prev && kw->prev->prev->str == "else" && kw->prev->isVirtual)
            continue;
        std::vector<const Token*> conds;
        const Token* c1 = ifCond(&sc);
        if (!c1 || hasSideEffectsOrCalls(c1))
            continue;
        conds.push_back(c1);
        const Scope* cur = &sc;
        while (cur) {
            const Token* close = cur->bodyEnd;
            if (!close->next || close->next->str != "else")
                break;
            const Token* e = close->next->next;
            const Token* ifTok = nullptr;
            if (e && e->str == "if")
                ifTok = e;
            else if (e && e->str == "{" && e->next && e->next->str == "if") {
                // else { if (...) ... } where the if is the only statement
                const Token* inner = e->next;
                const Token* innerBody = inner->next->link->next;
                const Token* innerEnd = innerBody && innerBody->str == "{" ? innerBody->link : nullptr;
                if (innerEnd && innerEnd->next == e->link)
                    ifTok = inner;
            }
            if (!ifTok)
                break;
            const Token* cc = ifTok->next->astOp1;
            const Scope* nextScope = ifTok->next->link->next ? ifTok->next->link->next->scope : nullptr;
            if (cc) {
                for (const Token* prevCond : conds) {
                    if (sameCond(prevCond, cc)) {
                        c.report(cc, Severity::style, "multiCondition",
                                 "Expression is always false because 'else if' condition matches previous condition at line " + std::to_string(prevCond->line) + ".", 398);
                        break;
                    }
                }
                conds.push_back(cc);
            }
            if (!nextScope || nextScope->type != Scope::eIf || nextScope->bodyStart != ifTok->next->link->next)
                break;
            cur = nextScope;
        }
    }
}

static void multiCondition2(CheckContext& c)
