cd /workspace/src; cat > checkcond.cpp <<'EOF'
#include "checks.h"
#include "fwd.h"
#include <set>
#include <functional>
#include <climits>

bool sameExprPublic(const Token* a, const Token* b);

static bool sameCond(const Token* a, const Token* b)
{
    if (sameExprPublic(a, b))
        return true;
    // commutative comparisons
    if (a && b && a->astOp1 && a->astOp2 && b->astOp1 && b->astOp2) {
        if ((a->str == "==" || a->str == "!=") && a->str == b->str)
            return sameExprPublic(a->astOp1, b->astOp2) && sameExprPublic(a->astOp2, b->astOp1);
        static const std::map<std::string, std::string> swapped = {{"<", ">"}, {">", "<"}, {"<=", ">="}, {">=", "<="}};
        auto it = swapped.find(a->str);
        if (it != swapped.end() && it->second == b->str)
            return sameExprPublic(a->astOp1, b->astOp2) && sameExprPublic(a->astOp2, b->astOp1);
    }
    return false;
}

static bool oppositeCond(const Token* a, const Token* b)
{
    if (!a || !b)
        return false;
    if (a->str == "!" && a->isUnaryOp && sameExprPublic(a->astOp1, b))
        return true;
    if (b->str == "!" && b->isUnaryOp && sameExprPublic(b->astOp1, a))
        return true;
    if (!a->astOp1 || !a->astOp2 || !b->astOp1 || !b->astOp2)
        return false;
    static const std::map<std::string, std::string> opp = {{"==", "!="}, {"!=", "=="}, {"<", ">="}, {">=", "<"}, {">", "<="}, {"<=", ">"}};
    auto it = opp.find(a->str);
    if (it == opp.end())
        return false;
    if (b->str == it->second && sameExprPublic(a->astOp1, b->astOp1) && sameExprPublic(a->astOp2, b->astOp2))
        return true;
    // swapped operands: a: x < y, b: y <= x is opposite? (x<y) opposite (x>=y) == (y<=x)
    static const std::map<std::string, std::string> swapped = {{"<", ">"}, {">", "<"}, {"<=", ">="}, {">=", "<="}, {"==", "=="}, {"!=", "!="}};
    auto sw = swapped.find(it->second);
    if (sw != swapped.end() && b->str == sw->second && sameExprPublic(a->astOp1, b->astOp2) && sameExprPublic(a->astOp2, b->astOp1))
        return true;
    return false;
}

static void collectVars(const Token* t, std::set<int>& out)
{
    if (!t) return;
    if (t->varId) out.insert(t->varId);
    collectVars(t->astOp1, out);
    collectVars(t->astOp2, out);
}

static bool hasSideEffectsOrCalls(const Token* t)
{
    if (!t) return false;
    if (t->isIncDec() || t->isAssignmentOp())
        return true;
    if (t->str == "(" && !t->isCast)
        return true;
    return hasSideEffectsOrCalls(t->astOp1) || hasSideEffectsOrCalls(t->astOp2);
}

static bool isModifiedIn(const Token* start, const Token* end, const std::set<int>& vars)
{
    for (const Token* t = start; t && t != end; t = t->next) {
        if (!t->varId || !vars.count(t->varId))
            continue;
        const Token* p = t->astParent;
        if (p && ((p->isAssignmentOp() && p->astOp1 == t) || p->isIncDec() || (p->str == "&" && p->isUnaryOp)))
            return true;
        if (p && (p->str == "(" || p->str == ",") && !p->isCast) {
            // passed to function: may be modified (pointers / C++ refs)
            if (t->var && (t->var->isPointer() || t->var->isArray))
                return true;
        }
    }
    // function calls may modify globals
    return false;
}

static const Token* ifCond(const Scope* s)
{
    return s && s->condStart ? s->condStart->astOp1 : nullptr;
}

static bool blockExits(const Token* open)
{
    if (!open || !open->link)
        return false;
    const Token* last = open->link->prev;
    if (!last || last->str != ";")
        return false;
    const Token* t = last->prev;
    while (t && t != open && t->str != ";" && t->str != "{" && t->str != "}") {
        if (t->str == ")" || t->str == "]")
            t = t->link;
        t = t->prev;
    }
    const Token* s = t ? t->next : nullptr;
    return s && (s->str == "return" || s->str == "throw" || (s->str == "exit" && s->next && s->next->str == "("));
}

static void duplicateCondition(CheckContext& c)
{
    if (!c.style())
        return;
    for (Scope& sc : c.tz.db.scopes) {
        if (sc.type != Scope::eIf)
            continue;
        const Token* close = sc.bodyEnd;
        if (close->next && close->next->str == "else")
            continue;
        const Token* nxt = close->next;
        if (!nxt || nxt->str != "if" || !nxt->next || nxt->next->str != "(")
            continue;
        const Token* c1 = ifCond(&sc);
        const Token* c2 = nxt->next->astOp1;
        if (!c1 || !c2 || hasSideEffectsOrCalls(c1))
            continue;
        if (!sameExprPublic(c1, c2))
            continue;
        if (blockExits(sc.bodyStart))
            continue;
        std::set<int> vars;
        collectVars(c1, vars);
        if (isModifiedIn(sc.bodyStart, sc.bodyEnd, vars))
            continue;
        std::vector<std::pair<const Token*, std::string>> path;
        path.push_back({c1, "First condition"});
        path.push_back({c2, "Second condition"});
        c.reportPath(path, Severity::style, "duplicateCondition", "The if condition is the same as the previous if condition", 398);
    }
}

static void multiCondition(CheckContext& c)
{
    if (!c.style())
        return;
    for (Scope& sc : c.tz.db.scopes) {
        if (sc.type != Scope::eIf)
            continue;
        // only first if of a chain
        const Token* kw = sc.classDef;
        if (kw && kw->prev && kw->prev->str == "else")
            continue;
        if (kw && kw->prev && kw->prev->str == "{" && kw->prev->prev && kw->prev->prev->str == "else" && kw->prev->isVirtual)
            continue;
        std::vector<const Token*> conds;
        const Token* c1 = ifCond(&sc);
        if (!c1 || hasSideEffectsOrCalls(c1))
            continue;
        conds.push_back(c1);
        const Scope* cur = &sc;
        while (cur) {
            const Token* close = cur->bodyEnd;
            if (!close->next || close->next->str != "else")
                break;
            const Token* e = close->next->next;
            const Token* ifTok = nullptr;
            if (e && e->str == "if")
                ifTok = e;
            else if (e && e->str == "{" && e->next && e->next->str == "if") {
                // else { if (...) ... } where the if is the only statement
                const Token* inner = e->next;
                const Token* innerBody = inner->next->link->next;
                const Token* innerEnd = innerBody && innerBody->str == "{" ? innerBody->link : nullptr;
                if (innerEnd && innerEnd->next == e->link)
                    ifTok = inner;
            }
            if (!ifTok)
                break;
            const Token* cc = ifTok->next->astOp1;
            const Scope* nextScope = ifTok->next->link->next ? ifTok->next->link->next->scope : nullptr;
            if (cc) {
                for (const Token* prevCond : conds) {
                    if (sameCond(prevCond, cc)) {
                        c.report(cc, Severity::style, "multiCondition",
                                 "Expression is always false because 'else if' condition matches previous condition at line " + std::to_string(prevCond->line) + ".", 398);
                        break;
                    }
                }
                conds.push_back(cc);
            }
            if (!nextScope || nextScope->type != Scope::eIf || nextScope->bodyStart != ifTok->next->link->next)
                break;
            cur = nextScope;
        }
    }
}

static void multiCondition2(CheckContext& c)
{
    if (!c.warning())
        return;
    for (Scope& sc : c.tz.db.scopes) {
        if (sc.type != Scope::eIf)
            continue;
        const Token* c1 = ifCond(&sc);
        if (!c1 || hasSideEffectsOrCalls(c1))
            continue;
        std::set<int> vars;
        collectVars(c1, vars);
        if (vars.empty())
            continue;
        // inner conditions
        for (const Token* t = sc.bodyStart->next; t && t != sc.bodyEnd; t = t->next) {
            if (t->str == "if" && t->next && t->next->str == "(" && t->next->astOp1) {
                const Token* c2 = t->next->astOp1;
                if (isModifiedIn(sc.bodyStart, t, vars))
                    break;
                bool calls = false;
                for (const Token* x = sc.bodyStart; x != t; x = x->next)
                    if (x->str == "(" && x->astOp1 && !x->isCast && x->astOp1->isName() && !x->astOp1->varId) {
                        for (int v : vars) {
                            const Variable* var = c.tz.db.getVariable(v);
                            if (var && (var->isGlobal || var->isStatic))
                                calls = true;
                        }
                    }
                if (calls)
                    break;
                if (sameExprPublic(c1, c2)) {
                    std::vector<std::pair<const Token*, std::string>> path;
                    path.push_back({c1, "outer condition: " + exprString(c1)});
                    path.push_back({c2, "identical inner condition: " + exprString(c2)});
                    c.reportPath(path, Severity::warning, "identicalInnerCondition", "Identical inner 'if' condition is always true.", 398);
                } else if (oppositeCond(c1, c2)) {
                    std::vector<std::pair<const Token*, std::string>> path;
                    path.push_back({c1, "outer condition: " + exprString(c1)});
                    path.push_back({c2, "opposite inner condition: " + exprString(c2)});
                    c.reportPath(path, Severity::warning, "oppositeInnerCondition", "Opposite inner 'if' condition leads to a dead code block.", 398);
                }
                break;
            }
            if (t->str == "{" && t->link && t->scope && t->scope->bodyStart == t)
                break;
        }
        // early exit
        if (!blockExits(sc.bodyStart))
            continue;
        const Token* after = sc.bodyEnd->next;
        if (after && after->str == "else" && after->next && after->next->str == "if")
            after = after->next;
        else if (after && after->str == "else")
            continue;
        for (const Token* t = after; t && t != sc.nestedIn->bodyEnd; t = t->next) {
            if (t->str == "if" && t->next && t->next->str == "(" && t->next->astOp1) {
                const Token* c2 = t->next->astOp1;
                if (sameExprPublic(c1, c2)) {
                    const std::string e = exprString(c1);
                    std::vector<std::pair<const Token*, std::string>> path;
                    path.push_back({c1, "If condition '" + e + "' is true, the function will return/exit"});
                    path.push_back({c2, "Testing identical condition '" + e + "'"});
                    c.reportPath(path, Severity::warning, "identicalConditionAfterEarlyExit", "$symbol:" + e + "\nIdentical condition '$symbol', second condition is always false", 398);
                }
                break;
            }
            if (t->varId && vars.count(t->varId)) {
                const Token* p = t->astParent;
                if (p && ((p->isAssignmentOp() && p->astOp1 == t) || p->isIncDec() || (p->str == "&" && p->isUnaryOp)))
                    break;
            }
            if (t->str == "{" && t->link && t->scope && t->scope->bodyStart == t && t->scope->type != Scope::eElse)
                break;
            if (t->str == "{" && t->link && t->scope && t->scope->type == Scope::eElse)
                ;
        }
    }
}

// interval logic
namespace {
struct Cmp {
    std::string op;
    long long n;
    bool contains(long long x) const {
        if (op == "==") return x == n;
        if (op == "!=") return x != n;
        if (op == "<") return x < n;
        if (op == "<=") return x <= n;
        if (op == ">") return x > n;
        if (op == ">=") return x >= n;
        return false;
    }
};
}

static bool parseLiteral(const Token* t, long long& v)
{
    if (!t)
        return false;
    bool neg = false;
    if (t->str == "-" && t->isUnaryOp && t->astOp1) {
        neg = true;
        t = t->astOp1;
    }
    if (!t->isNumber())
        return false;
    std::string s = t->str;
    if (s.find_first_of(".eE") != std::string::npos && s.find_first_of("xX") == std::string::npos)
        return false;
    char* end;
    v = std::strtoll(s.c_str(), &end, 0);
    if (neg) v = -v;
    return true;
}

static bool toCmp(const Token* t, int& varId, Cmp& cmp, std::string& text)
{
    if (!t || !t->isComparisonOp() || !t->astOp1 || !t->astOp2)
        return false;
    long long n;
    if (t->astOp1->varId && !t->astOp1->astOp1 && parseLiteral(t->astOp2, n)) {
        varId = t->astOp1->varId;
        cmp.op = t->str;
        cmp.n = n;
    } else if (t->astOp2->varId && !t->astOp2->astOp1 && parseLiteral(t->astOp1, n)) {
        varId = t->astOp2->varId;
        static const std::map<std::string, std::string> sw = {{"<", ">"}, {">", "<"}, {"<=", ">="}, {">=", "<="}, {"==", "=="}, {"!=", "!="}};
        cmp.op = sw.at(t->str);
        cmp.n = n;
    } else
        return false;
    text = exprString(t->astOp1) + " " + t->str + " " + exprString(t->astOp2);
    return true;
}

static void checkIncorrectLogicOperator(CheckContext& c)
{
    const bool printStyle = c.style();
    const bool printWarning = c.warning();
    if (!printStyle && !printWarning)
        return;
    for (Token* t = c.tz.list.front; t; t = t->next) {
        if (t->str != "&&" && t->str != "||")
            continue;
        int v1 = 0, v2 = 0;
        Cmp a, b;
        std::string ta, tb;
        if (!toCmp(t->astOp1, v1, a, ta) || !toCmp(t->astOp2, v2, b, tb) || v1 != v2)
            continue;
        const Variable* var = c.tz.db.getVariable(v1);
        if (var && var->isFloat())
            continue;
        std::set<long long> pts = {LLONG_MIN / 2, LLONG_MAX / 2};
        for (long long n : {a.n, b.n})
            for (long long d = -1; d <= 1; ++d)
                pts.insert(n + d);
        bool anyBoth = false, allEither = true, aSubB = true, bSubA = true, equal = true;
        for (long long x : pts) {
            const bool ia = a.contains(x), ib = b.contains(x);
            if (ia && ib) anyBoth = true;
            if (!ia && !ib) allEither = false;
            if (ia && !ib) aSubB = false;
            if (ib && !ia) bSubA = false;
            if (ia != ib) equal = false;
        }
        if (equal)
            continue;
        if (t->str == "&&") {
            if (!anyBoth) {
                if (printWarning)
                    c.report(t, Severity::warning, "incorrectLogicOperator", "Logical conjunction always evaluates to false: " + ta + " && " + tb + ".", 571);
            } else if (printStyle && (aSubB || bSubA)) {
                const std::string red = aSubB ? tb : ta;
                const std::string suf = aSubB ? ta : tb;
                c.report(t, Severity::style, "redundantCondition", "Redundant condition: The condition '" + red + "' is redundant since '" + suf + "' is sufficient.", 398);
            }
        } else {
            if (allEither) {
                if (printWarning)
                    c.report(t, Severity::warning, "incorrectLogicOperator", "Logical disjunction always evaluates to true: " + ta + " || " + tb + ".", 571);
            } else if (printStyle && (aSubB || bSubA)) {
                const std::string red = aSubB ? ta : tb;
                const std::string suf = aSubB ? tb : ta;
                c.report(t, Severity::style, "redundantCondition", "Redundant condition: The condition '" + red + "' is redundant since '" + suf + "' is sufficient.", 398);
            }
        }
    }
}

void runConditionChecks(CheckContext& c)
{
    duplicateCondition(c);
    multiCondition(c);
    multiCondition2(c);
    checkIncorrectLogicOperator(c);
}
